		heart_chain5 = "深空之眼医疗部曾经为奥西里斯进行过人格分离的手术，试图帮助她消除掉潜在的冥王人格。虽然奥西里斯的态度比较犹豫，但最终还是同意了配合手术。\n有隐科组的理论支持，还有弥芙尔率领的最先进的医疗智械，手术的前半程很顺利，但在后半阶段，手术却因不明原因停止了。\n关于这场手术的细节，主治人员还有休都闭口不谈，在手术报告上也没有任何说明。只是之后，再也没有人提过对奥西里斯进行人格切割治疗的事了。",
		heart_chain1 = "初见时只是一个身材娇小、性格温柔的孩子，让人很难想象这么娇弱的身躯居然可以和视骸战斗。\n但奥西里斯用自己的努力证明了自己，她成功通过了各项严苛的考试，和薇儿丹蒂一起成为了新人班的成员。\n「奥西里斯对待每项任务都拼尽全力，常常让我担心她会不会努力过了头」\n不同于对待薇儿丹蒂的严厉态度，休在提到奥西里斯时总是露出欣慰、却又带有些许担忧的表情。\n由于其讨人喜欢的性格，奥西里斯也是总部里人缘最好的修正者。\n她对待所有人都很温柔，会在发现同伴的困扰后，尽己所能地悄悄送上帮助，将同伴的事情永远摆在第一位，也因此被大家亲切地称呼为「小奥西里斯」。",
		plot_tip = "管理员，马上就要作战训练考核了，感觉，有些紧张……可以指导我一下么？",
