		cv_ja = "大和田仁美",
		heart_chain2 = "作为深空之眼新人小队的一员，奥西里斯其实加入组织的时间比绝大多数人要早。\n她在刚加入深空之眼的训练中支援同伴、消灭视骸，表现出和柔弱外表截然不同的作战能力，这大大出乎了队员们的意料。组织里的所有人都欣然注视着这个孩子的成长，希望她能成长为深空之眼次时代的中坚力量，但意想不到的变故却在此时发生了。\n深空之眼从源层的一处重侵蚀区检测到权钥信号，并派出月读和海拉前往搜查。搜寻行动收获了一柄无归属的上古权钥，分析后发现上面记录着属于奥西里斯的神格。\n能驾驭两件权钥就可以大大提升作战能力，一心想要成同伴助力的奥西里斯开始不分昼夜地练习，终于逐渐能开始掌握权钥中的力量。\n但很快大家便发现，使用第二把权钥的奥西里斯变强了，性格却也变得越来越好战和嗜杀。这种性格的变化在两件权钥切换时表现得尤为明显，且此前从未有过先例。直到医疗部对奥西里斯进行全面检查，才发现存在于她体内的第二人格已经完全形成了……",
		organization = "深空之眼",
		heart_chain4 = "奥西里斯知道冥王的存在，但没有人格转换时的记忆，因此常常担心自己是不是在无经意间伤害了别人。\n为了解决奥西里斯的担忧，又为了能够准确预测冥王是否出现。隐科组对奥西里斯进行了实验，最后得到了较为准确的结论。\n目前已知的冥王人格出现方式有：\n(1)当奥西里斯受到生命危险时——不过这种状况的判定方式极不稳定，冥王人格出现的概率只有一半左右，隐科组推测这可能是冥王人格对「真正危险」的判断力产生了变化。\n(2)直接使用「生魂」权钥，或者来到骸能极为强烈的环境。\n(3)当奥西里斯的精神或是身体状态异常时——如受伤和生病，或是恐惧和愤怒等情绪达到某种极端后，便会引发冥王人格的出现。",
		heart_chain3 = "「冥王。」\n那个被绿色鬼火包裹的少女如此自称道，明明长着和奥西里斯一模一样的脸，却拥有一双象征杀戮和死亡的赤色瞳孔。\n只要召唤出奥西里斯的第二件权钥，嗜杀的人格就会不受控制地出现，然后不分敌我地发泄那股要收割一切的杀意。\n不仅如此，医疗部还发现冥王人格的意识正在慢慢侵占主导地位，如果继续使用第二权钥「生魂」，势必让奥西里斯的人格被冥王完全取代。于是奥西里斯的作战科职员证被紧急吊销，并被收容进医疗部治疗……\n两个月的治疗期结束，奥西里斯的里人格虽然被暂时压制，但为了安全起见，奥西里斯并没有恢复新人班队员的身份。这个观察期没有设定期限，让奥西里斯成为了闲置收留人员中的一员。",
