		name = "白泽",
		id = 1012,
		heart_chain5 = "尚未转正时，白泽跟随着一位仰慕的前辈实习。某次任务中，出现了脱离了重大犯罪对策部管理范畴的突发事件。同队的其他成员不顾劝阻，违反科尔盖规定脱离队伍进行支援，反而同样陷入危机。关键时刻，前辈及时赶到为他们挡下一击，以重伤为代价为队员争取了逃跑的时间。虽然最后前辈脱离生命危险，但也因为揽下了所有问题被判断为失职，被迫离开部门。\n「假如当时队员们遵守规定，一切都会如常。」正是从此开始，白泽对「规则」的态度，由「尊重」升格为了「笃信」。\n在白泽成为行动组长半个月后，她手下的队员就已经彻底更换了一批：一部分队员因无法忍受白泽严苛的规章而离开，更多的一部分，则因违反了规章而被白泽开除。\n「情感、道德的主观判断，都会因个体的差异而受到影响，唯有公允的规则是最优解。难道你们想用自己浅薄的阅历和片面的理解，来挑战数代甚至数十代人验证的准则？」\n将陆吾从执法部门中永久除名后，白泽变得更为冷酷和凶狠，行动专员之间开始流传出对她「恶魔」和「鬼神」的称呼。\n她相信，唯有凶狠强硬，才能保证队员对规则的绝对遵从。软弱和善只会使人认为存在斡旋的余地，得寸进尺，以至酿成大错。\n看着队员愤懑的神情和离去的背影，她并非没有对自己的做法动摇过。但她仍然选择坚持原则，只因不想再重蹈覆辙。\n虽然看上去冷酷无情，白泽事实上极富责任感。她严厉的行为将下属限定在规则的框架之内，某种程度上减少了他们受到伤害的可能。\n假如遇到危险的情况，白泽必然会像那时的前辈一样，以保护队员为最优先。\n当然，若是因违规而身陷险地，被救下的队员绝不会被继续留在白泽的队伍中。",
		heart_chain1 = "幼年的白泽曾被称为「神童」，与生俱来的过目不忘的能力，使得她连连跳级，12岁便进入某所大学的数学系进修。\n白泽在觉醒后即被科尔盖招募，凭借着自身的学习天赋，从未接触过战斗的白泽很快具备了较高的作战能力，进入重大犯罪对策部，代号「白」。\n极强的记忆力为白泽的工作带来了极大便利。她能清晰地记住每名罪犯的面容，以及他们惯用的攻击方式。每一次行动的过程细节，也都印刻在她的记忆里。因此对白泽而言，每一场实战都有着独特的学习价值。\n每当案件结束，白泽都会念出相应的条律依据以作结。\n「根据公共安全条例第十二条，你蓄意破坏公共交通设施，并已造成严重后果，故现将你缉拿归案。」\n细心的队员可能会发现，唯有在这话音落时，平日里板着脸的组长的嘴角才会出现一个轻微的弧度。",
		plot_tip = "",
