		cv_ja = "林鼓子",
		heart_chain2 = "摒弃一切不必要的人际关系，是白泽的社交准则。\n进入科尔盖的最初，白泽被安排在塞赫麦特麾下。然而，塞赫麦特散漫的态度令白泽感到不满。与惧怕塞赫麦特的其他队员不同，白泽主动向塞赫麦特提出意见，后者自然未予理睬。于是白泽向上提出单独带队的申请。鉴于她一直以来的优秀表现，她的申请得到批准，因此，她也成为了外表最年轻的行动组长，且与塞赫麦特并列成为重大犯罪对策部中无人敢招惹的存在——科尔盖中常会有这两人关系恶劣的传言。\n在此之后，白泽在虚恒的工作中认识了尚未觉醒的陆吾。陆吾的阳光、乐于助人，以及总是不听劝告地揉乱她头发的自来熟行为，让白泽紧绷的神经偶有放松的时间。两人经常一同执行任务，成为了默契的搭档。\n然而在一次营救任务中，陆吾无视撤退命令继续营救目标，这一越界行为将两人的分歧激化到了无可弥合的地步。白泽并没有过多犹豫，上报事件经过并判断陆吾不应继续留任公安部门，并彻底与陆吾断绝友情往来。\n虽然白泽通过科尔盖的工作积累了不少人脉，但她至今没有朋友。陆吾或许是唯一能称得上是她朋友的人，然而这也已成为过去。\n白泽本人并不在乎自己是否有朋友。独身一人做事，也就无人干扰自己的选择，她觉得这样十分自在。\n而且，「无牵无挂」也意味着，自己的离开不会为任何人在情感上造成负担。\n只是她自己这样认为而已。",
		organization = "科尔盖",
		heart_chain4 = "或许只是无意义的强迫症，抑或是笃信规则的「后遗症」，白泽在一些方面有着特别的仪式感。\n每日睡前，白泽会将窗边的相框放到桌上，又在清晨将它放回窗边。这一习惯来自于她的大学时期。\n虽然以「神童」的光环满怀信心地填报了数学系，但只是长于记忆的她并不擅长运用缜密的逻辑推断，成绩糟糕到了难以毕业的程度。某天她将相框放到窗边，走出门时由窗外见到，于是一时兴起向相框道了别。那天考试的科目是她唯一及格的一科。于是，窗边的相框成了某种好运的象征。\n如今白泽不会再为学业忧愁，但她仍然习惯于每日移动相框，似乎拿起和放下相框的时候，自己的心境就能回到遥远的学生时期，变得纯粹而平和——不过也仅限于那一刻。走出门后，白泽仍是那令人生畏的「鬼神」。\n至于相框中的内容，则是一片空白。由于使用的是老式相纸，其上的图案已在长久的年岁中减淡消失。\n除此之外，在执行任务前，白泽会以指尖代笔，将任务内容在手心写上一遍，然后紧握手心。她第一次这样做时，任务进行得格外顺利，于是这个小小的习惯被保留下来。这仪式感对白泽而言，似乎已经成为某种祈福，或单纯是缓解紧张的心理安慰，不过她并不会承认这一点。\n重大犯罪对策部的任务大多危险而难料生死，假如自己不幸在此次任务中殉职，那么白泽这小小的仪式感，亦是在构建自己死亡的意义。",
		heart_chain3 = "没有人见过白泽摘下眼罩的样子。毕竟身在重大犯罪对策部，独眼，或者说伤痕，反是一种功勋的证明，因此大家并不会特地关注这一点。\n然而不为人知的真相是，白泽眼罩下的眼睛，其实完好无损。\n身为修正者，白泽可以通过汇聚神力，展开第三只眼「明照」。通过这超出常理的第三只眼睛，白泽能够更清晰地看到敌人的动作，乃至更大的全局情形，为战斗创造优势。\n最初使用这一能力时，白泽欣喜于它带来的清晰视界，一时头脑恍惚，撞上了街边的路灯。\n回过神后她意识到，同时透过三只眼睛观察外界会使得眼前的景象产生重影，导致她晕头转向。在第七次因此撞上门框之后，白泽选择用眼罩将自己的右眼遮上。\n此外，白泽也对自己戴着眼罩的造型很是满意——因为这样会使得自己的外表看起来更有威慑力。",
