		heart_chain5 = "梵天将阿修罗带回了弥楼衍并告诉她，只有自己的强大才能在混乱中站稳脚跟。梵天的这番话加上自己对她那份强大的憧憬，使得阿修罗萌生了想成为世界最强的想法，并开始锻炼起自己。\n一开始只是在夏什瓦特的地下拳场挑战，渐渐的她开始不满足于这样的战斗，在听说了其他原质区的强者传闻后踏上了旅程。\n不过只有阿修罗自己最清楚，哪怕成为了世界最强，也只是迈出了追赶梵天背影的第一步。",
