		heart_chain5 = "塞赫麦特使人望尘莫及的能力，使得她能轻松解决任何重大案件，于是一切都变得索然无味。她自认看穿一切，认为人类文明无趣至极。\n而唯一引起她兴趣的，是能短暂将意识剥离无趣现实的酒精。那段时间，她几乎成为了酒不离身的人。\n直到某天，塞赫麦特被安排支援一场即将袭来的骸震。然而那天她照例喝得酩酊大醉。等到她终于被第二十九通电话叫醒时，太阳早已西斜，窗外远处的城区升起了滚滚浓烟。\n她带着一丝愧疚飞速赶到了骸震现场。她只认为自己的懒散终于把事情搞砸了一次，但她也认为自己还有补救的机会。\n然而骸震早已结束，人们拼力奋战，在塞赫麦特缺席的情况下战胜了灾难——以上百名行动专员和普通市民的生命为代价。\n塞赫麦特在灾区奔走许久，发现偌大的救灾现场竟一时找不出合适她的位置。她忽然明白，她作为一名修正者，并不是人类文明存续的「前提」，而是人类文明存续的「结果」。\n她本是人类文明跨越数次灾难后形成的那层愈发坚硬的护甲。\n而即使没有这层护甲，文明也还是鲜血淋漓地再一次战胜灾难。\n因为骸震被成功解决，也考虑到塞赫麦特惯常的行事风格，科尔盖高层并没有对塞赫麦特下达严厉处分。\n但那是塞赫麦特最后一次缺勤，也是同事们最后一次从她身上闻到酒味。从那以后塞赫麦特开始厌恶所有沾有酒精的事物。\n一年的进修期结束后，塞赫麦特带着医学和心理学的专业学位重返工作岗位，在她的要求下，科尔盖高层将她调到了骸震对策部。她一如往常那样性感而又疯癫，依旧令人捉摸不透，但很多人都隐约察觉到她塞赫麦特身上发生了某种坚定的改变。\n她似乎更优秀了，她也似乎不再那么优秀了，但她并不在乎。似乎这份工作本身，重新变成了她的追求。",
		heart_chain1 = "假如塞赫麦特说你的身上「很臭」，先别急着回忆自己上一次洗澡是在什么时候。\n事实上她并不在乎身边人的卫生习惯，她只是厌恶某种人们喜闻乐见的饮品所散发出来的气味——酒。\n塞赫麦特讨厌酒，以及其他一切与酒有关的事物，这在科尔盖内人尽皆知。不过其中原由鲜有人知晓，鉴于她疯癫的性格，也无人敢问。\n与之相对的，塞赫麦特喜欢喝茶，她的办公室里甚至特别划出了一块区域用于茶艺。平日里举止跳脱的她，在品茶时仿佛开启了省电模式。\n平静下来，然后用清醒的头脑行疯狂之事——她乐在其中。",
		plot_tip = "",
		cv_ko = "김연우",
		like = "茶艺",
		super_plot_tip = "",
		plot_tip_picture = "1015",
		cv_en = "Brittany Cox",
		age_en = "",
		cv_zh = "昱头",
		cv_ja = "藤原夏海",
		heart_chain2 = "被带到重大犯罪对策部的犯人，一般会经历以下心路历程：被捕时趾高气扬，拒不服从；来到气氛压抑的审讯室，心生惧意；见到负责审讯的塞赫麦特，两眼放光……\n然后，脸上的表情开始快速更替、扭曲，最后凝固。由塞赫麦特审讯的每一个犯人，最后都会以一副麻木的表情承认自己的罪行，有时甚至将未被调查到的部分也和盘托出。\n审讯室的监控证明，塞赫麦特从不在审讯中使用暴力。相反，她的神情温和，也几乎没有什么肢体动作。\n一般审讯室的监控都会附带录音，唯独塞赫麦特在场时，录音信号会被好心人中断。\n「这是为了大家健康的精神状态考虑……我可不希望犯人以外的人也疯掉。」\n大家能够正常听到的，只有以下两句：\n「别紧张，我会想办法为你辩护的。」这是塞赫麦特审讯时的开场白。\n「恐怕，我真的救不了你了……」这是她的结束语，附带一副极度悲伤的表情。\n",
		organization = "科尔盖",
		heart_chain4 = "塞赫麦特成为重大犯罪对策部行动组长时，曾想过拒绝增加任何成员，毕竟她一人就可以处理一切事务，增加的组员说不定只是累赘。\n在走出办公室时，她正巧碰到了芭丝特。塞赫麦特一眼就看出芭丝特是个刚通过面试的新人，而芭丝特也一眼就认出了这位科尔盖的王牌探员。\n塞赫麦特灵光一现，忽然觉得从零开始带一位新人部下，会是一件很有趣的事。\n在听说芭丝特刚来到科尔盖就进入了塞赫麦特的小组时，大部分人都对此表示惊愕。他们怀着复杂的心理每天观察着芭丝特这个新人小姑娘的心理状态。\n面对一直开朗如常的芭丝特，大家心中的惊奇远大于欣慰。\n至于阿努比斯，塞赫麦特只是觉得，习惯独自执行任务的家伙，可以不用多管，省心省力。——不过后来在劝说他接受自己的搭档芭丝特时，塞赫麦特还是花了不少工夫。",
		heart_chain3 = "塞赫麦特早年的经历可以用「最普通的传奇」来形容。\n她按部就班地觉醒，按部就班地被科尔盖发掘，按部就班地被安排进入精英学院，按部就班地以极其优异的成绩毕业，并再次按部就班地进入科尔盖重大犯罪对策部担任要职。\n她精通心理学，阴险狡诈的惯骗在她看来像是只会扯皮的白痴。一通闲聊，她就能够把对方的内心想法全盘挖出，这可怕的心理侧写能力，让撒谎偷懒的同僚和心怀叵测的惯骗都避之不及。\n按她的说法，她其实并不讨厌谎言，因为她能轻松地分辨出言语的真假，谎言不过是张透明的纸。\n但这并不意味着对她说谎是无关紧要之事，因为她还有一个特别的爱好：她喜欢对撒谎者使用催眠，让撒谎者当众说出自己想要通过谎言掩盖之事。\n——而被催眠的人并不记得这件事，只能蒙在鼓里接受周围人异样的目光。\n在她面前，还是只说实话为好。",
