		height = "155cm",
		name = "金固",
		id = 1016,
		heart_chain5 = "金固逐渐长大，并开始接手公会事务时，马尔杜克分配给他的任务大多是向罗斯塔赫货箱区的难民分发生活物资。然而总有些恶霸通过勒索的方式克扣其他人的物资，然后高价倒卖。即便金固率领公会的人阻止过很多次，但还是屡禁不止。公会内有经验的长辈劝金固不要再插手，这些恶霸的存在变相维持了这些区域的稳定，否则难民哄抢物资的事情总会发生。向恶霸缴纳物资份额，俨然已经成为了某种「秩序」。\n但金固拒绝认同这种想法，在他看来，大多数难民苟且太多，反抗太少。如果不改变现有的秩序，无论分发多少物资，现状都不会发生任何变化。后来金固再次出现在这些难民跟前时，他带来的不再是生活物资，而是瞒着马尔杜克搞来的武器装备。——那也正是金固的亲信部队被组建的时候。",
		heart_chain1 = "金固从小就是罗斯塔赫的孩子王，在他被马尔杜克收养前就是如此。他看上去瘦弱，却拥有惊人的爆发力。一旦掉以轻心，即便高出两头的家伙也会被他一拳放倒。他没读过多少书，心思却出奇的活络。即便被多个找茬的坏孩子包围，他也总能想出一些出人意料的手段重创对方。\n不过，如果这些坏孩子们放弃与金固为敌，并愿意接受金固的指挥，金固就会化身成为一名出色的领袖，带领他们偷面包，打流氓，无往不利。而孩子王金固最出名的一次作战也为他带来了最大的麻烦——他率领流浪街头的孩子们成功偷走了阿卡德公会的货车，带回了足够孤儿院支撑一个月的食品物资。然而不到一个小时后孤儿院就被赏金猎人们包围，院长只能战战兢兢地将罪魁祸首金固交出来。\n那是金固第一次与养父马尔杜克相遇，出乎所有人意料地，马尔杜克满眼赞赏，他不仅将被盗的物资全都捐给了孤儿院，还指名要领养金固。",
		plot_tip = "",
		cv_ko = "김지율",
		like = "收集武器 ，扳手腕",
		super_plot_tip = "",
		plot_tip_picture = "1016",
		cv_en = "Khoi Dao",
		age_en = "",
		cv_zh = "一木",
		cv_ja = "千葉翔也",
		heart_chain2 = "夜里无人时，金固喜欢把他的荒獠拿出来把玩。从他有记忆起，荒獠就是陪在他身边唯一的「财产」。正是依靠荒獠那锋利的刺刃，金固才能够击退不怀好意的恶徒和饥不择食的野狗。\n荒獠想要撕碎的是什么？不公平的秩序？罗斯塔赫衰颓的现状？科尔盖再次酝酿的阴谋？金固并不知道，但他坚信，只要他和荒獠一起战斗下去，总有一天会知道答案。",
		organization = "阿卡德公会/迷铁之家",
		heart_chain4 = "在很长一段时间里，挑战养父马尔杜克都是金固不敢想象的事情。马尔杜克是他的理想，也是他无论如何努力都难以企及的目标。然而正式被马尔杜克收养后，金固得以穿过众人塑造的光环去近距离观察马尔杜克，却发现这位外表意气风发的领袖在很多事情上都显得无奈和保守，就像是个为一大家子讨生计的中年大叔——那绝对不是金固想要变成的样子。\n改变的契机来自一次扳手腕比赛，金固出乎所有人意料地出现在挑战者当中，并与「手腕王」马尔杜克进行了一场惊心动魄的对决。虽然金固最终还是输了，但他看到了马尔杜克额头上的汗。",
		heart_chain3 = "马尔杜克是一位笨拙的父亲，有时为了表现一下父爱，他会搜刮一些话题来与金固谈心，比如「金固，你的理想是什么？」每当被这样问，金固总是大声回答「我要把科尔盖的人彻底赶出罗斯塔赫！」而每次这样回答后，金固那认真的表情总是会让在场的其他长辈赞赏有加。马尔杜克却只是陪笑，然后一言不发。金固似乎能从马尔杜克的眼中看出一丝无奈，这种无奈令他不解。",
