		height = "165cm",
		name = "芭丝特",
		id = 1017,
		heart_chain5 = "每当雷声响起，芭丝特总是下意识地蹲下，蜷缩身体，就像只被吓到的小猫咪。\n旁人常常觉得芭丝特这样很可爱，然而芭丝特的回应往往是一脸苦笑。\n雷声总让她回忆起数年前的那个雷雨夜，她见到了普通人无法察觉到的怪物。那是芭丝特第一次觉醒修正者的力量，并意识到自己背负着常人无法背负的责任。\n然而当她准备出手搭救路人时，却因为怪物引来的雷电付出了惨重的代价——她心爱的猫咪为她挡下了雷击，长眠于那个雷雨夜。\n数年后，即便已经成为重大犯罪对策部的成员，每次想起那个雨夜，芭丝特还是会对这份责任的必要性产生动摇。",
		heart_chain1 = "芭丝特进入重大犯罪对策部不久，就获得了极好的人缘，这大体是缘于她那活泼乖巧的性格。\n无论是谁找她帮忙，她都极少拒绝。无论是多麻烦的问题，她总能想出巧妙的点子解决掉。甚至前辈们遇到了情感上的困难，也可以在她这里得到调解。\n然而一旦回归办案本身，芭丝特的实习生身份就会彻底暴露，她经常会犯一些明显是因为经验不足才导致的错误。比如被佯装晕倒的嫌疑人欺骗，比如不忍心把手铐扣得太紧。\n明眼人都看得出来，芭丝特在通过警校考入重大犯罪对策部之前，几乎没有接触过与刑侦有关的事情，只是没人忍心责备她。\n当然，芭丝特也有在努力完善自己，至少最近不会再犯些低级的失误了，她自己觉得这是值得庆祝的进步。",
		plot_tip = "",
		cv_ko = "이현진",
		like = "跳舞",
		super_plot_tip = "",
		plot_tip_picture = "1017",
		cv_en = "Lizzie Freeman",
		age_en = "",
		cv_zh = "陈雨",
		cv_ja = "佐仓薫",
		heart_chain2 = "实习时期的行动专员，通常会由经验丰富的前辈带领，而被部门安排给芭丝特的正好是阿努比斯。\n从性格上来讲，他们简直就像是两个世界的人，完全看不到交汇的可能。\n所以当芭丝特作为实习生被安排给阿努比斯做搭档后，几乎没有人认为这对搭档会长久。\n不过芭丝特并不在乎有关阿努比斯的一些传言，她只是觉得这个前辈太过冷漠，从来不会主动寻求搭档的帮助，甚至常有出击任务却不带她的情况出现。\n因此芭丝特开始挑战她入职后最艰巨的一项任务：让阿努比斯接受搭档的存在，学会与他人交流。不过到现在为止，这项任务还卡在第一步——让办案时不分白天黑夜的阿努比斯接受按时上下班的建议。",
		organization = "科尔盖",
		heart_chain4 = "曾经有人认为芭丝特就是个不会拒绝的天真后辈，于是想利用芭丝特的乖巧性格，以帮忙审计财务的名义诱骗芭丝特帮他们挪用公款。\n然而第二天那几个人就被监察员带走，而被转走的公款也早已进入安全账户，随后被财务人员尽数回收。\n或许芭丝特可以直接拒绝无礼的请求，也可以劝说同僚迷途知返，但她更喜欢用这种方式来惩罚坏人。\n毕竟再乖巧的猫咪也不能随意招惹，她的利爪不怜悯坏蛋。",
		heart_chain3 = "在重大犯罪对策部举办地某次内部庆功会上，芭丝特身着芭蕾舞服出现在舞台上，用一支《天鹅湖》赢得了所有人的掌声。\n被问起时，其他人才知道芭丝特曾经参加过芭蕾舞团，并且表现不俗。\n大家很奇怪，芭丝特的芭蕾舞水平明明已经到达了职业水准，为什么还要来科尔盖，甚至是重大犯罪对策部这样的地方。\n然而热心的前辈们并没有听到诸如「责任心」、「正义感」之类的说辞。\n「反正考上了，也不讨厌，就来咯。」芭丝特活泼地笑着，如此说道。",
