		name = "休",
		id = 1019,
		heart_chain5 = "近年来，休已经很少参与到直接的对视骸作战中，更多担当的是幕后指挥者的角色，这或许也和新人小队几乎不被派去执行危险的任务有关。\n但即使如此，休也从来没降低过对自己的要求。就算工作得再晚，在深空之眼的训练室里也能看到她每日训练的身影。\n因为休总是告诉着自己，当真正的危机来临时，自己的手中的长枪一定要第一时间挡在同伴的身前。",
		heart_chain1 = "休在苏醒之日就被奥丁找到，此后便在她的身边以修正者的身份被培养长大。因而对休来说，在修正者意识觉醒前她便对自己的身份有了足够的认知，而深空之眼对她来讲也是真正意义上的「家」的存在。\n那时，她与波塞冬一起长大。但与休一起长大的波塞冬却不知为何变成了不理外事的慵懒性格，这点与严谨无比的休截然相反。于是奥丁就把越来越多活交给了休，甚至这几年玩起了失踪。\n「究竟是什么时候变成这样的呢？」忙碌批改文件的休不由地想到。",
		plot_tip = "商业上的事务，管理员也会在意吗？我一个人倒不至于忙不过来，但如果管理员愿意帮忙的话，或许能轻松不少吧。",
