		heart_chain2 = "好记性不如烂笔头。\n休习惯将每日的事项都提前罗列下来，并按照重要程度区分优先等级。\n这并不是因为她的记性不好，而是身为大管家的她工作实在太多了。同时她还有记日记的好习惯，工作至今休已经用掉了十一本日记本。翻开其中的页面，可以经常看到前鬼坊在何年何日闯下了什么罪状。",
		organization = "深空之眼",
		heart_chain4 = "对于这位深空之眼的大管家来说，上至公司运营，下至成员管理，近些年来几乎所有的重要事务都由她一人包办了，恐怕除了休以外，没人知道这到底意味着多少的工作量。\n只是不知道这样的状态还能支撑多久，虽然休从不曾提起，但她的身体似乎已经因为连续的工作而略显疲态，据说偶尔也会被人看见她趴在自己的办公桌前浅眠。\n然而休其实很清楚，现在自己的身上肩负着引导众人的职责，还远没有到能够放心休息的时候。",
		heart_chain3 = "尽管工作越来越忙，休却从来没有想过辞去新人小队队长一职。\n她提到这是因为想多关注下新人们的成长，但也有传言是因为前鬼坊的恶作剧给休带来了太多梦魇，导致休至今都不敢将这份工作轻易放手交给别人。",
