	[1020] = {
		birthday = "2月27日",
		height = "146cm",
		name = "梵天",
		id = 1020,
		heart_chain5 = "在第一个纪元，梵天曾是所有人中最有信心的一个，即便经历了最初的失败，她也始终认为，只要大家团结一致，胜利终将会到来，但事实却与之相反。\n她站在众人的最前方，想要保护大家，但却只迎来了一次又一次的失败。她试着用权能唤回已逝的友人，可造出来的却只是悲哀的空壳。她试着与人类和科尔盖合作，在前方等着她的却是背叛。\n身边的友人一个接一个的消失，视骸的力量却越来越强，她痛切地知道，剩下的机会已经不多了。\n过往已不可追溯，那至少现在在身边一同奋战的伙伴，她仍有机会保住他们的今日与未来。\n发现往世书的那一刻，她就像是看见了一束希望，对未来的期盼让她将全部精力灌注于此。最开始她只不过是想从往世书中寻找一个答案，但不知何时间……她的目标已经发生了变化。\n「这个摇摇欲坠的世界已不再能被修补，那我就去创造吧。」\n她也知道「创造」二字并非说说那么简单，这意味着打破盖亚的规则与禁忌，可既然有着能够终结这场永无止境的战斗的办法，那她就应当去做。这更像是一场与时间的赛跑，能否在更大的牺牲发生前解明往世书便是这场赛跑的命题。\n「毕竟是那家伙，我就知道……」当听到庚辰失踪的消息时，她只是苦笑了两声，再度将目光投回眼前的往世书，愧疚的利齿却在悄然啃咬着她的内心。如果自己能更快解明往世书的话……如果自己能够更快将计划付诸实施的话，可能一切都不会发生。\n过去的夙愿与对未来的祈愿交织在一起，如巨石般压在梵天的肩上，将名为「放弃」的选项碾得粉碎，把前方变为一条只进无退的路。\n孤身一人也好，打破禁忌也罢，既然这是自己认定能够拯救所有人的唯一方法，那么她便会用尽自己的一切将它付诸实行。",
		heart_chain1 = "经过上个纪元的失败之后，梵天确信无意义的清剿视骸只是治标不治本，想要彻底消灭视骸，就必须要采取别的方法。在这个纪元里寻求答案的过程中，梵天发现了原本不该存在于盖亚表面的装置「往世书」，一个新的计划在梵天的心中逐渐酝酿。\n为了确保往世书的位置不被发现，并在加尔建立一定的秩序，梵天创立了弥楼衍，将往世书深埋地下。然而，随着时间的推移，弥楼衍的发展早已超出了她的预期，梵天原本只想在掩盖往世书所在地的同时维护加尔最基本的稳定，不让人打搅自己研究往世书。\n但现在的弥楼衍已经成为了加尔的秩序象征，担任着从救灾救火到消灭视骸等多种工作，甚至开起了孤儿院。\n不用想也知道，弥楼衍的盛况多半是源于自己的两位得力助手。\n「只要不影响我的计划，她们想干什么都行，我不介意。而且……这个弥楼衍，看起来还不坏。」",
		plot_tip = "阿管阿管~听说你来夏什瓦特出差啦！有空来弥楼衍一块儿玩呀，想玩·什·么都可以哦~",
		cv_ko = "이명호",
		like = "音乐鉴赏，捉弄手下",
		super_plot_tip = "",
		plot_tip_picture = "1020",
		cv_en = "Emily Cass/Ariana George",
		age_en = "",
		cv_zh = "龟娘",
		cv_ja = "伊藤美来",
		heart_chain2 = "一开始，伽梨和帕尔瓦蒂还会就帮派里的各种决断寻求梵天的意见，可得到的答案却总是同一个——「好好好~我同意~」。久而久之，伽梨和帕尔瓦蒂逐渐形成了一种默契——帮派内的事务比起问梵天，不如两人自行讨论来得快。就这样，帮派内的大部分事务都被扔到帕尔瓦蒂和伽梨头上。\n不过就算帕尔瓦蒂向梵天抱怨，也只会被梵天一笑而过，随后将话题转到奇怪的方向。\n「老大不就是该偷懒的嘛~比起这个……帕瓦你最近是不是长胖了？让我摸摸看~」这种火上浇油的行为只会让对方的火气更盛，到了这地步，就只有伽梨才能拉得住帕尔瓦蒂。可一旦气氛缓和，梵天又会忍不住开始捉弄两人，让伽梨在哭笑不得中加入数落梵天的队伍。\n她总是一副不问世事的样子，看似对一切都不在乎，像是弥楼衍里最懒散的那个人。可实际上，梵天总是被一股难以言喻的紧张感催促着，催促她将全部精力都投入到对往世书的研究。当不可避免的毁灭悬于头顶，其他的何种行为都只不过是粉饰太平罢了，正因如此，她对那些「没意义」的事情毫无兴趣。\n她的目光总是看向远处，看向那个被拯救的未来。",
		organization = "弥楼衍",
		heart_chain4 = "对梵天来说，创造与毁灭本就是一体两面的东西，任何被她解明的东西都可以被构筑，同样也可以被湮灭。\n不过比起湮灭，梵天更加喜欢创造，她的房里总会多出各种稀奇古怪的物件。\n不知从何处捡来的权钥碎片被她造成了一把全新的权钥，早就坏掉的终端机在她的手里变成了从未见过的全息显示仪，这些杂物不知不觉间就会将房间的角落堆满。\n当梵天一层层拨开事物的神秘面纱，其真面目便清晰地呈现在眼前。她如同一个编织者，将万物拆分成概念和原理，再将它们编织为现实中的形态和功能。\n如此强大的权能，在他人看来梵天几乎无所不能，伽梨问过她这样一个简单的问题：「梵天老大，你是不是什么都能创造得出来？」\n她几乎下意识地要给出自信满满的答复，但话到嘴边，又被她咽了下去。\n梵天曾经尝试过唤回已逝之人，赋予新躯壳以形态对她来说不算难事，友人们的面容清晰的在脑内浮现，随后又化作现实的形体。\n梵天怀着忐忑的心情轻声呼唤着她们的名字，思索着想要畅谈的话题，思念一个劲地在她的脑内打转。然而她等到的，却并非自己想要的回应。世间有着她也无法解明的东西，那些一同欢笑和哭泣的回忆，那些过往的牵绊，曾经流淌于胸中的感情，是无论如何也无法重塑的。\n「不，即使是我……也有创造不了的东西。」",
		heart_chain3 = "平日里的梵天，总是压抑着自身毁灭的力量，仅使用创造的权能。这时的她看起来就像是一位充满活力的年幼少女，总是热情洋溢、平易近人，甚至会让人觉得有些不着调，但这幅面孔绝不是梵天的全部。\n刚觉醒不久的伽梨与弥楼衍成员一同前往源层时，由于经验尚浅，陷入了视骸的包围圈。就在众人陷入绝望之际，「梵天」出现了。不再是平日那副年幼少女的姿态，而是宛如神性具象化的女性姿态，她的周身萦绕着毁灭的权能，举手投足之间，包围众人的视骸连反抗的余地都没有就全部化为尘埃。\n一切结束得太快，看着又变回平日里那副不着调姿态的梵天，伽梨甚至开始怀疑自己自己是否看见了错觉，但被一扫而空的视骸却是刚才所发生的一切的证明。\n事后，伽梨也曾问过梵天为何要封印自己的力量，她却只是笑着回答：「世间的一切都太脆弱，一捏就会碎，总得小心点。再说……要是平时就解放权能，那我不是连美少女的屁股都摸不了了嘛？」\n在身怀湮灭权能的梵天眼中，世间万物只需要看一眼，她就已经能构想出它们崩解的样子，存在与毁灭之间甚至难以划出一条明显的界限。正因如此，她才选择封印自身的力量。珍视之物就应捧在手心，唯有在敌人面前，她才会显露象征毁灭的一面。",
