	[1021] = {
		birthday = "8月20日",
		height = "163cm",
		name = "阿尔忒弥斯",
		id = 1021,
		heart_chain5 = "闲暇之时，阿尔忒弥斯会偷偷溜去各大剧院观赏舞台剧演出。无论是有名剧团的巡演也好，还是业余的演出也好，都能让阿尔忒弥斯流连忘返。\n骑士团内曾有过不少传言，最有力的说法是团长喜欢观看舞台剧中的骑士表演，实际情况却与所有人的想法都略有差距。\n阿尔忒弥斯的确喜欢舞台上高洁正直的骑士形象，但她更喜欢的却是舞台剧中穿着可爱服饰的公主，每当看着舞台上的公主华丽登场时，她都会在想起儿时看见的那些童话故事。\n一直作为家族的榜样，以骑士标准要求自己的阿尔忒弥斯并没有多少时间像享受青春，但这并不代表她没有少女的爱好。\n她也会喜欢那些少女风格的衣服，只是碍于骑士团团长的身份，她必须要在他人面前保持威严，自然与这些服饰无缘。\n作为替代，阿尔忒弥斯会悄悄收集那些舞台剧结束后贩卖的公主布偶，为她们起好名字，甚至一个人召开换装比赛。\n得益于阿尔忒弥斯的眼疾手快，到目前为止这个秘密还无人发现。",
		heart_chain1 = "阿尔忒弥斯是现任灯塔骑士团团长，也曾经任职铃兰骑士团的副团长。\n新加入的铃兰骑士们，大多也只是听说过这个响亮的名字，并没有真正见过她。\n据说在雅典娜之前，她是整个骑士团中实力最强的人，也是最有希望接班凯琳成为团长的角色。\n没人知道她为什么会突然放弃竞争团长之位，反而在一次远海任务后主动接下突然空缺的灯塔骑士团团长一职。\n虽然灯塔骑士团所承担的责任和驻守城市的铃兰骑士团一样重大，他们要在远离城市的海岛上坚守灯塔，维护航路的运转以及抵御来自大海的危险。\n可因为其具体任务鲜为人知，不仅是欧莫菲斯市民，就连铃兰团内部也对这支队伍存在一些误解和偏见。\n灯塔骑士团的成员们常常被称为「铃兰团的吊车尾」、「无法融入秩序的问题少年们」。\n曾有人以此为由劝阻阿尔忒弥斯应当多加考虑，但阿尔忒弥斯没有相信这些一面之词，她觉得既然大家同担「骑士」之名，就不该擅自猜忌。\n不过在正式接手后，她的观念似乎发生了一些变化……据不知名的灯塔骑士团成员透露，现在团内有关作风习惯的规定还在不断更新中。\n",
		plot_tip = "",
		cv_ko = "이은조",
		like = "舞台剧",
		super_plot_tip = "",
		plot_tip_picture = "1021",
		cv_en = "Rebecca Hanssen",
		age_en = "",
		cv_zh = "张若瑜",
		cv_ja = "立花理香",
		heart_chain2 = "作为家族的长女，阿尔忒弥斯曾与家族代表一起参加过许多的社交宴会，宴会上的所有人都仿佛戴着面具，阿谀奉承更是常常成为会场的主旋律。\n但阿尔忒弥斯却与这些人不同，在她看来正确与错误之间应当有一条明确的界限，而不是像墙头草一般随意偏倒。\n只要是自己觉得不公平、不正确的事情，不管对方的身份地位如何，她都会毫不犹豫地指出。\n可想而知，这样的性格让阿尔忒弥斯得罪了不少人，不知不觉间关于她的流言蜚语越来越多，那些人甚至给阿尔忒弥斯起了个称号——「徒有其表的贵族」。\n但阿尔忒弥斯并不在意，自己只不过是做了理所当然的事情，没有任何被指责的理由。\n加入铃兰团后，众人以为这次她总该学会收敛了，但刚入团的第一天，她就指出了前辈在规章上的错误，惹得所有新人都对她目瞪口呆。\n每次任务后的报告书中，不少人都会悄悄隐去一些无关紧要的细节，诸如追逐犯人时未按章程首先亮出团徽、又或是出借马匹时未能提前报备之类的。\n但阿尔忒弥斯却不一样，就算是迫于形势稍有违反规章制度，她也会将其一五一十地写在报告书上，然后乖乖接受打扫驻地的惩罚。\n仅仅几个月后，阿尔忒弥斯便在骑士团内出了名，但与以前最大的不同却是，铃兰团的骑士们都被她正直的作风所触动，这一次，她被称为骑士的典范。\n",
		organization = "灯塔骑士团",
		heart_chain4 = "成为铃兰骑士团副团长的不久后，阿尔忒弥斯认识了总是在训练场挥舞木剑的女孩——雅典娜。\n她为雅典娜的毅力所打动，有空时就会去指导雅典娜的训练，甚至经常做她的模拟战的训练对象，两人也成为了无话不谈的朋友。\n可随着雅典娜通过考核加入骑士团到成长为骑士团中耀眼的新星，阿尔忒弥斯就像在看着过去的自己：\n两个同样憧憬凯琳团长的人，两个同样以成为铃兰骑士团团长为目标的人，但雅典娜确实更为出众，她的存在对阿尔忒弥斯来说就像是不断追赶着她的巨浪。\n那些外界的猜测让她如芒在背，阿尔忒弥斯头一次感觉到自己的内心被胜负欲压倒，想要赢过雅典娜，想要成为铃兰团的团长，如凯琳一样领导骑士、领导时代。\n又一次模拟战后，阿尔忒弥斯勉强拿下胜利，但她很清楚这并非是靠自己的实力，而是因为雅典娜在最后关头收住了剑。\n「你刚刚明明可以赢过我，为什么收剑？」\n「阿尔忒弥斯副团长……因为我觉得铃兰骑士的剑是为守护而存在的，而不是为了分出胜负。」\n阿尔忒弥斯被这番话语怔住，良久无言。她看向雅典娜清澈不带一丝杂质的眼神，知道另一场胜负也有了结果。\n她回想起加入骑士团的那个午后，反问自己究竟是为了什么努力到现在。说到底，自己想要的并非是当上铃兰骑士团团长，而是成为像凯琳一般高洁正直的骑士。\n于是她终于露出释然的微笑，起身向雅典娜表达了自己的歉意。雅典娜虽然并不清楚发生了什么，但她能感觉到阿尔忒弥斯像是松了一口气。\n后来，雅典娜当上了铃兰骑士团的团长，而阿尔忒弥斯则成为了灯塔骑士团的团长。\n即便身份改变，但二人的关系依旧是无话不说的朋友，见面时两人总会像以前一样畅谈着音乐、剑技又或是凯琳的事迹。\n每当看见雅典娜为了欧莫菲斯而拼尽全力的样子，阿尔忒弥斯都会回想起凯琳团长的教诲——「骑士是为了守护而存在的」。\n",
		heart_chain3 = "自决定成为骑士开始，阿尔忒弥斯便一直以十分严格的标准要求着自己。\n一开始她只是想要尽力做到最好，可随着她加入骑士团后的优异表现，她很快便成为了众人瞩目的对象。\n前辈口中的未来之星、家人口中的家族希望、民众口中的骑士典范……她的头衔越来越多，意味着对她的表现有所期待的人也越来越多。\n为了回应那些期待，让这些虚名化为真实，她只能更加严格地要求自己。\n日复一日的严苛训练让阿尔忒弥斯当上了铃兰骑士团的副团长，也切实成为了许多人的榜样，背负的诸般期待推动着她不断前行，不知何时间就连退路都已消弭殆尽。\n阿尔忒弥斯作为团长的工作无可指摘，民众与团员们的赞誉之声不绝于耳，但阿尔忒弥斯心中却始终留着一份不安——自己会不会在何时踏错一步，致使他人的期待落空呢？\n但她不能将这些心底的疑问诉诸于口，唯有夜深人静的时候，她才会拿起小提琴，对着夜色抒发着自己这小小的不安，当太阳再次升起时，她又将再次变回平日那个凛然的骑士团团长。\n",
