	[1022] = {
		birthday = "3月1日",
		height = "170cm",
		name = "塞勒涅",
		id = 1022,
		heart_chain5 = "由于某个特殊事件，塞勒涅一直驻守在远离欧莫菲斯中心的克里特岛上。\n为避免引起岛上居民不必要的恐慌，塞勒涅的驻扎地十分偏僻，几年间都不曾见过人影，她在此的生活静谧而孤独。不过这也正合了她的意，她对此很是适应。\n不过，这清静的生活并不纯粹。在哈迪斯的强烈请求下，塞勒涅还是携带了通讯终端，以远程处理星虹议会的事务。\n「生活在哪里都差不多，无非是换个地方看太阳月亮兜圈子。我不在乎。」\n虽然塞勒涅总对周围的一切都表现出满不在意的样子，但不出一年，那片人迹罕至的荒地上就奇迹般开出了大片的花。\n海岸的居民们总说，在月圆之夜，能隐约听到有歌声自海上传来。那异常的声响并不使人产生未知的恐惧，反而使人感到无比舒适与安心。",
		heart_chain1 = "身兼星虹议会第五席及声乐协会会长的职位，理论上塞勒涅的公务会是相当繁忙，但事实并非如此。\n大部分时候，塞勒涅只是默默地坐在自己的办公桌前，阅读或撰写着各类论文。\n星虹议会和声乐协会的事务并不空闲，而塞勒涅之所以能如此清闲，是因为她难以接近的气质——如非必要，大部分人并不愿意寻找塞勒涅处理他们的诉求。\n与塞勒涅相处过的人都认为，在与她说话时会感到非常大的压力。对此塞勒涅回应道，自己从来只是正常地问询，从未故意刁难过任何人。\n「难道那些无意义的寒暄和谦辞能将事件处理得更好么？我不这么认为。」\n长此以往，本就散发着清冷气场的塞勒涅更是鲜有人愿意接近，她的周围总是十分安静冷清。\n值得一提的是，塞勒涅本人似乎很满意这个状态。",
		plot_tip = "若管理员你最近有空，我希望邀请你来声乐协会做客，与我共同参加新作月赏。",
		cv_ko = "정혜원",
		like = "声乐练习，复古物件",
		super_plot_tip = "难得你来，有兴趣和我去一个特别的地方吗？",
		plot_tip_picture = "1022",
		cv_en = "Alex Constantinidi/Alice Himora",
		age_en = "",
		cv_zh = "秦紫翼",
		cv_ja = "明坂聪美",
		heart_chain2 = "对于这位不怎么出现在公众视野里的第五席议员，欧莫菲斯其实一直流传着有关她的传闻。\n传说她曾经举办过一场只能用「震撼」来形容的演唱会，凡是亲历过的人，无不感叹「神迹降临」。\n「塞勒涅大人的演唱就连月光都为她动容，我亲眼看见银河流淌而下，月亮幽幽悬在她身后。」\n「当之无愧的第五席！她一开口，所有的事物仿佛都像是活过来一样！她唱到风起就有轻风拂面；唱到花开就有遍地蓓蕾绽放；唱到雪落，竟能让欧莫菲斯盛夏的天空中落下几片雪花来……真是神迹啊！」\n关于塞勒涅的神秘传闻随着她的一场场演出愈演愈烈，甚至一度达到「信仰」的地步。好在，这些狂热的言论和行为在塞勒涅中止演出活动后很快平息下来。\n事实上，塞勒涅这言灵般的能力在缪斯协会内部人尽皆知。她时常会用自己的能力给大家帮些小忙，譬如让门前快要凋谢的花朵再多盛开几天，或是让将断的琴弦多坚持一场演奏。\n但假如是「考试通过」「抽奖中奖」之类的「确凿结果」，她从不会应允。\n或许塞勒涅的沉默寡言，正是因为她不想过多使用自己言语的力量。至于过度使用会招致怎样的后果，恐怕只有她自己知晓。",
		organization = "星虹议会",
		heart_chain4 = "自声乐世家中成长，塞勒涅听过最多的一句话便是「你要为家族争光添彩」，或是「你要站在聚光灯下」。\n塞勒涅深以为然并为此努力，天赋过人的她很快就使自己天才的名号响彻欧莫菲斯。在这个艺术至上的原质区，人们看中了这份才能的价值。\n演出邀请和合约纷至沓来，塞勒涅被精心包装后推到台前，步步上升。\n最后她如愿站在巨大舞台的聚光灯下，赢得无数鲜花和掌声。然而，梦想成真的她看着台下涌动的人潮，产生了一丝游离的迷惘。\n演出与热度如同浪潮，来时猛烈，退时无声。一片死寂中，塞勒涅站在空荡荡的练习室里，思考着下一次又要用什么样的歌曲吸引更多的观众。\n太多歌唱以外的杂乱事务在她的脑中打转，她感到疲倦与无趣。\n当她意识到，自己开始将精力更多地花在盯着社会各界对自己的讨论评价而非认真练习时，歌唱已经失去了最初的意义。\n塞勒涅立刻宣布，自己不再继续演出。这霎时引起轩然大波，也有人认为她不过是在炒作。\n等一切的一切都平息，再无人提起那个盛极一时的歌唱家塞勒涅，她不再会被大批的追随者围堵，也不会因风评的变转而担忧。\n她悠然自得地躺在午后的草地上哼起旋律，看着认真驻足倾听的小小生命们，只有此时塞勒涅才会觉得，这些时间真实属于自己。",
		heart_chain3 = "塞勒涅的心神始终保持在极度稳定的水平，少有情绪与神采的变化。对她而言，音乐以外的一切都同等无趣。\n因为提不起兴趣，所以塞勒涅在处理事务的时候，总追求一步到位，避免不必要的迂回。她的决断通常不容置疑，事实上，她也确实从未出过错。\n她平静地观察着眼前的所有，然后以平缓的速度思考，再似机器般平稳流畅地安排出得当的处理方法。\n在恰当的时机，以恰当的方法，按恰当的顺序解决问题——这是塞勒涅对待工作的唯一信条。至于这个「恰当」与否，则全在她自己的直觉判断。她的直觉总是很准确。\n「事件就像乐曲，漂浮在空气中。大部分时候，它们完整而流畅。」\n「不协和音程在落进曲谱时，总会划破空气，发出噪音。我只要在它被演奏出来之前，将它修正即可。」",
