	[1024] = {
		birthday = "6月13日",
		height = "172cm",
		name = "阿努比斯",
		id = 1024,
		heart_chain5 = "其实阿努比斯并非一直孤单一人，他收养了一条流浪街头的牧羊犬，给它取名叫乌普，并将它培养成为一条警犬。\n乌普像仿佛和阿努比斯之间有心灵感应一样，每次都能准确理解他的意图，并优秀地配合，帮助阿努比斯侦破了许多棘手的案件。一起经历了许多后，阿努比斯将乌普视为无可替代的伙伴。\n但意外还是突然来临，在一次执行任务的过程中，乌普为阿努比斯挡下一颗子弹。\n「不要走……」阿努比斯将乌普抱在怀里，用力感受着那个逐渐虚弱的灵魂，「留下来！」\n或许是为了回应他的强烈愿望，名为「胡狼之面」的权钥终于觉醒，并将乌普的灵魂数据全部复制……当一切结束后，拥有乌普形态的魂犬借助权钥的力量出现在他的面前。\n然而真正的乌普还是远去了，他怀里的存在变成了没有回应的空洞存在，一如那天的墓碑。\n阿努比斯终于明白，他拥有的能力并不能真正阻止死亡。",
		heart_chain1 = "阿努比斯刚刚入职重大犯罪对策部特殊行动组时，就立刻收到了一份包含情书、巧克力、心意便当的豪华表白礼包。\n毕竟阿努比斯拥有一张年轻俊美的少年脸庞，即便最稳重的女专员也难免会动心。面对这样英俊的少年，表白者似乎有些信心不足，采取了匿名的方式，想要经历一场无果的暗恋。\n而阿努比斯采取的应对措施令所有同事大跌眼镜——他用缜密的办案思维收集线索，查出送件人，然后郑重地物归原主。\n这之后，特殊行动组的女专员之间出现了一条不成文的规矩——必须劝阻任何想要向阿努比斯表达心意的新人，以防她遭受被当众退还情书的痛苦。",
		plot_tip = "管理员，期待我们今后的合作高效而愉快。",
		cv_ko = "강호철",
		like = "办案",
		super_plot_tip = "",
		plot_tip_picture = "1024",
		cv_en = "Chrystian Marte",
		age_en = "",
		cv_zh = "乔磊",
		cv_ja = "古川慎",
		heart_chain2 = "其他人都以为阿努比斯会一直保持单独行动，直到他的新搭档芭丝特的出现。\n这个热情的少女似乎想要和部门的所有人都打好关系，其中当然也包括阿努比斯，为此他也没少烦心过。\n阿努比斯曾经数次申请调换搭档，并申明最好没有搭档，但不知出于何种原因都没被批准。\n不过，时间久了以后，阿努比斯也慢慢接受了搭档的存在——或者说接受了上级的安排，不过他还是会经常强调自己一个人执行任务的效率更高。",
		organization = "科尔盖",
		heart_chain4 = "养父葬礼那天，阿努比斯拿着养父留下的那枚胡狼假面，在墓碑前驻足良久，直到旁人离去。\n他将一只手放在墓碑上，试图再次感受养父的灵魂，体验那种温暖和真挚。\n但是什么反馈都没有，墓碑的质感冰凉而坚硬，内在空洞无声，养父的声音随着阿努比斯的记忆一起远去。\n「灵魂的远去，就是死亡。」阿努比斯默念道，「如果当时有我在，就好了。」\n他很想回到养父出发的那天，坚持陪在父亲身边。这样在养父遭遇不测的时候，他就有机会用力地将那个温暖的灵魂留下来。\n这样的想法成为阿努比斯心中无法消去的尖刺。",
		heart_chain3 = "阿努比斯还在幼年时就察觉到自己拥有一项特殊的能力，他似乎可以从灵魂层面去感受他人的情绪，因此可以轻易地识破欺骗和虚伪。\n但这对他来说并不算幸运，虚伪的大人们似乎都不喜欢一个太「聪明」的孩子，聒噪的孩子们似乎也不喜欢一个难以愚弄的同伴。\n长此以往，阿努比斯变得沉默寡言。\n不过，也有例外。阿努比斯的养父是一位正直而又热心的警官，当阿努比斯感受他的灵魂时，涌入脑海的情绪温暖而又真挚，阿努比斯从这些情绪中看到了一位正直的警官所描述的理想未来。\n也许是受到了这种情绪的感染，阿努比斯也梦想着成为一名伸张正义的警官。",
