	[1026] = {
		birthday = "8月11日",
		height = "183cm",
		name = "努阿达",
		id = 1026,
		heart_chain5 = "虽然自从接下隐科组的订单后每天都很忙碌，但努阿达很满意自己的现状。\n当然深空之眼也并不是没有表示过希望他能加入的想法，只不过努阿达似乎也有自己的考虑，所以并没有接受。\n他还想与这个世界上的其他人类谈谈，聊聊他们内心对工艺的想法，或者替他们制造一些小玩意儿。努阿达始终觉得，锻造是不能脱离人而存在的，只有造出大家需要的东西才是这门技艺存在的真谛。\n在制造强大武器的同时，努阿达也乐于有人在闲暇时间来找他修修故障的电视机。\n当然，偶尔也会有订单太多的时候，那他可能会因为通宵而没法提起精神和你说话，但要相信这并不是他的本意。",
		heart_chain1 = "努阿达被收养在一个工程师家庭，从小便对机械和制造充满痴迷。在很小的时候，他的工程师水平就已经超越了自己的养父，开始向更高的层次迈进。\n为了实现自己成为最强锻造师的梦想，努阿达开始挑战一些没有人尝试过的设计，但这也意味着更高的难度和更多的危险。随着技艺的不断增长，他的挑战也一次次更为惊险……直到那次变故的发生，意外的工程事故让努阿达失去了一条手臂。\n虽然捡回了一条命，努阿达却陷入了长时间的低迷，或许是失去手臂的缘故，但更多的应该是成为最强锻造师的梦想再也无法实现了。\n就在努阿达的人生即将被黑暗吞没时，他的修正者意识觉醒了。仿佛来自另一个世界的工程技艺和认知涌入他的脑内，彻底改变了他的人生",
		plot_tip = "管理员，要来我的工坊参观吗？随时欢迎……哈欠……",
		cv_ko = "김다올",
		like = "设备制造与改良、熬夜",
		super_plot_tip = "",
		plot_tip_picture = "1026",
		cv_en = "Chase Brown",
		age_en = "",
		cv_zh = "马洋",
		cv_ja = "白井悠介",
		heart_chain2 = "成为修正者后的努阿达告别亲人和朋友，独自来到核心城并开了一家名为「丹努炉心」的机械工作室，开始承接一些特殊的设备锻造与改造业务。虽然店面并不是很大，但身为店主也是唯一员工的努阿达，一直兢兢业业地经营着此处。\n他的产品总是能给人带来恰到好处的满足感，制作精良、严丝合缝。基本上只要光临过的顾客，无一不称赞他的精湛手艺。对于这些顾客的到来，努阿达也总是以笑容相迎，并且致力于为他们打造自己最好的作品。\n「如果我做的东西能够帮上他们的忙，就再好不过了。」",
		organization = "灵活就业",
		heart_chain4 = "「这个设计图，请务必交给我来做！」\n可以说隐科组和努阿达的组合诞生得有点过于巧合，像是套路般的展开。\n只是海姆达尔偶然路过努阿达工作室的门口，又恰好地掉落了一份设计图，而这份设计图又碰巧被努阿达捡到了。\n在拿起那份设计图之后，努阿达的脑子就开始飞速运转起来，蓝图、材料、效果，各种想法在他的脑子里交织。他在一瞬间就认定这份设计图正是他期待已久的，能够提升自己锻造技术的突破口，其中的精妙结构让他迫不及待地想要把这份设计图变成现实。以至于他都没有思考，立刻表达了想要接下这个订单的意愿。于是自从这次合作以后，来自隐科组的奇妙设计图不断被寄到他的工作室。\n努阿达现在，可以说充实地过了头。",
		heart_chain3 = "当然，来店的顾客也不止一次问过关于努阿达那只右手的事，不过他也只是笑笑，并不多说。对于他来说，这只机械制的右臂意味着成为最强锻造师的第二次机会，但同时也是一种警示。\n现在的努阿达相比以前更加稳重，虽然仍然会一时兴起挑战各种危险的设计，却也多了一丝谨慎。可以说专注于作品时的努阿达是抱着满腔热爱的，也是充满敬意的。偶尔会有人看见努阿达看着自己泛着银光的机械义肢，陷入深深的沉思中。",
		weight = "76kg",
