	[1027] = {
		birthday = "6月12日",
		height = "147cm",
		name = "利维坦",
		id = 1027,
		heart_chain5 = "在一次勘探冰山内部的任务中，「冬」小队曾意外被大量视骸伏击。应顾不暇的维达尔背后遇袭，是利维坦用她的船锚挡住了这一击。然而仓促中来不及调整体势的利维坦却被这一击击飞，负伤晕了过去。等她醒来后，她惊讶地发现自己正躺在维达尔腿上，激动过度的她随即又晕了过去，吓得维达尔还以为她受了重伤。\n那天晚上，维达尔将受伤的利维坦像一个蛹一样地包在吊袋里，然后将烤好的肉一块块递到她的嘴边。\n「唔……嗯……师父师父，你……真的不记得利维坦了么？」女孩似乎并没有因为伤口影响到说话的兴致，她晃动着被绑成沙包似的身体，眨巴着眼睛问眼前的人。\n「嗯，不记得了。」\n「唔……好吧。」\n「但是，利维坦身上有种让人感到安心的味道……」一直低着头的维达尔忽然小声地说道。「和芬里尔一样，像……家人。」\n「师、师……师父！」\n面对兴奋到飞扑过来的利维坦，维达尔条件反射地避开了吊袋，而这也导致利维坦直接一头扎进了雪堆里。\n「你没事吧？」\n「没、没事……利维坦好开心呀！」从雪堆里被拔出来的利维坦，咧着嘴笑着说道。",
		heart_chain1 = "据利维坦说，她曾经乘坐一个巨大的逃生舱，在一片黑暗里漂流了不知多长的时间。\n突然有一天，逃生舱的外部极速升温，她感觉到有什么东西与逃生舱外部剧烈地冲撞着，然后随着一声巨响，逃生舱降落在了极地的冰川上。至于她是如何登上逃生舱，以及为何在极地降落的，这些记忆已经完全断片了。唯一可知的是，利维坦来到深空之眼时，身上确实穿着一件古怪的白色密闭服。\n利维坦回忆起自己在极地和维达尔相处的岁月，曾经弱小的她，每日都要被暴躁的企鹅欺负，直到一天在冰窟窿里发现了浮起的冰船锚，这才有了驱赶那些企鹅的能力。\n但得到武器的利维坦并没有为自己猎得食物的天赋，如果不是遇到维达尔的话，估计她很快就要在寒冷的极地被冻僵饿死了吧。",
		plot_tip = "管理员管理员，和利维坦一起去遛芬里尔吧~！",
		cv_ko = "김연우",
		like = "维达尔、冰淇淋",
		super_plot_tip = "管理员，你快来帮帮利维坦吧！",
		plot_tip_picture = "1027",
		cv_en = "Harriet Carmichael",
		age_en = "",
		cv_zh = "刘雯",
		cv_ja = "Machico",
		heart_chain2 = "这样被提及到的维达尔，却坚决地否认自己见过利维坦。她没有在极地帮助过任何人，唯一的伙伴只有一只名叫「芬里尔」的极地犬。\n两人的记忆有了出入，但这并不影响利维坦的热情似火。\n尽管维达尔强调了很多次「我根本不认识你啊……」、「你认错人了吧？」、「你到底是谁啊？」，但到了最后，都总会被利维坦泪汪汪的小眼神所打败。\n可能是考虑到和利维坦一样在极地生活过的缘故，奥丁让两人组成了「冬」小队，由维达尔作为队长与导师带领利维坦一起行动。\n两人除了出击清除视骸外，还会在每年的特定时间前往极地，进行为期数月的勘探考察。一方面是她们都拥有应付极地恶劣气候的丰富经验，另一方面则是因为极地还隐藏着一批被冰封的可怕视骸，需要有人定时记录它们的情况。",
		organization = "深空之眼",
		heart_chain4 = "虽然维达尔本人对这个缠人的小徒弟应付不来，但她所养的雪橇犬「芬里尔」却非常的喜欢利维坦，利维坦也是深空之眼中唯二可以摸芬里尔头的人。\n以前只要晚上有空闲，利维坦就会骑着芬里尔到公园里兜风。可是被当成「一个人溜大型犬的小孩子」遭到市民多次举报后，利维坦就被剥夺了独自带芬里尔出去的权力。\n但因祸得福的是，之后带芬里尔出去溜的工作就由维达尔自己来进行了，理所当然的，利维坦也会被一并带上。\n维达尔走在前头用狗绳牵着芬里尔，而利维坦则趴在芬里尔的背上做着甜甜的美梦，这样温馨的时刻是利维坦每周最享受的时光。",
		heart_chain3 = "利维坦是个活泼开朗的孩子，虽然有些一根筋，不懂得察言观色。但她的纯真和率直让深空之眼的大家都非常喜欢她。\n只是有一点，当有人和维达尔之间表现得过于亲密时，利维坦就会鼓起腮帮子，用幽怨的眼神一直盯着对方看。这种小醋坛子的性格，似乎从她加入「冬」小队后就一直是如此。\n为了得到维达尔的认可，利维坦表现出了和性格大相径庭的努力，有段时间甚至会在训练室练习到天黑。但也许是心智还不够成熟，她总是会在任务中犯一些不大不小的差错，简而言之就是比较容易「犯迷糊」。\n「呜呜呜，怎么办？今天又在任务中掉链子了，师父不会因此讨厌我吧……」\n不过这样容易沮丧的利维坦，恢复心情的速度却也非常的快——当有蹬被子习惯的利维坦，醒来发现自己难得完好地盖着整齐的被单时，她便知道那个人已经来过了。\n「嘿嘿~师父果然还是最喜欢我的！」",
