	[1028] = {
		birthday = "5月8日",
		height = "160cm",
		name = "托尔",
		id = 1028,
		heart_chain5 = "转机的发生是在某一次追击视骸的任务中：前鬼坊冒进的行动使得她和阿波罗落入陷阱中，遭到了众多视骸的围攻。虽然托尔及时赶到救援，却也不得不面对队友重伤的事实。\n后来，当她怀着忐忑的心情前往探视的时候，迎来的却是前鬼坊和阿波罗的拥抱，以及他们希望正式加入托尔小队的请愿书。\n「我就知道，队长肯定会来救我和臭凤梨的！」\n「还真是惊险啊……差一点太阳就要陨落了，还得靠队长来摆平嘛~」\n这份夸张到有些溢出的信任，让本以为二人会就此退出的托尔感到吃惊。她也当即表示了自己想与他们成为正式队友的心情，收获了两人一致的「不坦率」的评价。\n在这之后，「雷小队」顺理成章地诞生，托尔也不再掩盖自己的自信，重新找回了开朗的性格——这虽不能称为坏事，但「雷小队」也因为受到她的影响，成为任务完成率最高，但战术执行效率最低的小队。\n休在检查作战记录时如是说过：「希望托尔能够明白，作为一名合格的领队，相比于承担成员的责任，不如一开始就别让他们闹出乱子……诶，虽然估计很难就是了。」",
		heart_chain1 = "根据深空之眼的档案记载，艾因索菲的源层曾发生过一次特殊的能量暴动。超出正常区间过多的异常数值，甚至惊动了奥丁亲自前往源层处理。\n得益于奥丁强大的实力，这次能量暴动很快就被压制下来，也幸运地没有引发骸震。不过和奥丁一起回来的，还有一名昏迷在她怀中的红发少女——也就是托尔。\n即便从现在已有的资料来看，托尔也是修正者中最为特殊的一类。毕竟直接在源层苏醒并不是常见的现象，何况从苏醒开始，托尔就开始日复一日地与视骸战斗。\n「那时候我只知道要消灭它们……有个声音这么告诉我的，至于为了什么？谁管嘛~」\n托尔长时间在源层狩猎视骸，积攒了无数对敌的经验，同时也受源层的环境影响，而在体内形成了高密度的神能。\n实力的增强本是有益的，但托尔在长久的战斗中，性格与对世界的认识并未获得成长。这也导致她没法控制一直在增强的力量，最终导致了源层能量的暴动。\n这次事件之后，奥丁决定亲自教导托尔控制力量之法，托尔也就顺理成章地加入了深空之眼。",
		plot_tip = "管理员，不管你有没有加入雷小队，我都罩着你！",
		cv_ko = "신나리",
		like = "训练、游戏",
		super_plot_tip = "训练？不知道大国主又搞了什么东西……没事！管理员你还有我在呢！",
		plot_tip_picture = "1028",
		cv_en = "Kristen McGuire",
		age_en = "",
		cv_zh = "袖子",
		cv_ja = "沼仓爱美",
		heart_chain2 = "「今天的源层真是壮观，苍蓝的雷电四处交织。有机会的话真想让你们也见识一下，呵呵。」\n奥丁将托尔带回来时，也不忘描述源层的盛况。苍蓝的雷电——这既是指托尔所释放的暴动能量，也是对托尔战斗方式的贴切比喻。\n将体内积攒的神力化作雷霆向外释放，无差别地对周围的一切事物进行电击，直至它们化作焦炭。经过一段时间的训练后，托尔已经能自由控制放电的目标与能量多少。\n在紧急情况下，托尔甚至可以做到引动雷霆缠身，强化全身的行动。那时敌人能捕捉到的，恐怕只有托尔的雷霆闪光了。\n隐科组针对托尔的战斗方式，专门为其开发了集电力存储和磁力场技术为一体的机械锤「妙尔尼尔」。本意是希望其作为托尔释放雷电的媒介，不过托尔本人似乎更喜欢它的物理打击性能。\n另外，托尔必须定期释放体内多余的雷电，如果在训练场见到托尔的话，或许不要靠得太近会比较好。",
		organization = "深空之眼",
		heart_chain4 = "「喂，小心别碰到我……」\n「哇塞，噼里啪啦的！这个是什么新型静电陷阱吗！有趣有趣！我有新的恶作剧灵感了~啊，你是托尔前辈没错吧，我是前鬼坊天狗，叫我前鬼就好，今天起加入你的小队实习。」\n时隔许久重新加入小队编制，托尔显得有些不适应，但热情的前鬼坊天狗早已因为「队长会放电真的超酷」这样单纯的理由，把自己默认为了她的伙伴，「雷小队」的一员。\n加上另一名队员阿波罗，托尔的身边逐渐变得吵吵闹闹起来。沉寂许久的心绪被唤起，托尔心中再度生出了与小队成员们和谐相处的向往。\n但同时被唤醒的，还有过往的经历——为了不再重复过去的错误，托尔开始有意识地收敛起自己的锋芒。她试图表现得更加沉稳可靠，但从队员的反应来看，并没有收获预期的效果，她因此变得不知所措起来。\n「最开始加入小队的时候，队长有一段时间感觉变得怪怪的。怎么说呢……她的头发都不会变得哔哩哔哩了。」",
		heart_chain3 = "托尔刚刚加入深空之眼的时候，还没有如今「雷小队」的独立编制。她自然也有不少与当时的其他成员合作完成任务的经历。\n当时的托尔还不能很好地控制自己的力量，因此身边总是充斥着从身体中逸散出的电流。她给人的感觉也和静电一样，毛毛刺刺的，看起来不怎么好惹。\n在一次小队任务中，自信的托尔独自追击视骸，疏忽大意之下，中了敌人的调虎离山之计。她的队友遭遇包围而重伤，之后便退出了深空之眼。\n因为这件事，托尔渐渐被一些成员疏离，没人愿意再与之组成小队。但她其实并不希望如此，她也曾认真维护过和队友之间的关系，但总是为时已晚。\n在那时的托尔心中，无法与队友拉近关系成为了永远的遗憾。自那以后，托尔就习惯于一个人完成任务了。",
