		id = 1032,
		heart_chain5 = "同深空之眼高层完成了前期洽谈后，提尔正式在每年一度的董事大会上，提出“用土地换取深空之眼公司股份以进行企业合并”的提议。选择深空之眼的理由，是他与奥丁约定必须守护的秘密，无论如何也不能在董事会上公开。\n不出意外的，这项提案立刻遭到包括内部劲敌和公司元老的强烈反对——深空之眼作为一家极其年轻的公司，根本无法获得他们这群老狐狸的信任。\n然而提尔早已不是那个稚嫩的接班人。会议开始前，他就已经安排内应做好准备。最终投票阶段的反水操作，让他的提案得以高票通过。而那些被会议气氛蒙蔽了的潜在敌人则纷纷暴露，已经牢固掌握权柄的提尔对他们采取了最果断的处置。\n处理完公司事务后，提尔照例很晚回家。但这天他看见了已经趴在桌子上睡着的弟弟——桌子上摆的蛋糕让他猛然想起，今天是自己十九岁的生日。",
		heart_chain1 = "提尔·塔列朗，塔列朗家族的第四代子嗣。在塔列朗家族企业与深空之眼合资完毕后，成为深空之眼董事会的成员之一，并在几年内帮助深空之眼成为艾因索菲区的最大的商业公司。\n对于这位第三部门的合作者，就连奥丁都对其赏识有加。他对内实行铁腕手段，执行方案时雷厉风行，同时又对自己看准的人才充分信任，赢得了属下的尊敬和信赖。\n即便公务繁忙，提尔偶尔也会在业余时间培养些小爱好，比如下棋和打高尔夫球。但与此同时，这些爱好也大多被他当作社交手段充分利用。提尔从未真正放松过，这似乎源自少年时代给他留下的伤痛，这份伤痛让提尔不允许自己松懈。",
		plot_tip = "",
		cv_ko = "한신",
		like = "商业讲座、高尔夫",
		super_plot_tip = "",
		plot_tip_picture = "1032",
		cv_en = "Joseph May",
		age_en = "",
		cv_zh = "桑毓泽",
		cv_ja = "武内骏辅",
		heart_chain2 = "虽然与深空之眼建立了合作关系，但提尔“塔列朗家族成员”这一身份并不会有任何改变，故而他也并不直接接受第九部门的调遣。\n不过奥丁曾经透露过，提尔一直暗中关注着第九部门的每一次行动，每当发现第九部门的成员遭遇麻烦时，提尔就会动用塔列朗家族那庞大的影响力提供帮助。很多修正者正是依靠这些帮助化险为夷。\n每当有人问起时，提尔并不避讳提起他向第九部门提供帮助的事实。不过在他看来，这并非是出自责任感或者情谊。提尔认为，如果第九部门遭到麻烦，深空之眼公司的运作也势必会受到影响，因此从商业层面考虑，他会在力所能及的范围内提供帮助。",
		organization = "塔列朗家族",
		heart_chain4 = "在十八岁的那一年，按照父亲的遗嘱和企业的规定，提尔正式成为了塔列朗公司的下一任董事长。\n摆在提尔面前的是堆积如山的债务、商业劲敌想要吞并塔列朗的野心、还有内部混乱离心的状况。当时几乎所有的财经媒体都认为，刚成年的提尔不堪当此大任，塔列朗家族企业的股票也持续下跌。\n然而年少的提尔却拥有令所有人都吃惊的果决和魄力，他一上任就对公司人员进行大刀阔斧的改革，清算了内部的腐败。同时他积极与债务公司进行谈判，为塔列朗公司争取到了宝贵的时间，甚至奇迹般地开辟了新的业务板块。\n在提尔的带领下，塔列朗家族企业最终扭亏为盈。股价不仅回升如初，还在后来屡创新高，塔列朗家族在很短的时间内，就以大型集团的身份重回艾因索菲龙头之列。",
		heart_chain3 = "塔列朗家族很早就通过地产投资，让塔列朗家族企业成为艾因索菲区的龙头企业之一。举世瞩目的成就让塔列朗家族获得了巨大的声望，同时也招来了诸多旁系亲族的嫉恨。这些旁系亲族没能从塔列朗家族企业的繁荣中分享到荣华富贵，个人私欲驱使他们在嫉恨中蛰伏。许久之后，他们终于获得了一个千载难逢的机会——塔列朗家族的上一任董事长被巨量的公司事务累垮了身体，离世时只留下一对尚未成年的兄弟。\n就在亲族成员如同秃鹫般群聚在董事会议上，准备瓜分塔列朗家主的最后一份遗产时，作为指定继承人的提尔·塔列朗现身了。他的身后站着他父亲最信任的律师团。最终，这场阴谋被未成年的提尔成功挫败。\n——以上，便是外界所知的全部。即便是塔列朗集团的大部分员工，也认为提尔是依靠继承权赢下了这场商战。只有极少数人知道提尔曾经做出过何其艰难的决断，又曾面对过何等凶险的烈焰……\n提尔没有像这些恶毒的亲戚们所期望的那样死于大火，但是右手被严重烧伤，从那以后，他一直戴着一副厚厚的黑皮手套。",
