		height = "154cm",
		name = "海姆达尔",
		id = 1033,
		heart_chain5 = "海姆达尔始终认为科学的发展与理论研究是无可分割的，但偏移的理论绝对无法导向正确的结果。正因为如此，海姆达尔偶尔会请隐科组或者综合科的成员一起讨论某些方案的可行性，以此确认自己的想法是否合乎常理。\n然而她本人对沟通技巧的掌握十分粗浅，这样探讨问题的会议往往会到中途，就变成海姆达尔单方面的理论授课，继而转变为严肃到有些僵硬的学术问答。参与过讨论的成员除了大国主外，几乎都经历了专业理论用语的洗礼，以至于最后也没能理解海姆达尔想要阐述的想法，讨论通常也就到此结束。\n「要怎么让别人理解自己的想法呢……看来这也是一项值得研究的课题。」",
		heart_chain1 = "作为深空之眼中弥弥尔系统的开发者，海姆达尔却总是在听到弥弥尔的名字后不自觉地回避起来。倒不是因为谦虚，只是她很清楚现在的弥弥尔系统和她预想中的效果实在相差太多。\n虽然最开始一切都在按原有的设计有条不紊地推进，但是在全部完成后海姆达尔发现根本没人能够使用这套系统，于是她做了最为后悔的一个决定——开发代号为弥弥尔的AI，让他接入系统并自主学习。然而最后的结果并没有让她满意，AI的自主学习方向完全不可控，弥弥尔的心智也不知为何变成了现在这样……\n据说那之后，海姆达尔都没有再接手过与弥弥尔系统相关的维护工作。",
		plot_tip = "管理员，这项实验的用度麻烦审批一下。如果不放心的话可以来隐科组，我给你看看我的构想。",
		cv_ko = "윤은서",
		like = "理论研究、赛马",
		super_plot_tip = "管理员，有空的话来下隐科组，有些数据要你帮忙一起处理。",
		plot_tip_picture = "1033",
		cv_en = "Allegra Clark",
		age_en = "",
		cv_zh = "陈婷婷",
		cv_ja = "大西沙织",
		heart_chain2 = "自从弥弥尔系统的开发失败后，海姆达尔就陷入了很长一段时间的消沉期。她怎么也想不明白自己的发明怎么会偏离预期这么多，最后将一切归于自己的理论预测不足。也是这件事以后，海姆达尔在科研工作中变得十分慎重。她变得执着于获得一个稳定可控的结果，为此她经常会在验证理论的阶段就做足工作，直到她认为自己已经完全掌握了这次试验中可能会出现的所有情况，才会开始推进至下一个阶段。\n「那个理论派，大概是不会知道实践的乐趣了。」\n同为隐科组的大国主对海姆达尔这样的行为做出这样的评价。",
		organization = "深空之眼",
		heart_chain4 = "「大国主把太多的精力花费在奇怪的发明上了。」\n自从大国主加入隐科组以后，这里的成员总是能够感到终日弥漫在研究室中的激烈火花。感觉只要两人开始交谈，随时都有可能争吵起来。\n只要提及大国主，海姆达尔就会摆出一副头痛的样子。对她来说这个大国主除了理论知识丰富以外，完全不符合自己心中合格科学家的标准，不仅寡言少语，还经常没有理论依据地想到什么做什么，甚至连消灭视骸的理念都很淡薄。但实际上，海姆达尔还是非常认同大国主的研究实力的，只不过并不怎么表现在口头上罢了。",
		heart_chain3 = "不过几乎没人知道，海姆达尔并不怎么排斥赛马这项运动，甚至还会亲自去到比赛现场为相中的选手与马匹加油助威。\n因为优渥的家庭条件，小时候的海姆达尔就有机会在自家的马场里拥有一匹属于自己的赛马，海姆达尔为它取名叫做「金顶」。她的小马很快在地方赛事中崭露头角，尽管非常不舍，海姆达尔还是答应让小马去更高级的赛事试试。\n此后，她就养成了去看比赛的习惯，尽管小马现在已经退役，她也会把观看赛马作为放松心情的方式。大声呐喊助威的时候，或许也是她袒露情感，最真实的一面。",
