	[1034] = {
		birthday = "4月21日",
		height = "162cm",
		name = "瓦吉特",
		id = 1034,
		heart_chain5 = "在重大犯罪对策部的诸位行动组长中，瓦吉特算得上是年纪最小的一个，但这并不意味着她是一位不称职的组长。\n自当上行动组长之后，瓦吉特就一直在思考，该怎样当好大家的队长，该怎样为大家做得更多。\n被繁多工作所压垮疲惫不堪的队员时常会发现，自己的工作在不知不觉间便被某人悄悄解决。\n而那些被自己的实力所困扰，甚至变得自卑起来的队员则总会得到瓦吉特的悉心指导，瓦吉特甚至会将自己的笔记编纂成册交给对方，用不断提升的训练成功将对方带出自我怀疑的漩涡。\n但世间不如意十有八九，即便她努力想做到最好，帮助每个人，但现实中却有太多她所做不到的事情。\n自己是否真的在让世界变得更好？她逐渐无法对这个问题给出肯定的答案，想做的事情太多，想保护的人也有太多，可自己的双手能握住的东西却只有那么一点。\n一次任务结束之后，瓦吉特独自驱车来到海边，望着正在涨潮的海面发呆，自当上组长之后，她就常常来这里。\n过往的一切在脑内打转，她不知道自己究竟会成为被浪潮拍入海中的砂砾，还是被波涛不断磨削的礁石，又亦或什么都不是……\n曾经引导自己的纳伊达选择了离开，让自己看见那条光辉道路的前辈早已逝去，梦想依旧如天边的云彩般难以触及。\n从背后传来的声音打断了瓦吉特繁杂的思绪，不知何时小队的成员们也来到了这里。\n为了感谢这些日子里瓦吉特对自己的帮助，队员们想举办一场宴会，不过在办公室里却找不到瓦吉特，于是队员们便来到了她常来的海边。\n看着队员们的眼神，瓦吉特只觉得非常熟悉，曾经的自己也是用那种眼神看向前辈，就像看着向远方放射出璀璨光芒的灯塔，只不过现在……那座灯塔变成了自己。\n瓦吉特再次露出了那副队员们熟悉的明媚笑容，不知不觉间，绝不能放弃的理由又多了一个。\n就算梦想再遥远，她也会继续向前走，不仅是为了自己，更是为了这些相信自己的人们。",
		heart_chain1 = "瓦吉特，科尔盖重大犯罪对策部行动组长，代号「毒蛇」。\n然而大部分人看见这位明媚阳光的少女时，都没法将她与毒蛇这样的外号联系在一起。\n在以「严肃」为主旋律的科尔盖中，瓦吉特带领的小队算得上是异类，小队里总是充满了欢声笑语。\n不少刚入队的新人都曾对小队的状态感到诧异，毕竟这和他们认知中的科尔盖相差太远了。\n但实际上，小队的风格大多都会因为组长而发生变化，瓦吉特的小队也亦然。\n「就算整天板着张臭脸，问题也不会得到解决，既然如此，还是笑起来比较好~」\n即便面对着艰难危险的任务，瓦吉特也总是能保持那副明媚的笑容去面对，随后用自己的全力去解决眼前的挑战。\n不仅如此，在平日里她会亲自带着新入队的成员参观科尔盖内部的设施，帮助他们消除内心的陌生感，也会为辛苦工作的队员订上一杯奶茶，抚慰对方疲惫的心。\n瓦吉特的样子逐渐感染着所有队员，最终才造就了小队这副在科尔盖内称得上是「异样」的状态。\n支持瓦吉特的人将此当做她善良的证据，也有部分她的对手们将瓦吉特的行为视作装腔作势，但瓦吉特的行为其实并没有那么多深意。\n在科尔盖压抑的氛围中，大部分特工都被困在使命与工作的漩涡中无暇顾及任何事情，瓦吉特并不喜欢这样的氛围。\n正因如此，她才决定要从自己做起，让一切从身边改变。\n唯一的问题是，瓦吉特的的小队总是会接到大量新人的入队申请，出于小队人数的考虑，瓦吉特不得不拒绝大部分入队申请，据说这是她最近最苦恼的事情。",
		plot_tip = "管理员，这周末有空吗？如果你没有意见的话，小蛇可要来履行约定了噢~",
		cv_ko = "박리나",
		like = "收集墨镜、车辆模型、分享生活",
		super_plot_tip = "",
