		cv_zh = "Kiyo",
		cv_ja = "远野光",
		heart_chain2 = "瓦吉特的兴趣相当广泛，从看电影、吃甜食到收集车模、赛车都是她的爱好。\n瓦吉特像是有着用不完的活力与热情，她的假日总是被各种丰富多彩的活动充斥着，甚至可以称得上是忙碌。\n她会抓住任何一丝空闲时间，在网上调查各种新开的甜品店，随后前往品尝那些新品芭菲，也会亲自驾车驶向各大景点，感受着劲风吹拂脸庞的滋味与前所未有的景色。\n对于那些下班了就累倒只想躺在床上睡一整天的同事来说，瓦吉特的行为简直难以理喻。\n不过在瓦吉特看来，这只不过是理所当然的事情，时间总是有限的，但要如何度过这份时间则是可以由自己决定的。\n比起让自己的时间被繁琐的事务与疲惫的喘息占满，她更想把时间用来见证这个美丽的世界。\n「蛇……你连下班都在东奔西跑的，真的不累吗？」\n「你想想看，这可是我们拼尽全力保护的世界，当然要花时间好好看看它啦，这叫成果检验~」",
		organization = "科尔盖",
		heart_chain4 = "加入重大犯罪对策部后，瓦吉特便在纳伊达手下学习各种规章制度，办案方法，这位温和的前辈平日里总是对瓦吉特关照有加。\n可随着在小队里的时间越来越长，瓦吉特的疑惑越来越多，这位功勋卓越的大队长，平日里却老是一个劲叹气。\n 「纳伊达队长……是、是我搞砸了什么事情吗？」\n「哈啊……和你没关系，你已经干得很好了。」\n看着队长苦涩的表情，知道不会得到进一步答复瓦吉特只能把心里的疑问暂且咽下，更加努力的磨练自己。\n或许只要自己能够尽快成长，能够帮团队排忧解难，纳伊达大队长也就不会这么劳累。\n但时间不等人，从一项神秘任务中归来后没过多久纳伊达把瓦吉特叫到了办公室里。\n瓦吉特看着纳伊达止不住的叹气，听着她絮絮叨叨地讲了半天自己的理想，然后又自嘲地笑了出来。\n「蛇，所有人中你的成绩是最好的，但我最不看好你。在这个吃人不吐骨头的地方，天真是最致命的东西。」\n「你和我很像，所以我不想你走我的路。戴上眼镜活着吧，别让其他人看到你眼睛里的想法。」\n瓦吉特有些懵懂地听完，刚想要说些什么，纳伊达却已经转身推开门走了。\n那天晚上，瓦吉特想了很久，她始终无法理解，科尔盖为什么是吃人不吐骨头的地方？为什么不能让身为同伴的其他人看到自己眼里的想法？\n怀揣着越来越多的疑问，瓦吉特决心找纳伊达问个明白，迎接她却是更为冲击性的事实——纳伊达因触犯禁令，遭受处罚被抓入监狱，并且判处死刑。 \n疑问非但没有解决，反而在一个劲地变多，但此时无论谁都无法给予瓦吉特答案，队长到底为何触犯禁令？她临走前说的那番话又意味着什么？瓦吉特不知道。\n直到后来，瓦吉特决心了解真相，不断试着向上爬的时候，她才终于理解了当时纳伊达所说的话。\n所谓向上爬就意味着竞争，科尔盖内部并非万众一心，每个人都有各自的想法，那些被她视作同伴的人们也一样。\n某些心怀鬼胎的人就像是隐藏在黑暗中的猎手，会试着从你身上哪怕最小的动作中找到破绽，把你从高处拽下。\n当上行动组长的那一天，瓦吉特一口气买来了十多副墨镜放在柜子里，这样只要出门，她就能挑上一副心怡的墨镜戴上，用那厚厚的镜片隐藏心底的想法。\n不知不觉间，她已经习惯了这一切，没戴着墨镜她反倒会觉得自己缺了点什么东西，仿佛墨镜已经成为了自己的一部分。\n可即便如此，她依旧从心底希望着，某一天自己能够取下墨镜，抛下伪装地活着。",
		heart_chain3 = "完成科尔盖特工学院的训练后，瓦吉特迅速凭借优异的成绩被骸震对策部选上，破格作为在校实习生加入了骸震救援队伍，但支撑着她加入科尔盖骸震对策部的却仅仅只是一份略显模糊的憧憬。\n当她作为实习生参与科尔盖的工作后才发现，虽然身为实习生的自己只是担任后方支援的工作，但光是在后方看着就能知道，这些任务远比想象中艰苦，需要拼上性命才能完成的任务简直数不胜数，但前辈们却从未退缩。\n瓦吉特深知，仅凭像自己这样一份模糊的憧憬是不足以让人坚定到这个地步，但她却不知道到底是什么驱使着前辈们做到这个地步。\n直到有一次，视骸的数量多到本是后勤人员的瓦吉特都必须拿起武器战斗，但这突如其来的实战却是瓦吉特始料未及的，双手的颤抖一直停不下来，别说瞄准敌人了，光是抬起枪就废了她老大的功夫。\n「前辈……你们……都不害怕吗？」再也无法抑制内心的恐惧，瓦吉特向着前辈们发问。\n「怕啊……哪会有真的不怕死的人。」\n「但是这件事总得有人来做，总不能就这么拍拍屁股逃之夭夭，在我们身后还有千千万万的普通人，比起他们……至少我们还专业那么一点。」\n听着前辈们的话语，双手的颤抖也渐渐平息，瓦吉特发挥出了远超训练的水平，帮助队伍顺利完成了那次任务。\n战斗结束后，瓦吉特和前辈们一起在受灾的街区上巡逻，而那些被救的人笑着向瓦吉特她们招手，向她们送上感谢的话语。\n仅是如此，瓦吉特就感觉那些疲惫和伤痛都仿佛一扫而空，今天自己所做的一切是有价值的，她头一回觉得，自己似乎理解了前辈们奋战的理由。\n从那天起，原本模糊的憧憬逐渐变得清晰，化为了足以被称作是梦想的目标，她想让世界变得更好，直到有一天所有人都再也不会遭受危险，大家也不用再赌上性命去战斗。\n伴随着瓦吉特觉醒成为修正者，这个目标也似乎变得离她越来越近，但灾难却突然降临……\n那一天，瓦吉特所在的小队遭到了视骸埋伏，前辈们护着瓦吉特逃出包围圈，但代价却是除了她以外的小队成员几乎全灭。\n原有的一切都在眼前崩塌，是去是留，未来该怎么走？她不知道答案。\n被某种不知名的情绪驱动着，瓦吉特回到了第一次出任务的地方，望着已然修复的街道站了很久很久，等到她驱车离开时，心里已经有了答案。\n不论前方有怎样的艰险在等着自己，她都不会放弃，只因为她想证明一件事——自己所做的一切、大家所做的一切，都是有意义的，让世界变得更好的梦想也绝不是空谈。\n即便如此，毕业的同时，本就是在校实习生的她也因队伍解散失去了在科尔盖里的立足之地。\n就在这时，重大犯罪对策部的纳伊达向她抛出了橄榄枝，为了延续心中的梦想，她毫不犹豫地点了头。",
