		id = 1035,
		heart_chain5 = "索贝克原本有一副十分珍视的鳄鱼头套，甚至洗澡和睡觉时也不肯将其摘下。被长久地佩戴后，那副头套早就破烂不堪，甚至已经到了不得不换的地步。在他人的抗议下，奥利海姆不得不动用组织二把手的权力，命令索贝克摘下头套。\n令所有人意外的是，索贝克竟然在头套下长了一张帅气的脸，但他却无法以这副帅气的外表示人，失去头套的保护后，索贝克总是怀疑附近的阴影中潜藏着野兽，时刻准备向他发起袭击。这种恐惧让索贝克变得极度自闭，不愿意和任何人说话，整天蜷缩在角落里，时刻防备着偷袭。\n眼看着索贝克连日常任务都无法完成，奥利海姆只好委托一名工匠为索贝克打造了一副金属头盔，这样至少不会像索贝克之前佩戴的头套那样残破，也更容易清洁。\n索贝克如获至宝，这副头盔迅速成为了他新的标志物。但是他并没有抛弃之前的旧头套，而是将它好好地锁在了他的宝箱里。这副破烂的头套代表了怎样的一段过往，或许只有索贝克自己才知道。",
		heart_chain1 = "当戴着鳄鱼头套的索贝克第一次出现在罗斯塔赫，并试图模仿鳄鱼来吓跑陌生人时，理所当然地被路人当成了疯子。\n但是这些人并不了解的是，就在几天前城外的沼泽地中，索贝克正是利用相同的手段吓跑了几条与他夺食的野狼。而当他被一家面包店的香味吸引后，立刻准备再次利用这种手段抢夺那些令人垂涎的食物，随后遭到了几名壮汉烘焙师的暴揍。\n这个在荒野中长大，比起人类更像是野兽的孩子，最终还是误入了人类的世界，并获得了第一次教训。",
		plot_tip = "",
		cv_ko = "강호철",
