		cv_zh = "刘照坤",
		cv_ja = "小林裕介",
		heart_chain2 = "与其说索贝克是因为对迷铁之家伟大理想的向往而加入了这个组织，倒不如说是因为奥利海姆提供的那一顿饱饭。\n饥寒交迫的索贝克被奥利海姆收留并提供食物后，一边狼吞虎咽一边接受了奥利海姆的提议，正式成为一名赏金猎人。当时奥利海姆所论述的种种远大理想早已被索贝克忘记，但那顿饭的香甜滋味却被深深地刻印在在索贝克的脑海中。从此索贝克成为整个迷铁之家最忠于组织的人，平时称呼奥利海姆为大哥，伊森为大大哥，零一为大姐头。",
		organization = "迷铁之家",
		heart_chain4 = "包装完整的速冻食品、尚未打开的罐装饮料，硬到难以下嘴但很适合长期保存的面包……诸如以上种种，都是索贝克心仪的「收藏品」，他会将这些东西仔细收集起来，然后锁进他房间里的那个宝贝箱子里。\n直到某次奥利海姆误入索贝克的房间，并看到了那堆小山一样的罐装饮料后，才发现了索贝克的囤货习惯。奥利海姆试图向索贝克解释「保质期」这种概念，但索贝克坚称这些东西会在连续几天找不到食物的饥荒中起到大作用，并拒绝把他的「收藏品」丢进垃圾箱。\n奥利海姆清楚地知道，即便是在以贫穷著称地罗斯塔赫也很少发生连续几天的饥荒，但他准备强硬下令时从索贝克的眼中看到了某种令他不愿触及的过往。最终，奥利海姆又给索贝克买了两个带锁的大箱子，并要求索贝克至少保证房间的整洁。",
		heart_chain3 = "索贝克拥有一副几乎从不离身的双刀，这副双刀早已锈迹斑斑，似乎随时都会折断，但却总能帮助索贝克抵挡各种先进武器的攻击。\n奥利海姆曾经被好奇心驱使而询问这副双刀的来历，而据索贝克所说，这副双刀来源于一次危险的狩猎：在数年前的一个雷雨交加的夜晚，作为猎人的索贝克反被猎物盯上——那几条野狼狡猾地联手，将索贝克逼退到能够吞噬生命的沼泽泥潭。无路可退的索贝克强烈地希望能获得对抗这些野兽的武器，而就像是为了回应他的希望一般，他那陷入污泥中的双手立刻摸到了这副双刀的刀柄……\n这种讲述神话般的口吻并没有让奥利海姆对索贝克手中的锈刀产生敬意，不过考虑到组织最近物资短缺，奥利海姆还是决定请人帮忙给这副双刀做防锈处理，这样就不用为索贝克配备新的武器了。",
