		name = "霍德尔",
		id = 1037,
		heart_chain5 = "自从巴德尔被智骸袭击的事件发生以来，霍德尔变得更加沉默寡言，很多时候都只是默默在病床边陪伴着姐姐。但她知道，仅仅在这里消沉下去也无济于事，如果姐姐醒来看到自己颓废的样子，大概也会很失望吧。\n于是，像是要摆脱以往沉默纤细的形象一般，霍德尔不仅接手了情报科的全部事务，甚至开始更加频繁进入训练场，并近乎苛刻地在战斗中提升着自己。她急切地为自己套上了强硬的面具，展示出越来越多偏执主动的一面，似乎想借此来掩盖内心的脆弱和思念。\n「想要成为姐姐那样独当一面的战力。」\n「想成为值得骄傲的妹妹，无损姐姐名声的妹妹。」\n————出于这些无论如何也想实现的愿望，现在的霍德尔在一步步艰难地向前，摸索着成长。",
		heart_chain1 = "她喜欢一个人默默在图书室里看书，耳机里总放着古典的交响乐，直到被人提醒要关门时，才会害羞地露出抱歉的笑容。\n霍德尔的羞涩以及内敛是她留给大部分人的第一印象，这大概是因为她在对待身边的人事时，总是表现得小心翼翼。平时和其他人的交流也仅限于情报之上，除此以外的大部分时间，都是伴随着古典音乐一个人度过。大部分人不知道的是，霍德尔私下对古典音乐有相当独到的见解，不过这些她也很少和姐姐以外的人提起就是了。",
		plot_tip = "管理员，我有比以前更帮到大家和姐姐一点吗……",
