		cv_zh = "谢莹",
		cv_ja = "藤田茜",
		heart_chain2 = "霍德尔与姐姐巴德尔，两人从苏醒之后就从未分开，一起生活学习，甚至连觉醒时间都是相近的。姐姐对霍德尔来说就是最亲近的人，有很多事也只会和巴德尔才会说起，甚至偶尔在外人面前提到姐姐时，霍德尔也会少见的露出略微激动的神情。\n实际上第一次听说两人其实是姐妹的人，多少都会表现出一些难以置信，因为她们的性格差距实在过于巨大了。\n相比于姐姐表现出的大胆和外向，霍德尔更像是隐藏在角落里的槲寄生，安静而纤细。不过也因为这份细心，通常霍德尔会负责大多数情报科的数据处理工作，虽然是繁琐枯燥的过程，但是她依然能够有条不紊地做到最好，这样的能力是连休也赞叹不已的。",
		organization = "深空之眼",
		heart_chain4 = "霍德尔很清楚的是，姐姐为了照顾自己究竟付出了多少努力。因为寄生型权钥的活跃，霍德尔每晚都被折磨的无法入眠，是姐姐一刻不休地每晚陪在自己的身边。即使在加入深空之眼，权钥得到抑制后，这点也没有任何改变。\n而实际上，相比情报工作，霍德尔知道姐姐其实更擅长参与作战科的任务，但她还是为了照顾自己而申请调来情报科。\n虽然活泼的姐姐偶尔也会闯下不大不小的麻烦，后果往往都是由霍德尔来受累收场。这样看起来令人操心的姐妹关系，实则是姐姐想为自己带来笑容和自信的方式，对这一点霍德尔也了然于心。\n「你在想什么啊，霍德尔当然也是很厉害的呀。没有霍德尔的话，我面对这堆复杂的资料肯定会手忙脚乱的~」\n曾经这样乐观地说出这句话的姐姐，现在却躺在病床上昏迷不醒。霍德尔握住她的手，默默为姐姐祈祷着。",
		heart_chain3 = "当然霍德尔也有不曾与姐姐提起的烦恼，明明和姐姐几乎是同一时间加入的深空之眼，但直到现在自己也没能成为正式的作战成员，而身边的人都已经和她逐渐拉开了差距。这让她开始变得有些不自信，对于自己的能力产生了怀疑。以至于每天都会在情报工作结束后，去训练室待上很长时间，甚至会把自己弄得到处是伤。但即便如此努力，霍德尔离自己的目标却似乎还是很远。\n想要成为作战成员并不都是为了自己，也是出于想要为姐姐分担工作的想法，想用这样的方式回报姐姐对自己的照顾。不过现在的情况绝对称不上是乐观，霍德尔稍微有些陷入了迷茫当中。\n「不能辜负姐姐的期待……」",
