	[1038] = {
		birthday = "7月21日",
		height = "165cm",
		name = "赫拉",
		id = 1038,
		heart_chain5 = "在诸多不能容忍的事项当中，有一项对赫拉来说是绝对的禁区，那就是毫无美感的事物，或者再确切一些，无法欣赏「美」的人也在她厌恶的范围之内。\n在她看来，世间的一切都应该是高雅的，而因为有审美低下者存在，毫无美感的俗物居然也能心安理得地出现在自己的视线之中。那么她也有必要教会他们「何为美」，或者在俗物污染自己的目光之前，让它们彻底消失。\n所以，在她面前，你最好能做到举止得体。或者至少，多多夸赞几句她当日的装扮。",
		heart_chain1 = "作为早期觉醒的修正者之一，赫拉将大量的时间花在了研究人类贵族礼仪以及各种名流聚会上。优越感让赫拉无法将人类这种生物当作是平等的存在，但对于其中孺子可教的部分，赫拉也愿意大方慷慨地教授她们淑女的知识，前提是她们对自己表达了绝对的取悦和崇拜。",
		plot_tip = "管理员，好好见证真正的优雅与美丽吧！",
		cv_ko = "소연",
		like = "出席各类名流聚会、举办茶会",
		super_plot_tip = "",
		plot_tip_picture = "1038",
		cv_en = "Penelope Rawlins",
		age_en = "",
		cv_zh = "卓思源",
		cv_ja = "植田佳奈",
		heart_chain2 = "赫拉不仅擅长礼仪，在舞蹈、声乐、鉴赏甚至是常人极少涉足的哲学、政治领域都极为精通。\n优雅的美貌、淑女的气质、以及在各种聚会和茶会上的表现，让赫拉在人类社会、尤其是欧莫菲斯的名流圈中颇具名望，也因此收获了一大批狂热的追求者和粉丝。\n因为高贵所以仰视向往，因为耀眼所以低眉俯身，赫拉对于这些名流们来说就是这样的存在。\n但在满是仰慕者的欧莫菲斯，也有个让赫拉无法忍受的存在\n——铃兰骑士团团长雅典娜，光是提到这个人的名字，赫拉便会气得牙齿发抖。\n以「聚集众多知名艺术家需要提前报备」为由，雅典娜率领自己的铃兰团多次叫停了赫拉举办的茶会，这位骑士团长似乎除了城市安宁和市民的安全外，并不把任何东西放在眼里。\n「哪有开茶会还要报备的道理？这样一点也不优雅！」",
		organization = "缪斯协会",
		heart_chain4 = "其实最初接到哈迪斯的邀请时，赫拉多少有些不情不愿：她的时间还没有多到有空去鉴赏一些稀奇古怪的行为艺术。但对于哈迪斯，这位星虹议会的议员之一，赫拉还是抱有足够的敬意。不论是在艺术造诣上，还是原初的知识，赫拉知道这些是现在的自己还比不上的，或许加入「缪斯」也并非全部都是坏事。\n另一方面则是，哈迪斯答应为赫拉安排正宗欧莫菲斯风格下午茶，每天都有。",
		heart_chain3 = "因为赫拉在艺术领域的才气在欧莫菲斯备受瞩目，也有不少协会向赫拉发来了邀请，不过都被她一一谢绝了。但据说早些年的时候，也曾有人在「缪斯协会」见过这位才气斐然的大小姐，不过说到底也只是传言，考虑到赫拉的年龄以及早已人气低迷的「缪斯」，大家都觉得这并没有什么可信度。\n「啊，又开始下雨了呢。」\n赫拉举起手中的红茶杯，看向「缪斯」窗外的天空。",
