	[1039] = {
		birthday = "3月21日",
		height = "164cm",
		name = "波塞冬",
		id = 1039,
		heart_chain5 = "一直成为他人「港湾」的波塞冬，平时是怎么化解自己的情绪的呢？\n「该不会，她一直都一个人默默承担了所有吧？」\n这样担心着的管理员，曾经就这个问题去问了和波塞冬相识最久的休。然而在了解到管理员的担忧后，休却显得并不在意。她在得到管理员保密的许诺后，将终端内的一份视频发送给了管理员。\n——视频里，波塞冬只穿了一件睡衣地坐在床上，眼睛红红、脸颊鼓鼓的，时不时还用捏紧的拳头锤几下怀里的枕头。\n「这……是在干嘛？」\n「她看了新闻里有关人类污染海洋的报道，然后就气成这样了，我当时觉得她生气的样子很可爱，就偷偷拍了下来。」\n「原来波塞冬也会有这样的一面啊……」\n「是啊……只是她的偶像包袱很重，你小心别让她看到这个视频。」\n管理员点了点头，然后悄悄把视频收藏进了终端里。\n——虽然一直都扮演着“知心姐姐”的波塞冬很迷人，但果然还是看到了这样一面的她，才能更坦然地接受那一份温柔呀。",
		heart_chain1 = "波塞冬与休是同期加入深空之眼的好友。和休认真、正经的性格不同，波塞冬显得更加温和与洒脱一些。所以当她被推荐为第九部门的管理人员时，波塞冬也谈到自己性格不合适，转而推荐了自己的好朋友休。\n在管理层选拔结束后，波塞冬除了执行任务，基本就不再参与深空之眼的其他事务。她喜欢假期时独自去往海滩，哪怕只是什么都不做地躺在沙滩上感受着海风，也能让她感到幸福和满足。\n有时休也不由得好奇，透过那对碧蓝色的眼眸，波塞冬眼里的大海是什么样子的？",
		plot_tip = "管理员，无论什么时候，这里都是你可以停靠休憩的港湾哦。",
		cv_ko = "김가령",
		like = "观海、收集海豚饰品",
		super_plot_tip = "管理员，有任何烦心事，都可以告诉我。",
		plot_tip_picture = "1039",
		cv_en = "Sophie Shad",
		age_en = "",
		cv_zh = "陶典",
		cv_ja = "佐藤利奈",
		heart_chain2 = "波塞冬很擅长倾听烦恼与安抚情绪。平时不苟言笑的休在被新人们搞得焦头烂额时，也都会选择来自己的“心灵港湾”波塞冬这儿寻求安慰。\n「诶，管理员，你也有烦恼想和我倾述么？」\n「好啦好啦~没关系，有什么不高兴的事情可以都通通告诉我哦。我的话，就算被当成是大家情绪的垃圾桶也很乐意~」\n听说找波塞冬做完“心理咨询”的人，都会获得一个海豚玩偶的小挂饰，真不知道她到底批量采购了多少这种东西……",
		organization = "深空之眼",
		heart_chain4 = "还未成为修正者时的波塞冬，曾经只是个热爱大海的小女孩。每日最喜欢的事情就是在海中畅游，望着那绚丽的珊瑚，还有水中变幻多姿的鱼群。\n有一天，波塞冬跟随鱼群潜入到了过于危险的深度，当她发觉不对时，身体已经因为力竭无法动弹。在快要绝望之际，她看到了一只优美的白鲸从身前游过，悠扬的鲸歌在深海中像灯火一样让她不自觉地循去，身体被海浪推送着，无数美丽的鱼儿围绕身旁。\n等她再恢复意识时，自己已经安全回到了沙滩上。也是从那时起，她便知道温柔的海洋一直都在守护着她。",
		heart_chain3 = "节假日的时候，同事们经常会看到波塞冬在街道和商城里分发“海洋保护协会”的活动传单，传单的背面，波塞冬的名字居然位列荣誉副会长之席。\n据休说，波塞冬仅仅用了两年时间就自学成为了海洋科学的学者，因而被协会选为了荣誉副会长。\n很多人认为她的当选是由于其精深的知识，但或许更重要的原因是，当她在谈及海洋时，双眸中所透露的那股热情和真挚，不知不觉就将他人感染了吧。",
