	[1041] = {
		birthday = "9月1日",
		height = "170cm",
		name = "雅典娜",
		id = 1041,
		heart_chain5 = "「赫拉，你已经涉嫌非法聚集艺术家，现在立刻停止茶会，否则我们将会以上述罪名将你带回审讯！」\n「本小姐只是在举办茶会而已。你管得未免太宽了吧，雅典娜……」\n「最后警告一次，我以铃兰团的名义责令你立刻停止活动。」——节选自《铃兰团执法记录第六十四期》\n以上的对话几乎每周都会在各种上流场所发生，铃兰团的成员们早已见怪不怪了。毕竟团长雅典娜也算秉公办事，要知道雅典娜从来都把秩序和规则看得比生命还重要，只要威胁到这些，不管是谁她都会竭尽全力地与之对抗。\n这种超乎寻常的责任感和荣耀感也使她与周围的人格格不入，久而久之几乎所有人都将雅典娜当成崇拜和瞻仰的对象，平日也没人见到她有什么亲密的朋友。可是知名人士赫拉小姐却从不把她放在眼里，三番五次挑战雅典娜容忍的极限。长此以往，两人的关系在旁人看来与其说是对头，不如说更像是能平起平坐的「朋友」，至于其中的渊源，或许要从一场提琴比赛的胜负说起……\n「你们别看团长每次都咄咄逼人的，我倒是觉得她们关系还算不错。」看似知情的铃兰骑士如此说道。",
		heart_chain1 = "「团长大人，巡逻已经完成了。」\n「辛苦了，你先去换班休息吧，之后我会再去巡查一遍。」\n「好，您也……要注意休息……」\n对于雅典娜这样看似有些不必要的重复行为，铃兰团的成员们早已经习惯，不如说这才是他们认识的那个拥有强烈责任感的团长。而这些年铃兰团在雅典娜的领导下，也确实将欧莫菲斯的治安提升到了新的高度。\n几乎没有人愿意在这位团长的眼皮子底下犯事儿，哪怕是随手扔掉垃圾，也很快会因为影响市容被雅典娜亲自问责。更遑论破坏或者偷盗艺术品，那将面对的是雅典娜的严惩。\n从没有人见过这位执法者真正休息的时候，几乎所有事情她都会亲力亲为，这在外人看来近乎是一种对自己的折磨，但雅典娜却认为这些只不过是自己应该尽到的职责。",
		plot_tip = "欢迎回来，欧莫菲斯的荣誉市民……我的挚友。",
		cv_ko = "정유정",
		like = "大提琴、骑马",
		super_plot_tip = "嗯……像这样邀请朋友来家里过夜，还是第一次。",
		plot_tip_picture = "1041",
		cv_en = "Amber Lee Connors",
		age_en = "",
		cv_zh = "杜晴晴",
		cv_ja = "小清水亚美",
		heart_chain2 = "幼时的雅典娜本该像其他失去家庭的孩子一样被孤儿院接收，但凯琳·帕拉斯看中了她的身体潜质，收养了雅典娜并将她作为铃兰团的一员进行培养。所以雅典娜从小就是在骑士精神的教育中成长起来的，一直以来也都在以成为优秀的铃兰团骑士为目标。\n像是为了报答凯琳一般，她总是对自己有着更高的要求，在整个帕拉斯家族中也是最努力的存在，本就有着优秀天赋的雅典娜在9岁那年成功通过了铃兰团的考核，成为最年幼的铃兰骑士。\n「能看着你成为铃兰骑士，我很欣慰，雅典娜。」\n「希望你能代替我继续带领铃兰团，守护好欧莫菲斯。」\n这是祖母，也是铃兰团的创始人凯琳·帕拉斯在弥留之际对雅典娜的期望。而曾经从祖母口中了解到欧莫菲斯黑暗过去的雅典娜，也下定决心不会再让这样混乱的时代重演。\n欧莫菲斯的制度不容被破坏，铃兰团的荣耀也不容任何人玷污，背负着这样沉重的责任，雅典娜一刻也不容许自己松懈。哪怕是成为修正者后，这份职责与使命也超越了修正者的自觉。雅典娜拒绝了来自哈迪斯的邀请，继续留任铃兰团，她不允许自己辜负祖母的期望，却也在执念中越陷越深。",
		organization = "铃兰骑士团",
		heart_chain4 = "据说在雅典娜的办公室中摆放着一把大提琴，但却从未见她演奏过。曾有人在准备汇报工作时看见雅典娜对着大提琴说话，这件事被团员们一致认为是雅典娜实在太累了，所以才做出这样的举动。\n实际上团员们不知道的是，雅典娜除了剑术外，在音乐方面也有不错的天赋。而其中她最擅长的便是大提琴，甚至早已通过了提琴协会的考核并取得了从业资格证，换句话说，即使雅典娜想以大提琴表演家作为职业都并非难事。\n只是在接任铃兰团团长以后，她已经鲜有时间再触琴弦了，压力、责任这些东西偶尔会让她有些喘不过气。以一己之力揽下重任的少女，只有看着这把祖母赠给自己的提琴时，才会卸下自己的伪装与防备。\n「祖母，如果你还在的话，一定会告诉我怎么做才是对的吧……」",
		heart_chain3 = "9岁进入铃兰团，16岁成为铃兰团团长，这样的经历在旁人看来有些不可思议，但对雅典娜来说只是迈出了第一步。她早就认定了目标，为了守护欧莫菲斯百年来的秩序，这是自己必须要走的路。\n但当她胜过自己的兄长阿尔戈，确定接任团长之位的那一刻，周围也出现了许多反对的意见，不仅仅是因为她的年龄，也因为她在那场胜负中当众指认阿尔戈的舞弊事实。这件事被揭露的那一刻，也意味着帕拉斯家族多年来积累的名誉和声望都毁于一旦，当然也包括雅典娜自己。\n「她让家族蒙羞」、「她肯定也是一伙的」诸如此类的声音不断传入雅典娜的耳中，她却没有展现出丝毫的退怯，依旧出任了团长一职，而代价则是被阿尔戈以族长之名从帕拉斯家族中驱逐了出去。不过彼时她早已无暇顾及这些，制定规范、实行新策，雅典娜想要守护的东西远比所谓的家族荣誉还要高远，祖辈留下的秩序与作品不容玷污，她是靠着这样的信念一路走来的。雅典娜出色的工作能力带来了立竿见影的效果，在短时间内完美处理了多起重大事件后，团员们对于这位强大而又有责任心的团长就只剩尊敬了。\n「如果是雅典娜团长的话，一定能带领铃兰团守护欧莫菲斯的现在与未来。」",
