	[1042] = {
		birthday = "1月31日",
		height = "173cm",
		name = "哈迪斯",
		id = 1042,
		heart_chain5 = "「啊，关于哈迪斯她啊，本小姐只有一个忠告要给你，别太相信她表面上的样子。」\n「哈迪斯姐姐的梦，黑色的……」\n「哈迪斯大人的命令是不可以违抗的。」就像这样，如果要打听关于哈迪斯的事，大概率会从与她相识的人口中听到这样可怕的评价，但实际上又很难将诸如「可怕」、「恐怖」这类形容词与眼前笑盈盈的优雅女士结合在一起。这当然只是表象，又或者说，只要没有见识过哈迪斯对待敌人的态度的话，大概不会有机会了解到她的另外一面：如同戏耍猎物的猫科动物一般，她在给予敌人致命一击前会尽情地将它们当做人偶玩弄于掌心之中。哈迪斯本人好像特别中意这种掌控的感觉，对她来说，战斗本身就是演出的一种。\n「哼，虽然不像话，但你们最好不要与她为敌。」——来自某不愿透露姓名的雕刻家。",
		heart_chain1 = "若干年前的欧莫菲斯，曾盛行过一次人偶的热潮，其源头是一家开在街角的人偶馆。低调又暗沉的店铺外表很自然地融入到周围的环境中，甚至不仔细观察都很难会注意到店门的存在，但若是推门进去，就又很快会被内部奢华的装修所吸引，随后便会注意到挂在墙上琳琅满目的各种商品——各式制作精妙的人偶。\n对于彼时的欧莫菲斯来说，人偶算是新鲜的东西，在此之前也并没有谁听说过有谁以制作人偶为生。但当栩栩如生的人偶被展出后立刻引起了社会层面的轰动，他们一致认为这样的作品甚至可以称得上是艺术。于是越来越多的人慕名前去那家店中观摩购买，甚至还能留言订购自己想要的款式。随后购买人偶逐渐发展成一股社会性的风潮，人偶艺术在短时间内被承认，越来越多的人开始争相模仿，甚至有传闻说那位阿尔蒂斯也慕名光临了。\n「我当时可没想这么多」事后加入了星虹议会的店主哈迪斯如此说到。",
		plot_tip = "管理员，想不想成为世界上最可爱的人偶呢？",
		cv_ko = "박의주",
		like = "人偶、剧场演出",
		super_plot_tip = "",
		plot_tip_picture = "1042",
		cv_en = "Cat Protano",
		age_en = "",
		cv_zh = "黄莺",
		cv_ja = "斋藤千和",
		heart_chain2 = "「老朋友不在之后，很多事情只能靠我们来替他完成了。」\n「只是没想到会这么劳神……我想先回去好好休息一下了。」\n「你有空发这些牢骚，不如多处理几份文件。」\n每当哈迪斯发表出这样的言论，通常只会收获一旁欧申纳斯冷漠的白眼。这倒并不是因为两人的关系恶劣，相反，正是因为他们都见证了星虹议会与欧莫菲斯的发展全过程，才更能明白阿尔蒂斯生前坚持的理念是多么的正确。而哈迪斯作为修正者，自然也清楚自己有责任和义务维护老友拼尽毕生创造的局面。只不过评议员这个身份对她来说并不意味着享受权利，更像是繁琐事务的代名词。不得不处理公务之时，哈迪斯总会想起以前在人偶馆的日子，随后开始发出连连的叹息：\n「啊~要不让明塔和琉刻来学习一下怎么处理这个吧……」",
		organization = "缪斯协会",
		heart_chain4 = "「您好，欢迎来到非常规艺术鉴定协会。」\n「你是来接受考核的吗……是吗，那么请开始您的展示吧，结果会由我们来评定。」\n虽然现在已经鲜有人来接受考核，但每一个来过这里的人都会对两位孩童模样的女仆印象深刻，尤其在她们自称是主考官后。不过会这样震惊也并不能怪他们，毕竟根本没人会想到她们只是哈迪斯安排管理协会的人偶。而这对双生子也代表着哈迪斯在人偶艺术上最高的造诣，她们有着如同真人一般精致的脸庞，神力的加持使她们拥有思维和心智，至于为何是孩童一般的体型，大概只能理解为是哈迪斯的个人喜好……总之在哈迪斯的教导下，除了战斗以外两人还会负责照顾所有的协会成员，后来随着她们学习知识的增加，哈迪斯也开始将协会事务交由她们一并打理，只是作为考核者，她们的标准或许还需要多加调整。\n「用鼻子吃意大利面吗……嗯，确实是很特殊的才艺，明塔你怎么看？」\n「明塔觉得琉刻说得对。」\n「好，创作者，你被认可了，现在授予你创作家从业勋章。」",
		heart_chain3 = "目前哈迪斯所在的缪斯协会也拥有颁发从业证书的资格，这里接纳一切罕见、独特，甚至闻所未闻的艺术形式，并且予以认证。因为有着相当高的通过率。曾经是最受艺术创作家欢迎的协会。只不过因为近十几年来的改制，大部分非常规艺术的创作者都难以被世人所认可，所以也就逐渐变得鲜有人来了。\n「老朋友，时代真的变了呢……」哈迪斯望着有些冷清的门厅，低声呢喃道。现在的多数人都并不知道缪斯协会的前身，就是早已消失许久的人偶师协会，在人偶狂潮席卷欧莫菲斯的那段时间，有许多人投身进这项新兴的艺术中来。但他们很快就发现无论如何都没办法超过哈迪斯所创作的人偶，期望从业者也就逐渐消退了热情，人偶协会自然也就逐渐没落。\n哈迪斯在与阿尔蒂斯谈话后明白这样的发展对当时的欧莫菲斯来说是不健康的，为了鼓励自由创作的氛围，于是将人偶协会改制为缪斯协会并鉴定非常规的艺术，这从现在看来也不失为一项大胆的决定。今时今日的缪斯协会，更多的是在哈迪斯的带领下解决着发生在欧莫菲斯的视骸威胁，算是这座艺术之都的，隐形的守护者。",
