	[1043] = {
		birthday = "11月30日",
		height = "159cm",
		name = "伊里伽尔",
		id = 1043,
		heart_chain5 = "伊里伽尔知道自己失明的原因。\n在诞生之前，伊里伽尔尚未在心象房间中培养完全，其视觉系统尚未完成。但由于罗斯塔赫发生紧急骸震，她被临时「投放」，因此以双目失明的状态苏醒，只能感知到骸能的大致方位——仅仅作为消灭视骸的「工具」而言是合格的。她遵循修正者的本能攻击视骸，却完全无法抵挡来自视骸以外的伤害，倘若没有伊什塔尔，她多半会在骸震结束后丧命。因此，伊里伽尔曾度过一段消沉的时间。她时常认为自己是被盖亚用之即弃的消耗品。\n伊什塔尔也曾开导她，生命不属于其他人而属于自己，倘若再这样消沉下去，反倒是在漠视自己的生命。而且，就算她不被盖亚需要，至少也被其他人需要着。可是，在彼时周围人泛滥的善意之中，伊里根本感受不到自己被需要。\n直到来到阿卡德公会，只看实力说话的赏金猎人们并不在意她的缺陷，伊里终于感受到「平等」的对待。\n每当听到同伴的称赞，伊里嘴角的弧度就会变得格外明显。曾有成员说，「伊里就算失明也能跟别人做得一样好，那样就是比别人更厉害了一大截」。这样的说法使伊里幡然醒悟——自己极力避讳的缺陷，其实也正是自己的独特之处。阴霾一扫而空，伊里不再对自己轻薄的命运耿耿于怀，而是接纳了这一切。\n她不会停下脚步。走过更长的路、结识更多同伴、保护更多生命，她会一直走下去，为自己赋予价值，以证明自己摆脱了身为消耗品的命运。",
		heart_chain1 = "「只要有伊里在，大家就什么都不用怕啦！」\n身为阿卡德公会的核心成员之一，伊里伽尔主要负责护送任务的统筹安排，并参与部分可能存在一定危险的任务。\n公会内部存在一个关于伊里伽尔的传言：在一次任务中，路线情报遭到泄露，队伍遇到一大群有组织的歹徒。当时伊里在远处掩护，她仅凭手中的弓弩独自一人杀死所有歹徒，没有误伤一位队员，而队员们驾驶着载具碾过歹徒的遗体与血泊……\n当然，这是好事者添油加醋而成的。实际情况是，伊里用麻醉弹击晕歹徒的首领，见首领晕倒在地，其他小弟们一哄而散，让大家哭笑不得。不过这只是个插曲，那次任务主要的危险实际上是半路遭遇的视骸。队伍里没有其他修正者，伊里独自一人消灭视骸群，保护了大家。好事者编造的故事或许脱胎于此。\n也正是那次任务以后，伊里伽尔的名字在公会里传开，她得到了马尔杜克的赏识。大家信赖这位可靠的保护者，常说「我们护送货物，伊里负责护送我们」。\n在日常生活中，伊里也为大家帮上不少忙。公会中许多成员的装备饱经风霜，多有磨损，伊里能够从枪支上膛的声音听出其中隐藏的异常，及时修理避免危险。除了武器装备以外，朽烂的地板、链条生锈的吊灯、漏气的车胎……在加入阿卡德公会的头一个月里，伊里做了无数类似于「安全隐患排查」的工作。倘若没有伊里在，恐怕公会里要多好几个被天花板砸到脑袋的倒霉蛋。",
		plot_tip = "",
		cv_ko = "",
		like = "养猫",
		super_plot_tip = "",
		plot_tip_picture = "1043",
		cv_en = "",
		age_en = "",
		cv_zh = "筱筝",
		cv_ja = "五十嵐裕美",
		heart_chain2 = "伊里伽尔以完全觉醒的状态诞生于灰塔事件引发的骸震中。天生的失明致使她极易受伤，几乎在这场动荡中丧命。好在，另一位名为伊什塔尔的修正者发现并救下了她，使她幸免于难。\n伊里伽尔将伊什塔尔称呼为姐姐，她在姐姐的家中度过了一段平静的时光。邻居们的心地都很善良，自从知道新来的女孩双目失明，时常来看望她。\n然而，周围人的善意反倒使伊里伽尔感到痛苦。她想试着自己做一顿饭，邻居发现后，立刻跑来让她放下手中的厨具，并将自家的饭菜端给她；她想出门透气，却被好心人当作迷路的孩子送回家去；甚至某些时候，她想要自己捡起落在地上的发卡，都会有人先她一步为她代劳。每当她鼓足勇气想要尝试独立完成某件事时，人们总会不请自来，最后她什么也不需要做。久而久之，她产生了一种无力感：她无法亲手完成自己想做的事，感到生命不属于自己。尽管伊里伽尔在无人的夜晚偷偷苦训自己的剩余四感，并且已经完全能够弥补视觉的缺陷，但邻居们仍然像从前那样对待她。\n「我不是病人、残疾人、弱者，我是伊里伽尔，我跟你们一样！」伊里伽尔的心声被善意淹没，她终究没法将这愤怒说出口。\n直到认识了「工匠」，伊里伽尔第一次感受到何为平等。伊里伽尔听闻附近公会有一位厉害的手艺人，没有人知道她的姓名，只有「工匠」的名号远近闻名。于是她带上自己打零工攒下的钱，找上了这位「工匠」。\n伊里伽尔说不清自己要什么，只能含糊地说，「我不想被当成弱者了。」\n「那就一套感官辅助强化装备，现结。」「工匠」只是看了伊里伽尔一眼便给出了方案，顿了一下之后，「对了，我还有别的方案。感兴趣的话，明天早上来我这。」\n自此之后，「工匠」便时常带着伊里伽尔参加各种户外活动，从徒步到攀岩，从钓鱼到冲浪，让伊里伽尔有了新的体验。\n从来没有人会邀请伊里伽尔参加这些「危险」活动。伊里伽尔曾经问过，「其他人看见瞎子做危险运动时是怎么想的？」\n「瞎子怎么了，我只有一只手，照样是最厉害的工匠。」「工匠」让伊里伽尔摸摸自己的左手，伊里伽尔触碰到的却是空荡荡的袖管。伊里伽尔这才发现，如果「工匠」不主动提起，她根本不会注意到「工匠」身体的残缺。卓越的技术掩盖了一切，在大家口中，她只是一名技术超群的工匠，而非断手的工匠。\n「只要厉害到一定程度，那大家就会忽视其他事情……」这样的想法在伊里伽尔心中萌芽。\n她想成为厉害的人，直到别人提起她的名字时，不再加上「可怜的」「脆弱的」的前缀，而只是「伊里伽尔」。",
		organization = "阿卡德公会",
		heart_chain4 = "赏金猎人的工作为伊里伽尔带来了更多积蓄，为了更好地完成任务，伊里伽尔找工匠制作了一台小型辅助智械，并将其取名为「奈提」。伊里伽尔并没有将奈提看作一台单纯的智械，她时常会去郊外与奈提玩捕猎游戏，无论奈提有没有寻得猎物，它归来时都会乖巧地站在伊里伽尔手臂上，而伊里伽尔也会摸摸它光滑的脑袋，就像鹰猎人与她最信任的猎鹰。\n奈提的初始设定是一台能够「协助」与「保护」使用者的智械。在「协助」伊里伽尔这方面，奈提发挥了100%的功用。在战场上，伊里伽尔会放心地将后背交给奈提，因为她知道奈提能够提供最准确的情报，辅助她进行攻击。久而久之，伊里伽尔发现拥有自我意识的奈提发展出了自己的个性，在任务中，它不时会说些俏皮的话语活跃气氛，而伊里伽尔也逐渐能和它有来有回地互相打趣。相比之下，作为备用机的「奈奈」因为出勤次数较少而更为冷静与克制，语言更简洁明了。\n这样智能的辅助机，在生活上也为伊里伽尔提供了很大帮助。伊里伽尔能够接住别人递过来的饮料，避开街上突然冲出的车辆，或者避开雨天出门，这些都多亏了奈提的信息收集与预测。\n只不过，奈提偶尔会显得过于「智能」。伊里伽尔的特殊之处偶尔会引起不明真相的路人的打量与议论，而在奈提眼里，这些都是对伊里伽尔的恶意，为了避免伊里伽尔遭受伤害，奈提会自动为伊里伽尔过滤这类信息。某一次，一个好事者故意在伊里伽尔背后向她投掷石子，以此测试她是否真的双目失明，奈提见状启动了防卫模式，想在不惊扰伊里伽尔的情况下驱赶对方，最后却被石头砸出了一个窟窿。\n在对奈提进行维修时，伊里伽尔一边仔细地为奈提做着检查，一边告诉奈提，在奈提宕机的时候，好事者已经被她「收拾」掉了。\n「奈提是我的眼睛，所以别人的目光和奈提为我做的事情，我一直都能看到。但是，我不想看到奈提为了我受伤。」伊里伽尔这样对奈提说。\n此时，奈提小小的芯片上有了新的认知：我为伊里伽尔着想，伊里伽尔也为我着想。从此，奈提会详实地为伊里伽尔汇报所有情况，不再「自以为是」为伊里伽尔抵挡恶意。\n伊里伽尔也为奈提发生的变化感到高兴，这样一来，她们之间不再是智械与使用者的关系，而是真正的朋友。",
		heart_chain3 = "倘若有人想要利用伊里伽尔的缺陷来谋骗她，恐怕只能失望。\n虽然伊里伽尔看不到他人的容貌神情，但久经磨炼的敏锐四感，使她能够感受到许多细微之处，同时又不会受到表象蒙蔽，反而可以「看到」别人看不到的东西。心跳、呼吸、语调的颤动，这些常人难以注意到的细节同样少有人刻意掩盖，它们无不展示着对方的真实心情与意图。\n在伊里伽尔面前，谎言是最为脆弱的东西。当察觉到他人心口不一时，率直的伊里伽尔会直接指出来，或是用真诚的语气询问对方为何不说真话，经常让对方哑口无言。\n久而久之，伊里伽尔能够看穿谎言的事情成为了「怪谈」，有人说她能够看见灵魂数据，有人说她能够与神秘事物交流信息，而追查谣言的源头，大家只是看到伊里伽尔独处时会自言自语罢了。\n然而，能够看穿他人内心的伊里伽尔，并不擅长掩盖自己的内心。\n因为不曾见过任何人的模样，所以伊里伽尔并不能意识到，自己的情绪会通过肢体和表情一览无遗。\n最初来到阿卡德公会时，大家都对这位看起来孤僻的盲眼少女有所惧怕。但赏金猎人的胆子总比常人大些，稍微细心些的成员很容易发现，伊里伽尔其实十分期望能和大家成为朋友。\n她常常坐在一旁，与闲谈的大家一同欢笑、一同沉思，只是她不知道该如何融入。于是，经过几位热心成员的牵头，伊里伽尔顺利地与其他成员们熟络起来，逐渐成为深受大家信赖的伙伴。",
