		id = 1044,
		heart_chain5 = "荷鲁斯第一次与奥丁见面是在凯米特的某座城市里。\n虽然对于她们来说，跨越原质区不算特别麻烦的事，但荷鲁斯还是想不通奥丁为什么要大费周章约她到如此远离深空之眼的地方见面。\n「最近几个纪元，她都住在这里。」\n荷鲁斯知道奥丁说的是谁，本想用「关我什么事」之类的话打发过去，可看着眼前的城市，却没能开口。\n「你不如她。」\n「这可不是你说了算啊……」\n荷鲁斯的反驳没什么底气，毕竟她继承的权能只是拉的一部分，而作为修正者的神力，她也不敢说自己能与真正的原初修正者媲美。\n况且，她能从奥丁的语气中听出来，奥丁指的并不是战斗能力上的差别。\n拉是温柔的、慈爱的，就连生死权能都仿佛存留着她对这个世界最无私的关怀。因为能够掌握生命之轻，所以愿意珍视生命之重，这是拉为生死权能赋予的独特意义。\n然而对荷鲁斯来说，权能就只是武器而已。一切目标，有的可以通过武器实现，有的不行……武器的意义不过如此。\n奥丁能够理解拉，荷鲁斯也能够理解拉，但她们都不会去效仿拉。这不是适合她们的道路——所以奥丁对荷鲁斯说的这句话，听上去没有批评或鄙薄，倒更像是惋惜。\n最终她们没有进城，也没有代替故人去干涉这座她曾当作故乡的城市。\n「但是，你不用跟她比，我也不指望你成为她。你就是你，做好你能做的就行了。」\n两人在深空之眼的天台降落，坐电梯下行时，奥丁还是给予了一句劝勉。恰好电梯门打开，荷鲁斯摆摆手，迈着她六亲不认的步伐走了出去。\n「你不也一样，做自己擅长的事就好了……」\n这是专门为荷鲁斯扩建的训练场所在的楼层。电梯门关上以前，荷鲁斯转过身，歪着脑袋朝奥丁行了个金属礼。\n「所以，要是有好玩的事，别忘了叫上我啊，老板。」",
		heart_chain1 = "虽然入职深空之眼所有材料上的名称都是「荷鲁斯」，但荷鲁斯仍保有作为「冥王」时的所有记忆，原本就认识她的人也习惯了叫她冥王，这导致她一度难以适应这个新名字。\n某天荷鲁斯希望把自己的名字改回冥王。休却告诉她，许多修正者觉醒前都有与现在截然不同的人生与名字，作为修正者的新名字并不意味着舍弃过去，而是标志着新生活的开始。\n让休意外的是，平时对说教极其抗拒的荷鲁斯没有反驳便收回了申请。休就过去那场手术向冥王道歉，冥王依旧不以为意。\n「……休不一直都是这样？跟她生气最后只会自己觉得无聊，随她便好了。」\n不止是休，连荷鲁斯都想不明白自己为什么会对休做出这样的评价，只能解释为「前纪元残留印象的复苏」了。\n由于荷鲁斯身份的特殊性，深空之眼没有给她多约束。她没有被编入任何一支小队，甚至没有加入任何一个部门，与其说职员，更像是个受邀入驻的协作者。\n因此在没有任务的时，荷鲁斯几乎全天都是假期。学会使用网络后，她很快发掘出大量能找乐子的活动，并直言奥西里斯的生活太过寡淡以至于让她对艾因索菲一度有了「无趣」的误解。\n不过荷鲁斯对新事物的热情来得快去得也快，最后沉淀下来的只有电子音乐和涂鸦，以及用各种各样饰品、灯光和电子配件将她日常居住的大房子装修得越来越气派。\n另一个与其称作爱好不如说是「执着」的事是，荷鲁斯喜欢拉着人讲故事，就像奥西里斯以前经常在心象房间外给她讲故事那样。她似乎认为这是朋友之间很常见的聊天方式，于是找来一个又一个她认为十分有趣的故事，冷不防就会在人前冒出一个。\n但她讲故事的感情远胜于技巧，选材大多也是刺激、暴力甚至有些猎奇的内容，听众无不冷汗直冒，分不清是因为尴尬还是惊吓。\n看上去荷鲁斯已经完全适应了新的生活……但距离她适应新生活大概还有很长的路要走。",
