		heart_chain2 = "对于这位带着「斩杀阿波菲斯」的惊天功绩横空出世的「新人」，深空之眼内许多不知内情的修正者表现出了极强的好奇心，纷纷邀请她切磋指点。\n在数支小队被荷鲁斯碾压取胜后，崇拜和敬畏的目光让她十分受用，想到在夏什瓦特源层的经历，她将「大姐头」这一称呼沿用了过来。\n虽然不会强制别人使用这个称呼，但对于愿意喊她一声「大姐头」的人，她通常也更乐于给予一些正面的回馈，像是以此证明「大姐头」并非徒有其名。\n于是大家逐渐发现，除了有些孩子气的霸道，荷鲁斯并不算难以相处。遇到麻烦事，她总会用最直接，有时也是最笨拙的办法帮忙解决，事成之后耀武扬威的样子并不让人讨厌。\n这一称呼越传越广，就连对她有一定管辖权的休和塞尔凯特有时都会半开玩笑地使用。而荷鲁斯对此不悦的态度又表明她并非单纯享受口头的追捧。\n「像你这样的家伙还叫别人『大姐头』，能不能有点出息？」\n荷鲁斯的反讽作用十分有限，毕竟大家有时只想看她有趣的反应而已。\n不过也有无论如何不会喊她「大姐头」的人存在——托尔就是其中的典型。\n当荷鲁斯听说托尔有着「奥丁之下最强」的名号后，便主动找上托尔，想看看她是否名副其实。然而随着托尔一句无心的「小矮子」出口，这场切磋立刻上升到了「决斗」的程度。\n面对托尔恐怖的巨力，荷鲁斯在即将落入下风时忍不住动用生死权能反制，但很快便解除权能并收起了武器。惊魂未定的托尔询问荷鲁斯收手的理由，后者却兴致索然。\n「要揍你，凭我自己的力量就够了……梅塞可留给我的东西，不是让我用来欺负自己人的。」\n此后，托尔对别人称呼荷鲁斯为「大姐头」不再有异议，荷鲁斯则将托尔放到了不准使用这一称呼的名单里。",
		organization = "深空之眼",
		heart_chain4 = "对于熟悉冥王的人来说，荷鲁斯归来后显然不同了。\n百分之九十的时间里，荷鲁斯依旧是冥王，大大咧咧、张狂蛮横。余下的百分之十，却让人感到有些陌生。\n有时她会私下调阅凯米特的历史，没人知道她在找什么，也没人听她说起过她的发现。\n有时她会对一些她本该从没接触过的概念和事件表现出熟悉感，发表一些不太像她的正经评论。\n偶尔还能看到她独自坐在一般人根本到不了的高处发呆。虽然每次被发现，她都会用和平常一样不着边际的侵略态度敷衍过去，但从她的表情不难看出她的确有心事。\n荷鲁斯唯一一次主动谈起自己的想法，是在调查弥楼衍仓库所藏的那把镰刀过程中的问询。\n「赛特……现在该叫他『图灵』了吗？叫什么都无所谓，等我碾碎他的脑袋，没人会在乎死人的名字。」\n她承认第一次接触到那把镰刀时的失控源自对背叛者的愤怒，可那并非完整的记忆，而只是强烈的情绪残留。\n按理说这也是记忆存在的体现，可关于她是否拥有上个纪元的记忆，连她自己也说不清楚。\n「谁知道啊？明白的东西看到就明白了。再说我知道的事为什么要告诉你？少得意忘形了。」\n即便荷鲁斯有孩子气的一面，但真正了解她的人都不会把她当成需要照顾的孩子。对于她不愿意多说的事，大家都保持着相当程度的尊重，或者说避讳。\n好在抛开这百分之十不谈，把荷鲁斯当作冥王来看未尝不可。无论怎样，她还是深空之眼的伙伴，仅这一点，就足够了。",
		heart_chain3 = "奥丁曾对荷鲁斯的工作安排下达过极其简明扼要的指示：「好钢用在刀刃上。」\n最初休希望围绕荷鲁斯建立一支新的小队。然而几次集训后的评估结论是，荷鲁斯毫无团队意识且鬼点子奇多，经常不服从指挥，想到一些只有她才能执行的奇怪战术，不待汇报便开始独自执行。更糟糕的是，与出于保护队友而独自行动的托尔不同，荷鲁斯的专行更加随心所欲。当被问及知不知道自己的战斗方式可能波及友方的时候，她的回答往往是：「我一个人能搞定的事，派那么多拖后腿的来干嘛？」\n虽然后来在与奥丁见过一面后，荷鲁斯对「工作」这件事的态度似乎变得驯顺不少，但休还是放弃了让她参加小队作战的想法。\n此后，荷鲁斯不再参与诸如巡逻和集训之类的常规任务，而是作为一支应急机动力量随时等候调遣。\n对荷鲁斯下达命令的方式也很简单，告诉她目标和要求，如何达成全得随她自由发挥。\n事实证明有些人天生适合单打独斗。即使每次被分派到的任务都十分艰巨，指挥中心总能听到她意犹未尽的汇报：「搞定了，然后呢？」\n比起生活中爱炫耀的做派，荷鲁斯很少对于「消灭了怎样强大的敌人」表现出兴奋的情绪，然而当提到诸如「挽救了多少生命」、「保护了多少财产」、「为其他人争取到了什么有利条件」之类的成果，她就会恢复得意洋洋的样子。\n因此可以确定她本性不坏，毕竟以她直来直往的作风，完全不会在这种事上对情绪遮遮掩掩。但也有人认为这与她不顾队友的战斗方式自相矛盾。\n荷鲁斯对这种疑惑表示疑惑：「你要觉得自己是需要被保护的弱者，就放下武器乖乖躲在后面；可如果你觉得自己有资格保护别人，至少别让别人再分心照顾你行不行？」",
