	[1045] = {
		birthday = "3月25日",
		height = "160cm",
		name = "亚莉莎",
		id = 1045,
		heart_chain5 = "因为亚莉莎冷静成熟的气质，欢迎会破冰后，不少人会专程找她寻求意见，其中不乏比她更年长者。\n可实际上，亚莉莎还不过是个十几岁的少女。或许只是在原本的世界中，为了适应残酷的环境，才在不知不觉中变得有些少年老成。\n也就是说，她从一开始就不是无所不能的超人。\n另外，因为一直以来只有打倒荒神这一个想法，亚莉莎对日常生活显得缺乏关心。\n安排给她的屋子，总是在一个月内就变得杂乱不堪无处落脚。\n出于对极东文化的兴趣，亚莉莎学习了与之相似的笹波料理。但最后做出来的，却是漆黑的不明物质。\n随着这种日常小插曲的增多，深空之眼的同伴们也渐渐改变了对亚莉莎的看法。\n尽管亚莉莎自己曾担心薇儿丹蒂等人是不是会对自己失望，但迎接她的却是温暖的笑容。\n「每个人都有自己擅长和不擅长的事。正因如此，大家只要能相互扶持就好了！」\n听到同伴的话，亚莉莎终于意识到了一件事。\n不论身处哪个世界，自己要做的事情都不会改变。\n不仅仅是为了实现与友人的约定——\n更是为了回应这些对自己温柔以待的人们。",
		heart_chain1 = "亚莉莎曾在幼时遭遇过荒神「天父」的袭击。袭击中，她失去了自己的父母。在那之后她为了复仇成为了神机使。\n亚莉莎被培养成为当时新型的第二世代神机使。尽管实战经验还有所不足，但她在演习中取得了优异的成绩。之后，亚莉莎从俄罗斯分部应征进入位于过去「日本」地区的极东分部，并被编入了第一小队。\n加入第一小队之初，亚莉莎曾将第一世代的神机使们视作「旧型」。高高在上的态度显得她很不合群。但最终她被队长雨宫龙胆和其他队员们的亲切所打动，渐渐融入了极东分部。\n但突如其来的变故打断了这一过程。\n在一次任务中，亚莉莎遭遇了大型荒神的袭击。袭击诱发了亚莉莎失去父母的精神创伤，致使她陷入了精神混乱状态。第一小队也因此陷入危机，队长雨宫龙胆就此下落不明。\n在精神创伤和愧疚感的双重压力下，亚莉莎精神崩溃，暂时离开了前线。但在同伴们无私的关怀下，她重新振作了起来。之后，这起事件被发现是一场阴谋。主谋者为达成目的利用了亚莉莎的精神创伤。\n亚莉莎接受了同伴们的关心，并与自己的软弱之处达成和解。她下定决心，要与阴谋战斗到底。",
		plot_tip = "",
		cv_ko = "坂本真绫",
		like = "<color=#000000ff>-</color>",
		super_plot_tip = "",
		plot_tip_picture = "1045",
		cv_en = "坂本真绫",
		age_en = "",
		cv_zh = "坂本真绫",
		cv_ja = "坂本真绫",
		heart_chain2 = "在盖亚世界醒来时，震撼亚莉莎的第一个事物便是——一望无际的绿色原野。\n这是在她的世界中从未得以窥见的东西，草原、树林、生活在这片世界上肆意奔走的动物们，一切都让她感觉到陌生而新奇。\n在盖亚世界的荒神灾害告一段落之后，她就常常出没于艾因索菲的动物园和植物园等地，完全成了常客。\n按理说这种新鲜劲要不了多久就会到头，但不管过了多久，亚莉莎都始终兴趣不减。\n面对面露疑惑的伙伴们，亚莉莎微笑着回答道：\n「我想把这一切都映在眼底……然后总有一天，我想让芬里尔的大家也能看见这样的景象。」",
		organization = "芬里尔极东支部",
		heart_chain4 = "亚莉莎平时无论是对谁，都保持着礼貌温和的态度。\n也正因如此，有时会让其他人感觉隔着一道墙，有一种微妙的距离感。\n但在欢迎会时，深空之眼的成员们见到了她真实的一面。以此为契机，大家逐渐改变了对她的看法。亚莉莎似乎也隐隐感受到了这一变化，平时总是绷紧的身体，也在不知不觉中放松下来。\n结果，亚莉莎变得直言不讳。有时甚至会做出「我无语了……」这种尖锐的吐槽。但周围的人都接受了亚莉莎的这一面。\n「现在的亚莉莎很有趣，所以没什么不好的。还有，把心中所想毫无保留地互相说出来，朋友不就该这样吗？」\n看到深空之眼的同伴们的笑脸，亚莉莎的脸上也情不自禁露出了笑容。\n旅程的终点无人知晓。\n但亚莉莎坚信——\n如果是和在这里结识的伙伴们一起，无论何种困难，都一定能够克服。",
		heart_chain3 = "为了欢迎来到深空之眼的亚莉莎，深空之眼的成员们准备了一场盛大的欢迎会。\n尽管亚莉莎时刻叮嘱自己，在社交场合要举止优雅，不要做出失礼举动——\n但在一杯罗斯塔赫的清爽果汁下肚后，她紧绷的神经一下子放松了下来，少女的一面也紧跟着流露出来。\n回过神来时，她已经在缠着管理员和薇儿丹蒂各种问题问个不停。\n「艾因索菲有什么有名的菜肴吗？」\n「大家平时都在做些什么工作啊？」\n「这座城市里有什么推荐去的地方吗？」\n一边两眼放光，一边开心地滔滔不绝的少女身上，不再有平时那种酷酷的、成熟的感觉。包括管理员在内，深空之眼的全体成员都因亚莉莎的反差而大跌眼镜——\n但看着亚莉莎的笑容，又不由自主地感到，或者这才是原原本本的她吧。\n——是的，无论在战场上表现得多么强大，多么可靠，亚莉莎确确实实和她的年龄一样，还只是个少女。",
