		name = "雪儿",
		id = 1046,
		heart_chain5 = "「我和你说，最近有人来借书，一下子搬空了一整面的小说。」\n「不会吧，什么小说这么吸引人？」\n「好像都是青春恋爱一类的……主要是来借的人我也不认识，用得还是临时的身份卡。诶，头疼。」\n「彼此彼此，最近军械库这边也不太好过。每天都有一个女孩子拿着申请过来要参观武器装备，一看就是一整天。」\n「……是不是银色头发的女孩子？」\n「对对对，你认识？」\n「就是借书的那个人。」\n「得了吧，你的意思是一个每天研究枪械的女孩子借了很多的恋爱小说？你肯定是看错了。」\n「那可能是我搞错了……」\n而此时，传言的主角雪儿正在自己房间的被窝中，借着缝隙中传来的微弱光亮仔细阅读着小说的最后一卷。虽然并没有人说过看恋爱小说有违深空之眼的规范，但她依旧选择了这样较为隐蔽的方式。\n直到「完结」的字样出现在她的视线中，雪儿才长长舒了一口气，随后小心翼翼地从被窝中探出身来，谨慎地观察着周围的情况。直到确认没有人在自己的房间中，才放下戒备的神情。\n对于雪儿来说，能够如此完整地看完一个故事并不容易，而从故事里，她能更多的了解到宝贵的与人相处的经验——当然，只是她自己这么认为而已。\n「接下来的安排是枪械参观……这个世界的武器构造，有值得学习的价值。」\n「等能够回去的时候，就和六花讨论一下吧。」\n银发少女脚步轻快地向军械库快步走去，却丝毫没有想到，有关自己的传言正在变成深空之眼的不可思议传说之一。",
		heart_chain1 = "雪儿出生于一个富裕的军人世家。但在幼时失去双亲后，她便被送到了一处名为「木兰罗盘」的教养机构，并在那里被抚养长大。\n「木兰罗盘」实施的是因材施教的精英教育。雪儿也在那里发掘了自己的特长，接受了包括近身格斗、各种武器的使用、破坏工作、间谍活动和暗杀术等多种内容在内的严苛训练。\n雪儿在训练中取得了优异的成绩，却也在不知不觉中成为了一个像猎犬一样，只会忠实执行命令的少女。\n不久后，因为在近身格斗术和战术领域造诣颇深，雪儿作为作战参谋，被编入了极致化技术开发局(以移动要塞为基地)下属的特殊部队——BLOOD。\n加入BLOOD之初，雪儿在自己积累至今的战术理论和队员们自由不羁的行动方式之间疲于奔命，迟迟难以适应。但是在某个同伴无私的支持下，雪儿最终学会了信赖队友和关心他人。\n在那之后，雪儿迅速将实战经验和理论知识融会贯通，遇到不同情况时也变得能临机应变，为团队做出了重大贡献。",
		plot_tip = "",
		cv_ko = "能登麻美子",
		like = "枪械",
		super_plot_tip = "",
		plot_tip_picture = "1046",
		cv_en = "能登麻美子",
		age_en = "",
		cv_zh = "能登麻美子",
		cv_ja = "能登麻美子",
		heart_chain2 = "因为出身军人世家，又接受了严格的军事训练的缘故，在雪儿的世界里组织纪律就代表一切。\n——即使是来到了盖亚之后，她也没能完全摆脱这一习惯。\n战斗训练自不必说，就连吃饭、睡觉和补充水分这种事，雪儿也会按照计划表精确到分钟执行。\n在周围人看来，她就像一台从不出错的机器。\n对于其他人的那种缺乏效率的行事方式，雪儿常常感到难以理解。\n尽管似乎她也渐渐意识到，自由散漫的团队合作未必是一件坏事，但想要摆脱从小到大养成的习惯，大概还需要一些时间。\n另外有传言说，有些不按常理出牌的深空之眼成员，在看到她不知所措的可爱表情后……就被安排了更严苛的时间规划。",
		organization = "芬里尔极致化技术开发局",
		heart_chain4 = "来到艾因索菲这座陌生城市时，雪儿的心中只剩下了迷惘——能够指引自己的一切都忽然不复存在，但令人眼花缭乱的外面的世界却无时不刻不在冲击着她的认知。\n所以，到深空之眼的时候，众人都有些惊讶于雪儿的不谙世事，这并不只是因为居住环境或者生活习惯的改变， 更是因为这两个世界有着太多的不同。\n在这里，没有四处肆虐的荒神，即便是修正者也能抽出时间享受那些普通人的快乐，但是雪儿似乎是被以前所学会的规则所束缚着，很难全身心的投入娱乐活动之中。\n为了让雪儿尽快适应这个世界的生活，深空之眼也召开了最大规模的帮助会，不过作为主办者的前鬼却怎么都不肯说最后的结果。\n「等下次……下次一定要让她明白游戏好玩的地方！」\n但或许也是因为众人的努力，雪儿偶尔也会在无人注意的角落，展露一丝不易察觉的笑容。",
		heart_chain3 = "雪儿冷静且毫无感情波动的说话方式，常常使周围的人感到震惊。\n甚至有时她在谈论起自己的事情时也是如此，只是平静地分析叙述，仿佛话中的主人公与自己毫不相关。\n但她并非失去了感情，只是单纯不擅长与人相处罢了。\n来到深空之眼后，雪儿的身边自然而然地聚集起了一批个性鲜明的同伴。薇儿丹蒂和管理员自不必说，深空之眼的其他成员也都很亲切。正因如此，虽然对话时依然显得有些笨拙，雪儿也渐渐变得想要回应大家。\n「希望有一天，能和深空之眼的大家也成为朋友……」\n尽管几乎要被内心的不安压倒，雪儿还是发出了这条倾注了自己感情的信息，向同伴们传达了成为朋友的意愿。\n然而——\n同伴们的回复却出乎意料。\n「都一起玩过，一起吃过饭了，还聊了那么多。我们早就是朋友啦！」",
