		heart_chain5 = "塞尔凯特几乎从未有过这种身处善意环境的经历，久而久之，她慢慢放下了戒心，甚至主动试着融入大家之中。\n看着变得越来越「陌生」的塞尔凯特，塞努弗莫名的感觉到了一种「背叛」，那些曾经视为信条的东西似乎只是一种谎言，本以为与自己相似的对方，如今却得到了自己甚至不敢奢望的东西，即便知道这是一种迁怒，年幼的塞努弗依然忍不住与塞尔凯特展开了争吵。\n而那次争吵带来的后果却是难以想象的，意气用事的塞努弗被塞尔凯特的老东家抓住，当做人质要挟塞尔凯特。\n为了救回塞努弗，她选择利用自己的人脉，将曾经自己掌握的大部分情报与资源交出，以换取浪游城老大杰克逊的帮助，但这却恰好中了对方的计。急于救人的塞尔凯特被前东家半路埋伏身陷险境。\n千钧一发之际，休带人赶到，与对方一番激战后救回了塞尔凯特，但被抓做人质的塞努弗却在战斗后行踪不明。\n躺在医务室的塞尔凯特陷入了深深悔恨之中，自己什么都没做到，而且还害得其他人也和自己一并受到牵连。\n但休只是默默坐在她身边，平静地开口——\n「你应该更相信我们一些。我们既需要你的能力，也把你当作我们的一份子。」\n「希望你能把深空之眼当成安心的归所——而一个能让人安心的地方，是犯了错也会被原谅的地方。」\n休微笑着拍了拍塞尔凯特。\n一个让人安心的地方……休的话让塞尔凯特想起了曾经的自己，那时的她也像休一样，想要成为大家的力量，想要为大家而努力，但现在……不知不觉间自己变成了曾经最讨厌的人。这样的自己，真的能作为他人的榜样吗？自己所坚持的道路真的是对的吗？ \n这一刻，塞尔凯特终于理解了什么是自己真正追求的东西，也许就是像这样，一个让人安心的「归宿」。\n她多次试图找到塞努弗，想要告诉她当年的自己是错误的，但却总是没有对方的音讯。 于是她选择正式成为人事部门的一员，去接触更多在人类社会中独自飘荡的修正者。\n即便不能把他们引入深空之眼，她也想像休一样，为这些人指引一条路。",
		heart_chain1 = "刚苏醒时，塞尔凯特就知道自己与众不同。作为半觉醒的修正者，她拥有强于常人的力量和智慧，因此被坎扬维尔集团下属的帮派收留。\n在帮派的日子，收留她的人总是堆满笑容，告诉她这里是个温暖的大家庭。\n但在帮派的一次行动中，所谓的家人们却果断抛弃了受伤的她。倚靠墙壁勉强站起的塞尔凯特无力追赶，只能亲眼看着曾经的家人们离开的背影，温暖大家庭的幻想在那一刻被击得粉碎。\n侥幸活下来的塞尔凯特选择不去撕扯尘封的创口，她游离在各个组织之间，暗暗发誓再也不要保护别人，以后一定只为自己而活。\n再也不用顾及那些羸弱的同伴，她游离在各个组织之间，只为了给自己谋求更大的利益。\n很快，不管是金钱还是地位都聚集到塞尔凯特的手边，她从简陋的出租屋里搬进了上百层的高级公寓，一切都遵照着她为自己指定的目标运转着……但她却总是被一股难以言喻的空虚感缠绕着，就像是心口有着一个无法填补的空洞一样。\n独处的时候，塞尔凯特总是会缩在阴暗的角落，看着阳光下逐渐拉长的影子。\n不知从什么时候起，她开始觉得阳光下的影子，有点像她自己。影影绰绰模糊出一团乌黑的面目，偶尔飞起几根发丝，随着风来回切割，让人隐隐感到疼痛，到后来，太阳本身都令她觉得有些厌恶。\n她总觉得自己斩断了那些沉重的锁链，告别了背叛与谎言，但似乎，她也逐渐失去了自己的模样。",
		plot_tip = "管理员，今天下班后老地方见~",
		cv_ko = "이주은",
		like = "参加派对",
		super_plot_tip = "",
		plot_tip_picture = "1047",
		cv_en = "Chelsea Krause",
		age_en = "",
		cv_zh = "梁爽",
		cv_ja = "大地叶",
		heart_chain2 = "逐渐迷失的过程中，塞尔凯特遇到了不少和自己一样的修正者们——流离失所，被他人利用。\n一次意外中，她救下了一个和自己遭遇相似的修正者——塞努弗。出于一些她自己也说不清道不明的原因，她收留了对方。\n「我没想过要帮她……只是觉得，多个帮手也不错。」\n塞尔凯特从不自诩保护者，与之相反，她总是会直白的告诉对方，我只是在利用你，因为人本就应该只为了自己而活。\n可在这些看似无情的话语背后，她又明里暗里地向塞努弗提供帮助，塞努弗也对此心知肚明，甚至她还在暗地里把塞尔凯特当成了榜样。\n但双方谁都没有说破，两个人依旧在表面上坚守着「只为自己而活」的信条。\n虽然谁都不会承认，但在两人心里，她们第一次真正拥有了一个，至少在形式上可以被称为「家」的地方。",
		organization = "深空之眼",
		heart_chain4 = "加入深空之眼后，塞尔凯特凭借出色的观察和过往的人脉，加入了外勤队展开工作，负责劝诱修正者加入深空之眼。\n这对塞尔凯特来说相当简单，她轻轻松松就拉了好几名修正者进来。\n在这期间，塞尔凯特开始调查深空之眼究竟是怎样的组织，她通过各种方式搜集深空之眼的相关资料，并不断观察休的态度。但休却从没露出任何「马脚」，既没有谄媚般的纵容，也没有施压般的严厉，只是以最普通的态度来对待她，仿佛真的对塞尔凯特没有什么别的企图。\n身为外勤人员，塞尔凯特经常接到来自深空之眼成员递上的休整申请。她发现为了保护队友而受伤的修正者，甚至比自己遭遇危险而倒下的人更多。\n每到这时候踏入病房，塞尔凯特总是能见到一屋子人熙熙攘攘围着床上的病人说笑。那一次她倚在门边，自己也不清楚为什么脱口而出——\n「你们真的很像一家人。」\n欢笑的声音没有停下，笑声中不知道是谁先说了一句。\n「你也是我们的家人啊，塞尔凯特！」\n然后从人群中突然探出一只手，一把把塞尔凯特拉进探病的众人中。\n被挤进人群的塞尔凯特难得拘谨了几秒，但随即又露出微笑。\n「好像……这样也不错。」",
		heart_chain3 = "在艾因索菲中部摸爬滚打了这么多年，塞尔凯特有了一个属于自己的信条——人与人的每一次交流，都有其意义。\n塞尔凯特的交往法则里没有「尴尬」二字。见到有人遛狗，塞尔凯特会颇有兴致地问狗主人能不能让她也遛一遛；吃饭点单拿不准主意时，她会走到隔壁桌，询问别人每道菜的评价……奇怪的是，即使是再唐突的搭讪，也不会被陌生人拒绝。塞尔凯特的发言仿佛有一种魔力，总能让别人高高兴兴地达成她的愿望。\n上至名流宴席、典礼盛会，下至卡拉OK、社团活动，她总有办法自然地混入其中，与不同身份的人谈笑自如。\n按照塞尔凯特自己的说法，这只是第一步，将这些琐碎并短暂的交集建立成可用的社交网的真正要点，是后续进行人脉维护所花费的无数时间和精力。\n但这些看似无谓的努力，又总会在不为人知的时候发挥作用。有时是一次友好的合作会谈，有时是一张及时出现的许可证。\n当塞尔凯特神奇地为一位深陷过往的富商带回她养母的遗物时，塞努弗已经对她崇拜得五体投地。\n「你到底是怎么做到的？」\n「还记得当时我帮忙遛狗的那位狗主人嘛？她是收藏品的中介商，我就拜托她帮忙追查了一下~」塞尔凯特笑意盈盈地说。\n点连成线，线连成网，塞尔凯特靠着一次次简单交流打造出的关系网，才是她最重要的武器。",
