		name = "前鬼坊天狗",
		id = 1048,
		heart_chain5 = "每隔一段时间，前鬼坊就会进入一段被海姆达尔称之为「恶作剧倦怠期」的时间。这时她会反省自己给大家带来的麻烦，也会在这段时间内收敛自己的行为。\n经过海姆达尔的精确计算，「恶作剧倦怠期」差不多是每半年一个周期，进入之后会持续两周左右。根据这份预测，深空之眼的修正者都会尽量将自己的休假与之对应。在这种现象稳定形成之后，休干脆将这两周作为固定的休息日加入到了深空之眼的勤假制度之中。\n而在宛若天堂的「恶作剧倦怠期」结束后的几天，重新恢复精神的前鬼坊的恶作剧也会变得更加强烈。\n听不幸在这几天被恶作剧的人说，他们在被恶作剧之后，看着逃跑的前鬼坊，不知道是不是错觉，似乎能听到从她身旁空荡荡的位置传来「一起来玩吧~」的轻笑。",
		heart_chain1 = "作为修正者队伍中较年轻的一员，前鬼坊天狗的成长可以称得上是无忧无虑。\n前鬼坊天狗的信号在苏醒前就已经被隐科组的神力探测器所捕捉。因此，她自一苏醒就被深空之眼所吸纳，并幸运地得到了奥丁的亲自教导。原本大家对由奥丁来教导年轻的修正者这件事很是放心，但最后的结果却出乎所有人的意料。\n面对每日恶作剧不断，心性还和小孩子一样闹腾个不停的前鬼坊天狗，让所有人都感觉「是不是哪里搞错了」？",
		plot_tip = "管理员管理员，恶作剧俱乐部正在招新，我看你骨骼清奇，就决定是你啦~！",
		cv_ko = "방연지",
		like = "恶作剧、凑热闹",
		super_plot_tip = "嘿嘿嘿，管理员，打起精神来哦，恶作剧倦怠期的前鬼大人，也要给你送上惊喜！",
		plot_tip_picture = "1148",
		cv_en = "Sarah Ovens",
		age_en = "",
		cv_zh = "韩娇娇",
		cv_ja = "高森奈津美",
		heart_chain2 = "另外一件让大家相当在意的事情是，前鬼坊总是声称自己的身边有个名叫「后鬼」的小伙伴，并表示这是一直和自己形影不离的最好朋友，还展现出想向大家介绍这位空气友人的极大热情。\n然而实际上，根本没人能看得见这位后鬼，甚至连最有兴趣的大国主，都没有办法调查到任何关于后鬼的信息，这个空气朋友的身份也成为了一个彻底的谜团。不过现在深空之眼的大家也都基本习惯了，大部分修正者把后鬼的存在当做前鬼坊的中二妄想，只有单纯的薇儿丹蒂对后鬼的存在深信不疑。",
		organization = "深空之眼",
		heart_chain4 = "虽然前鬼坊是一个幻想着自己有空气朋友，偶尔心血来潮炸掉厨房、偷走休的笔记本、扰乱大国主实验、和维达尔的宠物狗搏斗的捣蛋鬼，但她在战斗中的表现还是十分可靠的。\n毕竟从她懂事开始，就被奥丁安排了那些极其严苛的训练。而且出于恶作剧以及恶作剧之后逃跑的需要，前鬼坊在武器的运用和机动作战上也有着突出的表现。\n不过比起这些技术层面上的东西，前鬼坊作为前线作战人员最大的优势是她豁达开朗的心态，或者说没心没肺比较准确？总之，只要有她在队伍里面，队内的气氛就永远不可能变得阴沉。在面对强大的视骸之时，她也能很好的起到鼓舞士气的作用。只要她不听完作战计划就开始行动的行为能收敛一下的话，她将会是一个不错的队友。",
		heart_chain3 = "当然，想要和前鬼坊好好相处还是有些难度的，首先你得要能忍受不知何时就会出现在你身边的恶作剧。这也是让休非常头疼的一件事，通常你要是在走廊遇见休拎着前鬼坊走过，八成是因为她又捅了什么篓子，正要去办公室写检讨。据不完全统计，光是一个月内，前鬼坊的检讨文就能达到惊人的三位数之多。然而这并没有什么太大作用，第二天一切照旧。\n而在前鬼坊看来，这样的恶作剧只是后鬼想和大家一起玩的表现。所以她其实真的并没有什么恶意，总的来说是个心思单纯，只是有点活泼过头的好孩子。不过还是要注意，前鬼坊很多时间不太管的住自己的嘴，建议最好不要告诉她什么秘密。虽然她总是信誓旦旦地说自己只会把这个秘密告诉后鬼，但她和后鬼说话的时候可从来不管身边有没有别人。",
