		id = 1049,
		heart_chain5 = "藉由黄泉咒刀打开与常世的链接，就能召来日狭女。原本不该有形的灵魂数据，却以伊邪那美最朝思暮想之人的样貌出现在她的面前。\n起初，伊邪那美曾把她当成母亲灵魂，尝试与她沟通，但是这些沟通与交流从未得到结果。许久之后，伊邪那美才愿意面对那个令人痛苦的现实，母亲早已不在人世，日狭女也只是存在于常世的唤灵。\n伊邪那美不断告诉自己，虽然有着与母亲相似的模样，但她只不过是从权钥中孕育之物，这只不过是自己的错觉，她并不是鸦越绫子。\n但在某个从往昔之梦中惊醒的夜晚，她自身前静静拥抱着自己，拂过的触觉宛如行将消散的雾气，伊邪那美忍不住像个被抛弃的小女孩似的乞求她别走。\n但不论伊邪那美怎样诉说自己的思念，这位与母亲相似的唤灵也无法作答，只能轻轻为她拂去眼角的泪花。",
		heart_chain1 = "成为鸦家真正的掌权者之后，伊邪那美在宅邸中找了一间密室隐居，就如那间囚禁自己的地下室僻静而阴暗，即便早已不是囚徒，她的心也始终被困在那间囚室里。\n「我习惯了僻静与黑暗，就让我住在这吧。」\n面对哥哥鸦越千堂更换居所的劝说，她总是这样回答。\n可鸦越千堂却看见了在她眼眸深处静静燃烧的火焰，那是誓要将朗香燃尽的业火。\n每每躺在这片黑暗之中，朗香杀害母亲，羞辱自己的画面就会涌上心头，进而撕开一个无法合上的创口。\n后来，自知劝不动她的鸦越千堂只得把本来放在千羽房间的家具搬进地下室里，让这间密室变得姑且像个居室。\n伊邪那美有时会望着这些令人怀念的物件发呆，那是始终作为幕后家主运筹帷幄的她少有的放空大脑的时间。\n在被诬陷成「妖女」之后，她再也无法以鸦越家二小姐的身份生活，在几位服侍她起居的佣人的加油添醋下，鸦家的禁室里住着一位魔女的消息不胫而走。\n先是「魔女」，后来又是「灾星」，对她的称谓变得越来越多，但她不会因此忘却自己是谁。",
		plot_tip = "你又回来了？……呵呵，拜访鸦家的日子里，请多指教了。",
