		cv_zh = "一口井",
		cv_ja = "安济知佳",
		heart_chain2 = "伊邪那美随身携带着母亲赠予自己的龙笛，母亲曾告诉她，音律之中寄宿着感情。当时还是初学者的她，并未完全理解母亲的话，只是将其作为知识记下。\n但她深深记得，每当母亲吹奏龙笛时，自己的心中总会涌起一股暖意，她也以奏出这样的曲调为目标。\n可不管她如何精进自己的技艺，吹奏出的曲子也没有母亲的那股温暖，可当她就此事向母亲请教时，母亲却只是露出慈爱的微笑，复述当初的那句话——音律之中寄宿着感情。\n直到她作为「妖女」被禁锢在那间阴暗的囚室后，她才深切的理解了母亲当时所说的话。\n不管是她的悲伤、愤怒、孤独、亦或是对母亲的思念，都无人能听她诉说，她只得拿起龙笛，将自己的满腔情感化作音律奏出。\n只不过，这曲调已经与她当时的目标相距甚远。",
		organization = "鸦越家族",
		heart_chain4 = "她曾经被作为「妖女」与「鸦神化身」押送回鸦越家，也正是因此，她才终于看清在鸦越家的阴影里潜伏着的东西——真正的鸦神。\n鸦越千堂设计用沾染惑火之刀斩杀鸦神之后，众人本以为萦绕鸦家的诅咒终于被清除，可伊邪那美却察觉到，鸦神并没有死。\n甚至就连被斩杀一事，也在鸦神的计划之中，它就此将自己转化为模因怪物，为了不让更多人认知到鸦神，伊邪那美尽可能的封锁信息，将鸦神关在自己的意识里。\n这段时间里，她不仅要在意识中对抗鸦神，还得作为幕后家主处理鸦家事务，她的每一日都充斥着阴谋诡计。但她选择一人抗下一切，不依靠任何人。\n也正是因此，她逐渐变得不愿与他人交流，因为信息本身就意味着危险，她不能坐视鸦家因此毁灭，只能默默饮下孤独，直至现在已成习惯。\n可即便如此，鸦神还是留下了阳谋，即便它什么也不做，只要其他山神开始行动，所有人都会自然而然地认为，鸦家也有一个鸦神。\n到那时，鸦神便会无可避免的复活。伊邪那美很清楚这点，却也明白这不是单靠自己就能解决的问题。\n或许她偶尔也想向谁倾诉，但她也在害怕那会是另一场镜花水月。",
		heart_chain3 = "即便是将鸦神斩杀，笼罩鸦越家的阴霾也未能全数驱散，它就像是沁入鸦越家中的一剂烈毒，若不下狠药，便难以根除。\n可鸦越千堂光是处理内部事务就已经焦头烂额，此前被鸦神暗中操控的日子里，他失去了太多实权。\n为了能向朗香复仇，鸦越家的力量是必不可缺的，而且自己身为鸦越家的一员，也不能坐视它这样衰落下去，伊邪那美只能接过了哥哥身上的担子，暗中替哥哥处理一部分鸦越家的事务。\n在这段期间，伊邪那美展现了极高的天赋，不论是鸦越家内部的管理问题，还是与外部相关的处理，她应对起来都显得得心应手，让人根本想象不到这是一名少女的手腕。\n对内，她肃清了鸦神原有的势力，让鸦越家再次上下一心。对外，她迅速封杀所有和鸦神神话有关的消息，尽最大可能降低鸦神的影响力。\n面对妹妹做出的实绩，鸦越千堂也不得不承认，妹妹在这方面的才能远胜自己，要想让鸦越家尽快走上正轨，就必须仰赖她的力量。\n到后来，几乎大部分事务都被交到了伊邪那美的手里，她也正式成为了鸦越家的幕后家主。\n少女从未渴求过这等身份，但为了自己的复仇，也为了鸦越家，她不得不接下这份职责，从此投身尔虞我诈之中。",
