	[1050] = {
		birthday = "6月12日",
		height = "161cm",
		name = "丰前坊天狗",
		id = 1050,
		heart_chain5 = "就如熬过寒雪的春苗更加茁壮一般，人也是在低谷中奋起之后才能达到更高的高度。假如此时的人本来就是天才的话，这个高度就难以估量。\n以父亲留给自己的话为座右铭，以老师月读为目标。几年来不断精进实力的丰前坊天狗，现在已经是深空之眼不可缺少的强大战力。即便如此，决定让她回到笹波去执行任务一事还是引起了一些担忧。不过丰前坊在这次笹波区任务中的出色表现很好地证明了她确实不会再受到当年的事件影响，这也让她重拾信心。\n「剑道即为心道」\n当年离开笹波的时候她并不明白父亲这句话的意义，但现在的她十分确信自己已经找到了属于自己的「剑道」。因为对她而言，留在月读师父的身边，作为消灭视骸的利剑便是她的「心之道」。",
		heart_chain1 = "丰前坊天狗童年生活在一个笹波的剑道馆家庭。\n将还在襁褓中的丰前坊收养之时，丰前坊的养父并不打算让这个可爱的孩子成为一名剑士。但在耳濡目染之下，丰前坊自愿走上了这条也许颇为艰辛的道路。\n「只是被环境带动罢了，等她理解了剑道的枯燥之后就会放弃了吧」\n以这种心态开始教导丰前坊的养父，在实际开始剑道训练之后深深地被丰前坊的剑术天赋所折服。年仅十四，丰前坊就几乎追上了她的养父。在她获得免许皆传身份的仪式上，她也继承了林崎馆的镇馆重宝「小乌丸」。\n「这是父亲对我的认可，我不能辜负他的期待」\n将这份信念植入心底，丰前坊的剑道之路永无止境。",
		plot_tip = "可以和管理员一起做的事，仔细想想还有很多。嗯……一起吃菓子的愿望已经完成了，下次一起玩歌牌吧！",
		cv_ko = "이다은",
		like = "剑道、武侠小说",
		super_plot_tip = "管理员，一起玩歌牌的约定，还记得吗？",
		plot_tip_picture = "1050",
		cv_en = "Andrea Gatchalian",
		age_en = "",
		cv_zh = "十四",
		cv_ja = "阿澄佳奈",
		heart_chain2 = "「在她手上，林崎馆的剑术必定能在笹波剑术史上留下浓厚的一笔。」\n「小姐的剑术已经出神入化了，就算是馆主也不一定能击败她。」\n「可以这样说，在年轻一代中，小姐的剑术毫无疑问是最强的！」\n……\n在丰前坊天狗获得免许皆传的身份之后，诸如此类，对她精妙剑术的赞誉几乎传遍了整个笹波。\n人们总是自视甚高，对于天才的出现嗤之以鼻。刚开始的挑战者大多都是抱着灭一灭天才风头的想法，而在他们失败之后，新的挑战者又开始觊觎起这似乎确有其事的天才之名。对于这些挑战，丰前坊展现出了强大的实力，将它们全部击溃，一时之间颇有笹波年轻一辈最强剑士之势。\n「天才果然就是天才」，拜服于丰前坊的强大之后，失败者开始为自己的败北正名。\n然而，这些人都忽视了丰前坊在剑术修炼上的付出。如果他们知道，她修炼的艰苦程度远超他们的话，不知道又会找出怎样的借口呢？",
		organization = "深空之眼",
		heart_chain4 = "从荣耀家乡的天才变成遭人唾弃的凶手，丰前坊天狗的遭遇宛若诗歌和小说中的那些传奇人物。\n尽管是修正者，本质上也不过是个十五岁的孩子。为了能够正确的引导她，月读在她刚到深空之眼的时候问了她这样一个问题：如果让你再选择一次，你还会选择除掉那个视骸吗？在犹豫之后，丰前坊是这样回答的：如果父亲和我处于同样的境地，他一定会毫不犹豫地除掉那个怪物。我继承了父亲的小乌丸，应该做出对得起它的行为。\n从丰前坊的回答中，月读明白了丰前坊的坚韧和高洁，同时也从她的犹豫中明白了她心中的迷茫和不舍。她认可了丰前坊的回答，之后作为丰前坊在深空之眼的导师，竭尽所能地帮助丰前坊，希望能够带她走出昔日的阴霾。\n之后几年，从剑术到生活，从任务到休假，月读对于丰前坊来说师如姐。也因此，每每谈及月读的时候，丰前坊天狗的眼里总是闪烁着真挚的光芒。只要是月读的吩咐，丰前坊一定会尽心尽力去做。\n「吾师之愿，即吾之愿」\n这是她唯一能够报答月读的方式。",
		heart_chain3 = "天才永远不会缺少赞赏，同样的，天才也免不了被人嫉妒和怨恨。大多数情况下，这些嫉妒和怨恨都被天才的光环所压制着，掀不起什么风浪。可若是有一丁点的闪失，千里之堤亦会毁于蚁穴。而丰前坊天狗的蚁穴，就在一起「歹徒无差别袭击行人」的事件之中。\n奉行剑道精神，丰前坊毫不犹豫地就冲上前去试图阻止这名歹徒，但是以制服为目的的攻击反而让丰前坊落入下风。就在危机时刻，丰前坊觉醒了修正者意识。当时的她内心忽然多出了一种无法言说的感觉，让她觉得绝对不能让对方活下来，于是丰前坊不顾自己还在大街之上，在刚赶到的警察面前拔刀消灭了这名歹徒。\n以此事为开端，丰前坊「凶手」的名号在笹波中沸腾，各类夸张的传闻不断涌现。为了让丰前坊免于政府抓捕，也为了保全林崎馆流传下来的声誉，养父只能将丰前坊逐出了林崎馆，秘密送往艾因索菲。\n得到消息的深空之眼通过社会关系替丰前坊摆平了这件事，在之后得知「那个歹徒其实是侵蚀种视骸」的真相时，丰前坊才减缓了自己心中的痛苦。但关于她的恐怖之名已经在家乡流传起来。丰前坊无法回到养育自己长大的林崎馆，最终被深空之眼暂时收留。\n在离开道馆之际，丰前坊本想归还小乌丸，但他的养父执意要她将小乌丸带走。\n「剑道即为心道，心之重即为剑之重，心之弊即为剑之弊」\n品味着父亲留给自己的话，丰前坊决定在深空之眼中继续锤炼自己的剑道。",
