	[1052] = {
		birthday = "4月20日",
		height = "182cm",
		name = "马尔杜克",
		id = 1052,
		heart_chain5 = "每个月，马尔杜克总会例行请一天假。在这一天当中，即便是最了解马尔杜克的部下也不知道他人在哪里。躲入秘密藏身处，避开那些崇敬的视线后，马尔杜克会启动秘密通讯装置，然后脱下和蔼大叔的伪装，变得干练、冷酷——因为此刻他要面对的并不是无辜的民众和热心的部下，而是被全体罗斯塔赫居民仇视的科尔盖。\n提供环境骸能检测数据，汇报保密工作，确认物资调度需求……马尔杜克机械地将这些工作依次办完，就像是之前很多次那样，像是台机器。他不想在这些事上投入任何感情——他也必须摒弃掉所有感情，才能允许自己做这些事。为了他在罗斯塔赫所维护、所热爱的一切。",
		heart_chain1 = "阿卡德公会的很多成员都见过马尔杜克咬着一截雪茄，但是并不点火的情景。旁观者大多理解这种举动——在罗斯塔赫这种穷困的地方，雪茄这种稀罕物可不好找。即便是身为阿卡德公会首领的马尔杜克，也只能省着点抽，平时就咬在嘴里过瘾。\n有不少人好奇地问过，自称和大家一样穷苦出身的马尔杜克到底是什么时候拥有了这种奢侈的嗜好。马尔杜克从未正面作答，只是为难地讪笑一阵，然后把刚刚攒起来的一笔小钱全都转到孤儿院的账上。偶尔身旁无人时，马尔杜克会偷偷点着嘴里那截雪茄，深吸一口，回味一阵后立刻将其熄灭，然后小心翼翼地收起来。",
		plot_tip = "",
		cv_ko = "한신",
		like = "抽雪茄、扳手腕",
		super_plot_tip = "",
		plot_tip_picture = "1052",
		cv_en = "Eliah Mountjoy",
		age_en = "",
		cv_zh = "赵梓涵",
		cv_ja = "楠大典",
		heart_chain2 = "在整个罗斯塔赫，都罕有人能在掰手腕上赢过马尔杜克。虽然年近花甲，但马尔杜克那健壮的身躯中仍然涌动着澎湃的生命力。面对挑战者，他来者不拒，用长辈特有的笑容看着他们一个一个前来挑战，然后一个一个落败。\n不过，马尔杜克「手腕王」的地位也被动摇过——金固十二岁那年向马尔杜克发起了挑战，这场父子对决立刻吸引了大批人围观。也正是在这场对决中，马尔杜克罕见地露出了吃力的神情。\n当马尔杜克最终获胜时，他的额头上竟然出现了细密的汗珠。在旁人的谈笑声中，马尔杜克明白，金固的修正者能力已经接近觉醒。",
		organization = "阿卡德公会",
		heart_chain4 = "罗斯塔赫的人对马尔杜克都有种奇怪的印象——这位阿卡德公会的首领喜欢接济疯子。自从多年前的那场大灾过后，罗斯塔赫地区突然出现了很多疯癫的家伙，他们成天念叨着什么怪物、异空间之类的鬼话。大多数罗斯塔赫居民遇到这些疯子，都会敬而远之。而每当其他人远离时，马尔杜克就会出现。他带着上好的啤酒和熏肉，主动和那些疯子畅饮、交谈，直到他们不再念叨那些疯癫的鬼话，而是开始无奈地长叹。\n旁观者大多认为马尔杜克这么做是为了维护罗斯塔赫的安宁，他采取的是理智且必要的举动，然而马尔杜克往往会在畅饮后皱起眉头。之后的日子里似乎就没人再见过那些疯子，就像他们从未来过这里。",
		heart_chain3 = "成为阿卡德公会的首领后，马尔杜克逐渐习惯了被人称为「老大」。不过，偶尔也会有刚刚入会的新人用「队长」称呼马尔杜克。每当听到这个称呼，马尔杜克总是会错愕一阵，然后挥手赶走准备纠正新人的部下，走过去在新人肩膀上拍几下。之后，公会的人大半天都见不到他，偶尔会有人看到马尔杜克靠在无人的角落里沉思，根本不敢上前打扰。",
