		heart_chain5 = "羲和性子逍遥散漫，不爱显山露水，科尔盖以及虚恒早期的一些组织建立后，她便早早退出了人们的视野，开始混迹市井。羲和葫芦里装的不是酒，而是果汁或者汽水。她本就逍遥天地间，没有愁苦没有烦闷，还需要酒来消解什么东西呢？\n这一段闲散日子中，她结识了不少隐士，这些人都是有志趣有能力的贤达，进则出将入相，退则放旷山水，其中庚辰赠与奥丁的《翠微录》就是其中一人所著。后来荒兽入侵，这些人大多出山，在各自擅长的领域立下了卓著功勋。\n然而一边是战乱不断，一边是岁月蹉跎，羲和结识的那些贤达，战死病死老死。当最后一位故友在卧榻上安然病逝，羲和意识到，寿命是困在人类身上的永恒枷锁，正因为人生苦短，所以在有限的生命中恣意畅快便是逍遥。但对于寿命无尽的她来说，时间早就已经是模糊的尺度。\n逍遥本就是一种人生选择。当这种选择被赋予无限重来的机会，还能称之为逍遥吗？\n羲和在很多年中为此事感到迷茫，因此镇压混沌后，她选择了长居若木宫，既是履行镇压混沌的职责，也是给自己一个停下来自省的机会。\n在若木宫中的生活闲散自在，关于逍遥的思考却一直萦绕在羲和心中。直到那位来自深空之眼的小友来到若木宫，说出了他的想法：「虽然生命的长度不同，但时间的每一刻却是公平的。」\n「正如我们此刻对坐畅聊，消耗着同样的时间，对时间的感受也相同。」\n「同频的人一起做着闲适美好的事情，这一刻的体验如此珍贵。人生不就是由这么多珍贵的瞬间组成的吗？」\n羲和已经很长时间没有仔细感受当下的一秒，一瞬，一刻钟。对她来说，时间和空气一样平淡普通。可是听完那位管理员的话，这些久远的关于时间的回忆再一次出现，让她想起与旧友谈笑风生的日子。自己想要什么样的逍遥？也许这就是了。就是这样畅快闲适的日子，三五好友，呼朋引伴，诸事随心，不想前程。\n逍遥是当下的每一刻都要快活，都要畅快。\n是兴之所至，便花上一天，看檐角燕子搭窝。\n是有一件事值得为之付出生命，便去做。不瞻前顾后，也不为此伤感迟疑。\n也许，这就是她一直寻求的答案。",
		heart_chain1 = "「旸山上有个若木宫，里面住着个很厉害的道师，如果遇到邪祟，找她必定能解决。」\n「且这道师看着就像位高人，本事也着实不小……」\n虚恒山间乡野四处流传着羲和的名声。作为道师，羲和时不时帮周边村民铲除被误认为邪祟的视骸，兴趣来时还会摆摊算命，鲜少出错。因此她很受赞誉，连带着若木宫也成为村民心里百试包灵的道观。不过，尽管羲和已经在这里待了许多年，却很少有村民看见过羲和原本的样子——\n因为觉醒时年龄尚小，羲和时常被当成孩子来看。据知情人透露，在很久之前羲和与庚辰外出围剿视骸的时候，曾被当地居民误认为是母女关系，气得羲和在接下来的任务中都距离庚辰十几米的距离，庚辰也少有的露出了不知所措的神态。\n这类事情发生次数多了，羲和对「被当成孩子看」这件事情格外留心。好在她根据自身神能研究出了「天通术」，可以将自己调整为成人样貌，避免了很多此类麻烦。成人姿态的羲和时常偷偷下山，听见旁人夸她沉稳端和就会心情大好，久而久之她也习惯了用这个样貌来云游虚恒。\n据说她曾在事后找过庚辰，固执地让她陪自己去当年围剿视骸的地方重新走上一圈，得到二人「旗鼓相当」的评价才满意离开——这是她在亲近之人面前才会显露的，孩子气的一面。\n如果你遇见的是原本孩童样貌的她，大概率会听她说一些看似高深的话。不用感到奇怪，那是她为了看起来更像个隐士高人而专门设计的话术。\n用她的话说：「如果在外貌上吾已经失去了让人信服的条件，那就只能从言语上找补了。」\n如果你要问具体是哪种言语，那你可能会听到一连串——\n「万物皆循其道，急有何用？譬如这初春笋，刚冒尖就挖出，只能吃到一口，长成再挖，能吃到……好几口。」\n「吾日三省吾身，吃饭了没？吃饱了没？吃好了没？」……\n没听懂的话，在羲和说完这些之后配合着点点头就对了。不然如果你直言怪哉，不能保证她会不会猛敲你脑壳。",
