		heart_chain2 = "因为羲和独特的语言风格，管理员第一次去若木宫的确有被唬住。\n「羲和前辈不愧是隐居的高人，说的话好像都很深奥……但总觉得哪里有点奇怪？」\n不过这种隐士高人的印象很快就在饭点被打破。羲和随手丢给管理员一把铲子，自己背上黑锅，扛上小锄头，说要去准备今天吃饭的食材。\n「上午山涧雪水刚化，此时的茼蒿最是脆嫩。」\n来到溪边的羲和利索甩掉鞋袜，赤脚下水挖菜。羲和平时半披的长发挽成松散的发髻，专注地弯着腰凑近溪畔，像个插秧的农家姑娘。\n管理员原本想称呼的「前辈」突然变得有点说不出口。\n「羲和……看起来你对吃很有研究。」\n「既然都要吃，自然要吃最美妙的那一口，方能物尽其用嘛。」\n「那也没错。不过上山之前，很难想到羲和你居然是愿意了为了挖菜花上一两小时的人。」\n「那不然呢？吾跟你说，人皆知有用之用，而莫知无用之用。对吾来说，此刻的茼蒿就是世界上第一值得花时间的事。莫说一两小时，若有鲜美的鲈鱼，蹲上一天也无不可。」\n「既然来了若木宫，就把时间什么的抛到脑后，专心吃，专心看，专心生活吧~」\n没有再多说，两人挖好茼蒿，直接在溪边架锅。三两滴猪油，几瓣白蒜，中火下锅，几分钟便是一盘脆炒茼蒿。\n爽口的菜就着溪水、鸟鸣声，味道更好了。这一刻的管理员放下了对「下一刻」的任何思考，如羲和所说，去吃，去看，去感受生活。\n什么都不多想，从内而外感到无比放松。\n这下管理员真觉得羲和是个高人了。",
