		heart_chain4 = "「你问这柄剑？吾不常用，吾本来也不是擅用剑的人。」\n管理员看向那柄剑，剑身莹润无尘，怎么也不像不常用的样子。\n羲和解释道：「这柄剑意义非凡，来自吾的一位故交。这位故人为了万世生民耗尽心力，最终永远留在了异界之地。」\n管理员听完举杯，和羲和一起遥敬「故人」。\n「每次看到这把剑，吾常想起曾经一起恣意游乐的日子。吾总会想，为什么要冒着那么大的风险去做那件事情呢？为什么不再想想别的办法？」\n「先保住性命，吾总能想到别的办法……」\n煮茶的炉火噼啪作响，偶尔迸溅的火星带起袅袅香烟，羲和眯着眼睛，仿佛透过烟看向曾经让人怀念的旧时光。\n平时羲和总是豁达淡然的，管理员很少看见她露出惆怅的表情。这样的表情出现在外观稚嫩的羲和脸上，怎么看都有点违和。管理员忍不住捏了捏她的脸颊。\n「我觉得羲和你和这位故人其实没什么不同。」\n被管理员的话绕了一下，羲和甚至忘了拍开他的手，任由他捏捏脸颊又摸了摸头。\n「嗯？怎会没有不同呢？」\n「因为你们都是内心洒脱之人，都有自己要追求的事情。」\n「洒脱也并不是什么都不在乎，而是知道自己想要什么，并且为了想要追求的东西甘之如饴，哪怕失去生命也不可惜。不会像普通人那样瞻前顾后，也不会被别人的言论所左右。」\n「这是这段时间，我从羲和你身上学到的。」\n羲和沉默了。她看着手上的剑，半晌微微一笑。\n「你很有悟性，有来若木宫当道师的潜力。」\n「等这些事情了了，吾可要向奥丁挖人了~」",
		heart_chain3 = "作为除庚辰外虚恒最早觉醒的修正者，曾受庚辰委托代行当地的维稳工作，因此早早就游历过虚恒四方。虽然现在隐居若木宫，但她时不时还是会下山，随手解决掉困扰村民的邪祟，自然得像吃饭喝水。\n难得的机会管理员与羲和一起下山。一路上羲和左看右看，村头的珍酿，村尾的糍粑，每一种都不错过，和她平时在若木宫板着脸的样子大相径庭。\n管理员不由得好奇发问：「你都在若木宫待了那么久，这片地方你应该来了很多次了吧？看你对什么都很感兴趣的样子。」\n羲和摇了摇手中用于伪装的扇子，接过树上飘下的落叶把玩。\n「乡土所在，每次来的感受都不一样。因为太熟悉了，一花一木的变动吾都知道。」\n看着眼前闲适散步的羲和，管理员想起初见她时，觉得她是个严肃高深的人，总喜欢以前辈身份自居。相处了一段时间，他发现羲和其实心胸豁达，行为洒脱，并不真正在意辈分，也鲜少有动怒的时候。若木宫的一切都讲究自然无为，但羲和又与真正不问世事的高人不同。\n她和虚恒人一样眷恋着故土。因此她记着初春的茼蒿，村野的花木，走到哪里都会随手帮村民清理掉邪祟。\n山水怡情，这方土地滋养着羲和和万千虚恒人。哪怕隐于山野，她仍然对脚下的土地充满情怀。\n这么一想，管理员好像知道金乌的一片赤诚来自何处了。",
