		id = 1054,
		heart_chain5 = "从双子诞生开始，不安定感便如影随行地伴随着她们。\n必安和无咎生成时意外被分隔两地，无法顺利觉醒，觉醒的当天对两人来说又都是惨痛的经历。而她们四处游历时，无论是作为送葬人举行葬仪，抑或是在大荒见过的人事，凡此种种都在她们的心中留下了痕迹。\n如果说她们从这些经历中有什么领悟的话，恰恰还就是「无常」二字。只是对于这件事，或因少时经历不同，或因天性使然，两人却有着不太相同的看法。\n必安的父母从小都鼓励她积极的面对病痛，命运的不公不会打倒一个人。觉醒以后，后土行胜于言，有她的引导，必安很快接受了自己的情况，开始从后土身上学习。\n就这样必安耳濡目染，且又一直在保护下成长，因此养成了乐观温柔的个性，在很长一段时间内，她都相信只要人们能携手与共，彼此理解，问题总能被克服，希望总会来到。\n「世事无常但世人有情。因为有情，所以那些被侵蚀的人们愿意为了不伤害他人而结束生命；也因为有情，我们才能取信于人，让他们放心地把自己交到我们手里。」\n必安对世上生命都常怀慈悲之心，坚信人们都值得被拯救，但这也成为了她的软肋。因为相信世人有情，而送别有情之人总是太难，所以在第一次葬仪时，必安听完遇害者的遗言后久久无法回神，最后还是在无咎的提醒下结束了葬仪。\n到后来，两人遇到了更复杂的情况，面对着被侵蚀的友人，必安无法下手，她退缩了，她的「有情」没能敌过世间的无常。而这样的事越来越多，她则不断地后退。\n无咎在葬仪中总能果断地出手，因为她曾经被那个寄生在父亲身上的侵蚀种摧毁了全部希望，所以对于她来说重要的只是阻止伤害的蔓延，至于安慰和希望，大概率不存在的东西没必要花费太多力气。\n「能减少一点目所能及的坏事，抓住手里有的一点点东西就已经很不容易了，至于更多的……抱歉，我没有那么乐天。」\n同时这也是对妹妹的保护，她不愿意让必安纯净的世界观蒙上阴影，所以沉重的工作她会代劳，而有关过去的惨痛的经历她选择对妹妹缄口不言。对她来说美好是短暂而珍稀的，阴暗则总蛰伏着挥之不去。即便是那些在葬仪中接受了必安关怀的人，合上双眼之前不也难免带着遗憾吗？\n自以为看清了这一切的无咎不再去思考太多关于未来的事，以一种救治绝症患者的心情行使着自己的使命，结局不可逆转，但在病人合上眼睛之前，治疗就是自己的职责。\n或许也因此，无咎对于职责之外的事情总是兴致缺缺，在大荒与虚恒分隔以后更是如此，除去看守穷奇的封印和偶尔处理侵蚀种，其他的事似乎都不被她放在心上。\n但是管理员在相处中却觉得两人远不止是面上表现出的这样，或许连她们自己也没有意识到。两人更多时候像是磁铁的两极，截然不同但又总是在不断朝向对方移动，或许终有一天，她们会成为自己真正期待的模样。",
		heart_chain1 = "囚云山附近，尤其是山北大荒地界曾有传言，若有人得了怪病或撞上邪祟，全身长出黑纹，药石无医之时便可能有黑白无常前来索魂，送将死之人最后一程。\n传言中白无常面带笑意，翩如春风，她会来到临终者身边，欠身问其遗愿。而黑无常会沉默地执剑站在不远处，待最后同行葬仪。若遇上失心狂乱之人，黑无常便会现出恶相……\n这「失心狂乱之人」自然是已经彻底转化的侵蚀种，只是流言不明真相，渐渐把黑无常传成了个铁面鬼使似的人物。\n「这个版本还挺平淡的，我听过我身长三丈青面獠牙手拿一把腰粗大砍刀的版本，那个编得比较刺激一点。」\n众多传说中铁面冷心眨眼间夺人性命的无咎，大部分时候会根据时令不同迁移到秋霖宫阳光最少的房间里，用许多枕头和被子把自己堆在中间，默默地做手工或是神游思考。\n而初次见到必安的人则会觉得她和不少民间传闻中的形象颇为贴近，总是踏着轻快的步伐，满面含笑，使人观之可亲。若外客到来，她也是那个主要负责交涉或接待的人。\n露于人前的场合，两人几乎永远形影不离，且总是必安在前，无咎沉默着跟在她身后，于是很多不熟悉的人都以为无咎性格冷酷。\n但必安知道无咎只是不想为在她看来不重要的事花费精力而已，私下相处时，两人的衣食起居几乎全靠必安打理，如果没有她的话，无咎大概只会维持一个勉强能活着的环境。\n「这些都是小事啦，万一世界马上完蛋了呢，付出这么多完全没必要嘛。」\n而对于姐姐的这些话，必安总是温柔地笑笑不予置评，她会一边打整房间一边把姐姐拉起来，不顾对方皱到一起的脸给无咎安排一些小任务，看着她慢吞吞地开始挪动。\n「但是世界今天还在，明天多半也不会完蛋，所以先去救一下你房间里那盆快蔫掉的花吧，它看上去马上就要完蛋了。」",
