		cv_zh = "无咎：栾祥瑾\n必安：郑好",
		cv_ja = "无咎：柊优花\n必安：田泽茉纯",
		heart_chain2 = "见到本人之前，因为先走过了囚云山的迷阵，又看到了清寂得像座陵墓一样的秋霖宫，在管理员的想象中，无常姐妹应当是两个稳重的清修之士。但是见面后不到一天，这个印象就全部碎裂了。\n两姐妹看起来确实已经很久没见过陌生人，何况是遇到这么紧急的情况。明显一开始应对得有些慌了手脚。两人先是着急忙慌地一把将管理员拉到了机关所在的地方，又抱来厚厚一堆后土留下的说明。\n管理员懵了一会儿之后，刚打算从善如流地开始学习，两人又像是才回过神来一样，觉得这似乎有些莽撞不符待客之道。又七手八脚地把管理员领到了客厅里，想着要泡杯茶先聊一聊。\n结果两人翻箱倒柜半天，只从某个不见天日的角落里翻出来后土走之前留下来的一盒古老茶叶，管理员眼角狂跳地看着她们拿起那颜色明显深得有些诡异的茶叶戳戳闻闻，似乎在考虑要不要赌一把。\n在必安开始指挥无咎去汲水时，管理员终于忍不住出言阻止了：「两位……要不就算了吧，这个茶叶，看起来有年头了，还是……让它珍藏着好了。」\n无咎立刻像得到了什么许可一样，以今天以来最快的速度迅速坐到了角落的沙发上，然后在管理员的震撼注视下，慢慢变成了一摊人。\n还是必安捂着脸过来扶正了自己的姐姐，然后端上一杯清水，和管理员讲了讲在囚云山上的规矩。可惜没说上几句就变成了对管理员身世和外界情况的好奇。\n最后还是管理员提醒了一下或许该是她们多给自己讲讲机关和凶兽的相关事宜，必安这才如梦初醒正襟危坐起来，有模有样地跟管理员说了机关和地牢的情况。\n管理员这才真正对两人有了一点最初的印象，不仅不是什么清修之人，反而是两个长居山中性格迥异但都有些孤单的女孩。但就是这两个女孩，耐着寂寞看守着封印和机关许多个日夜寸步不离。\n所以囚云山中虽然没有什么世外高人，但却有两个生动的少女，一个丧里丧气，一个天真温柔，但都同样紧握着手中的使命。",
		organization = "冥途旅团",
		heart_chain4 = "秋霖宫落成后，两人基本就常住在了这里，或者用必安的话来说她们是「赖在了这里」。后土从来没说过要让她们帮忙做什么，只是她们一直在这里，几人便形成了一种奇怪的相处方式。\n两人从来没有拜过师，但是后土却会在必要的时候给她们点拨。平时后土也从来不关心她们在做什么，但无论哪天，两人的房间的花瓶里却总会有一把新鲜的花。\n后土从没要求两人帮什么忙，但是不知不觉间，必安就照顾起了秋霖宫上下的生活。即便是从来不爱动弹的无咎，也会去弯着腰去打理那一大片花田，有时口中还念念有词让它们别生病。\n管理员到来后，两人告诉管理员，大荒与虚恒分离之前，两人还会时不时随着后土下山，有关送葬人和葬仪相关的东西基本都是后土传授给她们的。\n但是两人并没有和冥途旅团保持太紧密的联系，几乎都是独立行动，只是偶尔在游历中遇到侵蚀种时才会动手解决，「黑白无常」的传说也是从那时起开始在囚云山一带流传，一直到如今。\n随着相处变多，管理员发现姐妹俩的相处模式很特别。表面看起来，必安是那个安排各种事项，打头阵的人，但在关键问题上，无咎才是两人中真正掌舵的那一个。\n比如在她们执行任务时，虽然通常是必安进行事前安排，但是在实际的作战中，判断形势，决定任务进行到了哪一步，什么步骤应当被提前，什么步骤应当被删去的却是无咎。\n「其实真正在遮风挡雨的那个人是姐姐，我一直都知道的，但是不该这样，我不想只在光鲜的场合站在前面，在困难的时候却躲在姐姐身后。」\n但无咎却并不在意这些，对她来说，必安能一直保持着她的温柔与明净就好了，那些恐惧、黑暗不应该沾染她。在这件事上两人一直僵持着，谁也没有多进一步。\n直到管理员进入秋霖宫，带着新的想法的他和两人在共同经历的一连串事件中，给姐妹俩都带来了新的刺激和改变。\n两个人已经习惯的相处模式和思维，会被管理员发现不太健康的地方，比如因为必安在大事上总下不定主意，无咎干脆许多重要的事便自己拿主意处理；又或是必安心疼着姐姐过去的伤疤，对她的一些消极举动采取了小心翼翼的呵护态度。而管理员会在合适的时候，偶尔推上某个人一把，让她们发生一点改变，慢慢地更多理解对方。\n也因此，在机关学习之外，管理员也额外收获了与无常双子的情谊。唯一不知道算不算正面结果的随着几人的熟悉，管理员的身边、甚至身上开始不定期不分场合地刷新出无咎，这似乎是她表达好感的一种方式，但是多少让管理员有些头疼。\n必安也很头疼，她不止一次地红着脸把无咎从管理员身上拽下来。",
		heart_chain3 = "关于自己早年的事，两人往往很少谈及，即便是开朗健谈的必安也是如此。准确来说，她们谈到自己的过去时，总是说得很有选择性。就连两人并没有诞生在一起这件事，管理员都是在数次长谈之后才得知的。\n必安偶尔会不经意地提到一句童年的事，但是却会立刻看看无咎然后止住话头。更加熟悉以后管理员才知道，两人有着天差地别的少年时光。\n无咎生在大荒，养父母又暴躁冷漠，在和必安重逢以前，从没有过一天好日子；必安自幼体弱，但是却有着一对关怀备至的父母。因此两人都鲜少谈及过去的事，无咎是不愿回顾，必安则是照顾着姐姐的心情。\n但纵然生成时分隔两地，又有着截然不同的经历，有一件事却是两人共有的：对彼此存在的确认。那是一种与生俱来的不完整感，从苏醒时她们就知道要去寻找自己的姐妹。\n这样的话无咎自然不敢告诉自己的养父母，一直计划着长大逃离之后去寻找自己的妹妹，但是生活不断恶化，她一度都快不报希望；必安的父母曾经试着帮她寻找自己的姐姐，但是久寻无果，她自己身体又差渐渐也作罢了，只是心里一直记挂着。\n直到觉醒之后，必安跟随了后土，后土知道她对姐姐的记忆并非戏言，许诺会帮她找到姐姐。两人就这样一路北上，边游历边寻找无咎的踪迹。当后土终于在玉京卫星城的小巷里找出正处于颠沛流离逃亡中的无咎时，姐妹俩几乎都不敢相信。\n无咎不相信的是自己竟然真的还有见到妹妹，离开现在生活的一天，生活多年的折磨让她几近要把对妹妹的印象当做一个梦；必安没想到的是自己的姐姐竟然过着这样的生活，后土带着两人见面时，必安听到一半就哭着抱住了无咎，而无咎大概僵硬了十几秒，才试探着抬起手，轻轻摸了摸必安的头。\n两人就此一同跟在无咎身边，虽然分离多年，但那份来自灵魂的亲近感很快让她们变得形影不离，觉醒后终于身体变好的必安会拽着无咎去参与各种各样的趣事，据她们说让后土头疼不已。\n后土本性不大爱和人交往，也不是很喜欢照顾人，姐妹俩一度担心会被后土逐出麾下，但不知道为什么后土竟然任由她们一直这样吵吵嚷嚷地跟在身边，一跟就是许多年。\n关于那段时日两人总能搜捡出话题，连大部分时候兴致缺缺的无咎都会插上一两句，但唯独在提及两人觉醒那天的事情时，她们都会沉默下来。\n必安或许还能稍微提上一两句，她在觉醒那日险些死去，也因此告别了父母，所以不愿多谈。无咎则是完全回避提及那日的事情，连必安都不太清楚姐姐觉醒那日究竟发生了什么。\n「没什么可好奇的，不过是命运给我开的一个巨大的玩笑罢了，只是我到现在还是觉得不太好笑，所以……暂时还不想记起来。」",
