		id = 1055,
		heart_chain5 = "暗御津羽掌握着冰系力量，却出奇地怕冷。这是因为她在尚未完全觉醒时已经能够使用一部分神力，而不完全的认知导致她在神力的使用上产生差错。\n那是很久以前的某个夏天，暗御津羽正躺在树荫下乘凉。炎热的气温使她心生厌烦，她突发奇想，觉得自己的力量正好适宜降温。她尝试降温周围的空气，但很快被周围的炎热稀释，于是她选择——降温自己。\n她将冰冷的神力反注入自己体内。\n那个夏天她确实凉快得舒适，但紧随而至的冬天，却差点要了她的命。\n完全觉醒后，她驱除了在体内游走的寒意，却始终无法驱走内心对寒冷的惧意。",
		heart_chain1 = "暗御津羽苏醒于笹波下京区。她在苏醒之初便掌握了部分神力，从而拥有了在鱼龙混杂的下京区生活下去的依仗。\n她游走在下京区社会之中，见识过太多人心险恶，目睹过太多坑蒙拐骗，浸淫其中，反倒青出于蓝，成为下京区最精明狡黠的游侠，活跃在流氓地痞聚集的场合，把各种凶神恶煞的歹人耍得团团转。她顺着自己的心意，搅动混乱的人海，然后饶有兴致地看着人们在涡旋中浮沉。\n没有人敢报复她，因为她的武力无人能敌。即使是暗算，也无人能保证自己的计谋在她之上。\n下京区的人称呼她为「怪侠」，她从未理解这两个字的含义，只是发觉下京区的居民对她的看法，与被她戏弄的地痞们并没有什么不同。这或许是因为她曾经让缺斤少两的小贩当众出丑，曾经张贴告示揭露一个妇人在街边嚼舌根散播八卦谣言。\n敢亲近她的，只有小孩子。一开始有胆大的孩子问她能不能跟随于她，她看着孩子真诚的眼神，欣然答应。渐渐地，她认领了一帮无家可归的「小号忍者」，为他们提供安身之所，并教会他们各种生存技能。",
		plot_tip = "哈哈，在下京区和在下相处了这么久，你也越来越接地气了嘛，管理员！",
		cv_ko = "김율",
		like = "街头将棋",
		super_plot_tip = "",
		plot_tip_picture = "1055",
		cv_en = "Jennifer Sun Bell",
		age_en = "",
		cv_zh = "降温",
		cv_ja = "中村环奈",
		heart_chain2 = "下京区，即是暗御津羽所见社会的全部。在这里，言语并非心绪的传递，而是筹码和武器，或者只是无意义的音节。暗御津羽明白，她不能说出自己的真实想法，不能让别人猜到自己在想些什么——这被她奉为信条。\n暗御津羽自然也学会了说话的「技术」，不过不同的是，她并非谎话连篇，而是将所言之事拆得半真半假，令人将信将疑。\n与她打交道的人，只能赌自己的判断。有人信了她的话，去往偏僻的山林寻宝，最终一无所获；有人不信她的话，把黄金当作无用之物丢弃，之后得知真相悔恨万分。\n要么别跟她打交道，要么相信自己这回能赌对。",
		organization = "无",
		heart_chain4 = "她早就觉得自己并非人类的一员。觉醒，只是为她这一想法提供铁证。\n刚苏醒时，暗御津羽就被骗进了黑作坊。里面的人面容憔悴，环境更是惨不忍睹。她很快意识到了不对劲，但这里显然不是能自由进出的地方。于是她学着工头的腔调，稍微添油加醋了些，竟使所有人误以为她是这儿的所谓「老板」，任她大摇大摆地走出。她对此感到可笑，认为人类不过是被表象迷惑的存在。\n因此她观察人类，模仿人类的所作所为，将人类当作取乐的媒介。然而对人类的模仿，并不能让她理解这一切的内核。——其实她又何尝看穿过表象。\n愚昧的是人类，明智的也是人类；屈从的是人类，反抗的也是人类；暗御津羽讨厌的是一群人类，但是喜欢的也是一群人类……\n人类为什么会这么做呢？人类为什么能这么做呢？直到现在，暗御津羽仍然在寻找答案。",
		heart_chain3 = "暗御津羽人生的转机，出现在游侠生活持续十八年后的一个下午。\n一位年轻的府将率领一队人马来到下京区，在讨伐怪物的过程中与她相遇。一个年纪轻轻就当上鹿家府将的少女，与一个孤身一人却在下京区纵横十几年的少女，就此相识。少女府将名为秋鹿绯美子，她是暗御津羽的第一个朋友。\n暗御津羽本不理解「朋友」的含义，她只是觉得又多了一个可以耍弄的对象。但秋鹿绯美子帮助暗御津羽学习语言文字，同她一起游走于市井，逛集会，看烟花，用一种截然不同的方式对待她。她也曾试图耍些手段捉弄一下这个看似天真的人类，却总被反将一军。\n不知为何，绯美子能分辨出她言语中的虚实。暗御津羽像往常一样对绯美子说，自己要去山林打猎。她确实是去「打猎」，只是这猎物是偷盗粮草的地头蛇。她潜入粮仓燃起火把，却看到绯美子站在自己面前。绯美子阻止了她，并承诺会代她处理这件事。被看穿心思的暗御津羽自认败北，没再反驳。后来地头蛇不知所踪，粮食也回到了民众手中。\n暗御津羽发觉她与人类之间还存在另一种相处方式，她喜欢这种方式，期望这一切能够永恒。她甚至打破了之前的信条，许诺绝对不会对秋鹿绯美子说谎。那是她在下京区中不曾体会过的，名为「朋友」的坦诚相待。作为交换，暗御津羽也不再对绯美子有所隐藏。\n「反正就算告诉她假的消息，也很快会被看穿的啦~」",
