		name = "伽梨",
		id = 1056,
		heart_chain5 = "在加入弥楼衍后不久，伽梨的修正者力量就如同梵天所预料的一样觉醒了。然而起初，伽梨对这份力量始终抱持着有些纠结的感情——一方面，她知道了当年父母遭遇的事故是由视骸引起，拥有的这份力量不仅可以帮助自己报仇，也能更好地保护夏什瓦特的孩子们；但另一方面，早就见多了各种斗争的伽梨，从心底认为争斗只会给更多无辜的人带去不幸。\n但最后她还是认同了自己修正者的身份，为了不再有悲剧的发生，也为了守护身边的人……伽梨相信只要能善用这份力量，和平的生活一定会到来。",
		heart_chain1 = "伽梨的养父母在很早的时候就因为事故离开了她，而在夏什瓦特的贫民窟这样混乱不堪的地方，自然也没人会有余力来关心无家可归的孩子。\n所以对幼时的伽梨来说，生活是一件非常辛苦的事。她每天都要和其他流浪的孩子们一样，挨家挨户敲开住民的门，乞求他们能够分给自己一些吃食。运气好的话，她能获得一些发霉的土豆，但大部分时候得来的只有辱骂和驱赶。\n然而伽梨只是默默地承受着这一切，她知道想要活下去，现在能依靠的只有自己。",
