		cv_zh = "苗洋",
		cv_ja = "濑户麻沙美",
		heart_chain2 = "流浪毕竟不是长久之策，随着经历的增长，伽梨也愈发深刻地认识到了这一点。不仅仅是目睹了帮派之间的斗殴，残酷的拳赛、街角的交易……在这个混乱无比的地带，她可以不用提心吊胆上街的日子屈指可数。如果街上响起了帮派喧闹的声音，就意味着接下来的几天她只能饿着肚子了。\n所以她剪短了头发，学着混混们摆出豪爽的样子，希望能够找到愿意收留自己的帮派。只不过这收效甚微，并没有团体愿意平添一张吃饭的嘴。就在伽梨因为饥饿快要昏倒在路边的时候，梵天找到了她。",
		organization = "弥楼衍",
		heart_chain4 = "关于伽梨优秀的烹饪技巧，她本人表示学习这个的一方面原因是为了更好的照顾组织内的孩子，而另一方面，同时也是更主要的原因，源于梵天带她吃的第一顿饭。那是她第一次品尝到真正意义上的料理，那些熟悉的食材在烹饪后拥有了更加丰富的味道。这使得伽梨逐渐对这门技术产生了兴趣并开始了练习，她的厨艺也水涨船高，收获了孩子们的一致好评。顺带一提，目前伽梨最擅长做的是咖喱。",
		heart_chain3 = "梵天慷慨地为伽梨准备了食物与住处，并提出希望她能加入弥楼衍。虽然很感激于她的救命之恩，但真正让伽梨下定决心的，是弥楼衍对待流浪孤儿们的态度。\n她来到这里后才知道，弥楼衍一直秉持着净化的理念，这几年来都有在为贫民窟的流浪孩童提供更好的生活环境，而深知流浪疾苦的伽梨认同了梵天，加入了弥楼衍后接手了这部分的工作。伽梨非常明白因为家庭被毁灭而流离失所的这些孩子们最需要什么，她照顾着这些心灵受伤的孩子们，久而久之便学会了哄小孩开心的技能，心性也得到磨练，变得成熟了许多，慢慢地也成为了他们公认的大姐大。",
