		height = "155cm",
		name = "迦具土",
		id = 1058,
		heart_chain5 = "有一件事迦具土和大多数人都不曾提起：当初握起「龙切」之时，他也背负上了名为「斩落神明」的宿命。\n最终计划成功与否，现在已经无从得知了，但似乎从那以后迦具土很少再参与亲卫队的任何行动。\n不过即便现在总是表现出一副优哉游哉的处世态度，迦具土的内心依旧还是坚守着保卫鸦家的使命。\n「若是鸦家有难，我定当竭力。」",
		heart_chain1 = "小孩的容貌带给迦具土很多麻烦，似乎很少有人相信迦具土是一个大家族的亲卫队长。心智上早已成年，在被刺杀阴云笼罩的笹波，迦具土保留了不少难能可贵的童趣。\n虽然在执行一些特殊的任务时，这副容貌也会起到不少作用，但是对迦具土本人来说，并不怎么希望被当成小孩子来看。",
		plot_tip = "管理员，一起去看花火大会吧，再不去买票的话就赶不上了。",
		cv_ko = "이경태",
		like = "钓鱼、喝碳酸饮料",
		super_plot_tip = "",
		plot_tip_picture = "1058",
		cv_en = "Stefan Menaul",
		age_en = "",
		cv_zh = "唐雅菁",
		cv_ja = "天崎滉平",
		heart_chain2 = "虽然本职工作是鸦家的亲卫队长，不过经常是神龙见首不见尾，据说哪怕已经加入亲卫队很久的队员，见到队长的次数都屈指可数。\n于是就有许多关于迦具土的传闻在新加入亲卫队的队士之间扩散开来，「队长是个高大威猛的壮汉」、「在暗处护卫鸦家和平的强者」——诸如此类。\n然而实际上，迦具土只是觉得管理下属和提交报告这类琐事过于麻烦，光明正大地翘班了而已。",
		organization = "鸦越家族",
		heart_chain4 = "能够畅饮碳酸饮料对于迦具土来说是另一大乐事，虽然家主曾不止一次的和他说起过量饮用对健康的危害，不过迦具土还是更享受于气泡在口腔里炸开的快感。\n哪怕是在战斗的时候，迦具土也会带着自己的水壶——里面装满了碳酸饮料。按他自己的说法，这有助于他在战斗中保持精神振奋——当然这并没有任何的科学依据。",
		heart_chain3 = "忙里偷闲的迦具土通常会有个好去处，在鸦家后山的湖边钓鱼算的上是他打发时间的一大爱好。\n最开始只是为了能够独自待着清净一下，结果最近已经变成了雷打不动的常驻活动，甚至于开始钻研起钓竿的制作工艺来。\n这也使得迦具土钓鱼水平日益精进，甚至包揽了近期几场由鸦越家举办的钓鱼大赛冠军。",
