	[1059] = {
		birthday = "5月21日",
		height = "180cm",
		name = "阿波罗",
		id = 1059,
		heart_chain5 = "「大家都还好吗？我是你们朝思暮想的阿波罗。想必你们拆开信封的时候已经热泪盈眶，但还请注意不要让泪水打湿信纸，毕竟那样就看不清我写给你们的思念了~」\n「这次要调查的遗迹真的好热啊，即便是我这样如太阳般明媚的人，也快要被这真实的太阳烤掉一层皮了！真怀念艾因索菲的气候啊，那片蔚蓝澄净的天空，还有翱翔云端的飞鸟，一定都在期盼着我的归来吧。放心，即使是被晒黑的我，论帅气也是依然是不会扣分的。不如说，现在的肤色更让我有了一丝来自边土沙漠的独特魅力，想必回去之后会变得更受欢迎吧~唉，真是苦恼到时候要怎样妥善处理那么多人的迷恋。」\n阿波罗寄来的信总是洋溢着这样令人扶额叹气的自信。那个自恋过头的男人在沙漠浮想沉醉的样子跃然纸上，真是让人忍不住捏紧拳头想要揍他一顿。",
		heart_chain1 = "深空之眼雷小队的成员，擅长使用弓箭在远处狙击敌人，是组织中可靠的远程火力手。\n在加入深空之眼前是欧莫菲斯有名的贵公子，实际上并不有钱，靠着打多份工来维持开销，经常在歌剧院兼职拉琴，十分注意自己的仪表。因为拒绝某位很有势力的大小姐的追求，导致在欧莫菲斯没有立足之地的他来到了深空之眼。\n「为什么我会拒绝她？当然是因为，不能让更多我的粉丝伤心落泪啊~」\n每当被问起这个问题时，阿波罗总会用手抵着额头，故作忧伤地这样回答。",
		plot_tip = "哎呀，这不是管理员吗？要来听一场华丽的演奏吗？",
		cv_ko = "김지율",
		like = "弹竖琴",
		super_plot_tip = "",
		plot_tip_picture = "1059",
		cv_en = "Hyoie O'Grady",
		age_en = "",
		cv_zh = "徐翔",
		cv_ja = "杉田智和",
		heart_chain2 = "由于种种自恋的言行，阿波罗总是受到休的批评。同时也因为和同队的前鬼坊最为熟络，导致他成为了前鬼坊捉弄最多的对象。\n「我说啊，小前鬼~拿我恶作剧可以，但能不能别弄乱我的发型啊？」\n被天花板上吊着的水桶泼了一身水的阿波罗，摘掉头顶水桶后第一件事，不是责问这件事的元凶，也不是关心自己湿透的身体会不会着凉，而是用手指小心翼翼地捋着被打湿到已经完全贴在额前的金发。",
		organization = "深空之眼",
		heart_chain4 = "作为深空之眼的一员，阿波罗已经渐渐爱上了这个温暖的大集体。每次远出回来后，他都会带来各式各样的小礼物。\n热爱旅行所以经常抢着执行需要出差的任务，时不时还能从奥林匹亚速运那儿收到他寄来的信件，里面阐述了阿波罗近日来的见闻，顺便祝许久未见的大家永远开心快乐。",
		heart_chain3 = "虽然言行注重华丽，浑身上下都透露出贵公子的派头，但阿波罗却经常因为大手大脚的开销而经济紧张。在最窘迫的时候，阿波罗甚至会在食堂蹭管理员的饭，久而久之，两人的关系也变得还不错。\n「管理员，你真是一个好人。」\n一面说出听上去有些微妙的发言，一面丝毫不见外地吞嚼着管理员从自己的便当中分给他的饭团。\n「如果你在『怎样才能更受欢迎』这方面上有烦恼的话，就让我来为你解决吧！」\n阿波罗决定以这样的方法报答管理员。在他看来，没有比这更适合他的报恩方式了。",
