	[1060] = {
		birthday = "5月18日",
		height = "173cm",
		name = "陆吾",
		id = 1060,
		heart_chain5 = "陆吾尚身为警员时，在工作中结识了科尔盖的行动组长白泽。白泽常驻虚恒地区执法，两人在多次合作中逐渐熟络，在工作之外也常有联系，成为了好友兼「搭档」。\n然而，在一次营救任务中，陆吾即将找到营救对象之时，接到了白泽的撤退命令。\n陆吾当时只觉人命关天，违抗命令继续深入，结果遭遇视骸，营救对象全灭，陆吾自己也陷入了绝境。\n好在白泽及时赶到，救下了陆吾，但也因此受了伤。陆吾的修正者意识在此次事件中觉醒。\n事后，陆吾虽然能够理解，白泽让自己撤退是为了避免自己遭受视骸攻击，但无法接受她不以救人为优先的做法。\n陆吾站在警员的角度，认为自己是守护者，不论如何自己应该保护他们；白泽站在科尔盖的角度，认为警员身为人类也是被保护者，陆吾不应该接触规则外的事。\n「你所谓的正义不过是一杆摇摆不定的天平，正义与否，全仰仗于你心中虚无的砝码。你竟要用这臆想的标准，来动摇清晰且公认的『规则』？」\n「……我只知道不能见死不救。」\n两人争执不下，最终白泽上报了事件经过，判断陆吾不适合留在公安部门配合科尔盖工作，随后将她从部门中永久除名。\n陆吾并不记恨白泽。她只是有些不甘，并且现在仍然想要向白泽证明，正义无关身份与力量。",
		heart_chain1 = "觉醒前，陆吾因出色的身体素质以及本人强烈的意愿，进入警校学习，后顺利进入虚恒公安部门，任地方警员。\n身为警员，陆吾和同事们尽职尽责地处理片区内大大小小的案情，帮助居民们解决问题对她来说是每日的必修。\n「举手之劳，不足挂齿啦。」偶尔遇上陆吾有空的时候向她致谢，她大概率会这么摆摆手，然后继续在各种本不属于她的领域中提供力所能及的帮助。\n然而，出于某种原因，陆吾在觉醒后退出了公安部门，悄无声息地离开了原先的片区。\n来到新的环境中，陆吾一度感到迷茫。她也曾尝试过许多工作：文员、教练、服务生，都不了了之。\n最后开办的一家安保公司，也由于陆吾完全没有半点经商头脑，很快面临倒闭。\n好在转机意外出现，安保公司承接了一笔来自天禄贸易的商单。任务顺利完成后，禄良亲自上门谈妥了收购事宜，于是，陆吾加入了天禄贸易。\n经历了几次身份转换，陆吾深知，无论拥有何种身份、身处何种境地，她作为她自己，想要帮助他人的心情始终如一。",
		plot_tip = "",
		cv_ko = "이세레나",
		like = "抓娃娃",
		super_plot_tip = "",
		plot_tip_picture = "1060",
		cv_en = "Brittany Cox",
		age_en = "",
		cv_zh = "沐霏",
		cv_ja = "青木瑠璃子",
		heart_chain2 = "离开公安部门之后，陆吾的工作处处碰壁，常有人说她多管闲事，也有人说她做事欠考虑。经历了一次又一次的失败，陆吾开始怀疑自己的选择，「越界」二字像是刻在她的脑海中一般挥之不去，她试着不再「多管闲事」，只做分内的事。\n现在的她是个安保队员，只要和自己的货物无关，就没必要趟浑水。不知是否拜此所赐，不再多管闲事之后，她的工作也进行得愈发顺利。\n可当她越是置身事外，她就越是发现——在光芒照耀不到的地方，暗藏着许多罪恶与不幸，警局并非毫无作为，只不过要护的人太多了……总会有些顾不到的人。\n她见过惹上混混被打得半死的贫苦之人，也见过被小偷偷走救命钱而在街头痛哭的老人，陆吾想要为他们讨回公道，但却被同伴拦住。\n安保队员不该介入这些事，救那么一两个人也改变不了这里的规则。\n她学着说服自己这就是生活，说服自己这是对的，让赤诚的心逐渐冷却，身为安保队员、身为修正者的她不应该参与这些事。\n直到有一天，追查丢失货物的途中，她听到了少女的呼救声。就像是有某种沉睡的东西再次被唤醒了一般，陆吾身体自顾自的行动起来。\n转过小巷，她只看见伤痕累累的少女倒在地上，什么立场、身份、规则，统统被她抛之脑后，陆吾没要多久就将包围少女的混混全数放倒，甚至用不着武器。\n现在的自己不是警员，不需要做这些事，可真的是这样吗？看着少女那如遇救星的眼神，陆吾已经得到了答案。\n她运用警员时期的丰富经验设计抓住了连环盗窃犯，随后又单枪匹马捣毁了混混们的老巢。\n她并非自诩英雄，只不过是觉得，总得有人来做这些事。\n仅凭陆吾一人或许不能改变什么，但是她却让这里的人们开始相信这个世界上存在正义。\n在警员与当地群众的紧密合作下，曾经一时动乱的街道再次回归和平，而陆吾正是这一切的开端。\n置身事外无法改变任何事情，只要有人需要自己，她就绝不会袖手旁观。\n「活着总得相信点什么吧？我只是……选择相信正义而已。」",
		organization = "天禄贸易",
		heart_chain4 = "陆吾有个收集的爱好。她的房间和办公室里，全都堆满了大大小小各种毛绒玩偶。它们的形态和风格各异，将房间装点成了一个小小的幻想世界。\n而扩充这一「收藏」的手段，主要来源于在商场里的各式娃娃机。因为凡是能够直接购买的周边款式，都早已进入了陆吾的收藏，而最新款又大多会第一时间在娃娃机中出现。\n陆吾最为喜爱的「圆圆雀」系列，是娃娃机特供的款式。\n为了集齐这个系列，陆吾曾有过一段「光辉事迹」：她在「圆圆雀」的机器前，从早上十点站到晚上十点，花光了自己一整个月的工资，最后的收获却少的可怜。\n于是此后几个月里，下定决心锻炼技术的陆吾每天都辗转于商业街的各种娃娃机之间，直到自己的工资见底。\n那时陆吾一到店，所有人便都自觉为她让出一条通向娃娃机的路来。\n在多年的经验累积之下，现在的陆吾已经十分擅长利用娃娃机的脱钩机制，只要是自己想抓到的，多半都能到手。新款的「圆圆雀」，在上新当天就会出现在她的案头。\n不过要说究竟为什么对这事这么着迷，陆吾也总会摸着头说不出个所以然。她对这个小小的毛绒玩具的第一印象，是某天下午白泽随手抛在她桌上的不明圆形物体。\n「随手搞到的，不要就帮我处理了吧。」\n随着陆吾的藏品逐渐变多，房间里的装饰也显得拥挤起来，她便定期拿走一半送人或捐给学校，其中不乏极其稀少的款式。\n只是房间里的装饰换了许多轮，她桌上最显眼的位置，却始终摆着一个泛旧的玩偶。曾有爱好者找上门来希望收购这个已经绝版的玩偶，但却被一向大方的陆吾婉拒了。\n或许在她看来，这是自己与过去仅剩的牵绊。",
		heart_chain3 = "加入天禄贸易后，陆吾开启了一段全新的生活。\n起初，陆吾只是执行一些虚恒内部的小型护送任务，由于她能力出众，禄良很快开始将跨原质区的任务安排给她，她均能顺利完成，因此禄良对她赏识有加。\n经常在外的陆吾可谓是万事通。从缝补、野炊、扎营之类的野外生存技能，到电路维修、管道疏通之类的日常生活事务，陆吾都十分熟练。\n安保队的队员都希望和陆吾一起执行任务，似乎只要有她在，任何困难都能迎刃而解。禄良察觉到了这些队员想要偷懒的心思，于是经常只安排陆吾一人成队。\n虽然执行任务时总是一人，但在任务之外，陆吾的周围总是围绕着许多朋友。\n得益于乐于助人、阳光开朗的性格，陆吾很快在天禄贸易结交了不少朋友，许多人都受过她的照顾，是天禄贸易上下都赞不绝口的老好人。\n目前，陆吾常驻夏什瓦特，只有偶尔会回到天禄贸易总部。每次回莱仙阁时，陆吾总会受到大家的热情欢迎。\n英招会难得放下工作，和麟钰一同为陆吾准备丰盛的菜肴；安保队的其他队员们，会拉上陆吾品尝窖藏的珍酿，或是切磋武艺。\n唯有在短暂返回总部后的临走之际，陆吾才会感到一丝不舍。",
