		name = "执明",
		id = 1061,
		heart_chain5 = "在外人眼里，执明从来一副冷冰冰、对所有事情都了如指掌的样子。无论是主导实验，还是处理庚辰交给她的工作，她都能快速且妥善地完成自己手中的事物。\n只有她知道，自诞生后，自己一直都处于敏感而脆弱的状态。她茫然无措地跟在庚辰身后，了解但却没有能力执行盖亚赋予修正者的义务。她的身体素质没有寻常修正者那样强壮，诞生时一只眼睛失明，就连伴生权钥都是残缺不全的。\n她不明白自己存在究竟有什么意义，好像她的诞生，只是为了证明盖亚的参数出现了很严重的问题。\n「我真的能当一个修正者吗？」\n在无人看见的角落，执明时常质疑着自己，她拼尽全力地摄取知识，企图用另一种方式来证明自己。凭借着聪慧的头脑以及刻苦的努力，没几年执明便成了虚恒名声鹊起的学者，但她依旧没能解决之前困扰自己的问题。长久压抑着自己的情感，也使得执明愈发沉默寡言，性格也变得尖锐。她开始抗拒所有人的关心和接近，所有的关心与照料在她眼中如同无声的嘲笑与同情。\n这样的状态直至执明与「玄机」有了些许感应才得以缓解。庚辰感应到神力波动来到实验室时，看到的是怔怔的执明，但她的脸上却挂着难忍的笑意。那之后，执明就把自己关在了实验室里，全身心地投入到权钥的恢复工作中。几番废寝忘食后，执明以比之前更为虚弱的状态结束了「闭关」，只不过这次她眼中再无半分迷茫。\n「或许，我们并无不同。」",
		heart_chain1 = "执明的住所有一间专门用来放置纸质书籍的房间。虽然现在大部分人都已经习惯了在终端上进行阅读，但执明依旧保留着这个看起来老派的行为。\n早年间，还未觉醒的执明为了探寻盖亚生成自己时参数错误的原因查找了很多资料，后来觉醒后才了解到她身上发生的事情根本就不是可以查询到的。但那几年她看了海量的书，每日的阅读已经成为了习惯，当不再抱有目的性地去看书，她感受到了前所未有的放松，这个习惯也就变为了爱好。\n她的藏书种类繁多，上到《自然哲学万物原理》下到《豚兽的产后养护》皆有收藏。她会对一些奇奇怪怪的书产生强烈的好奇心，每次都会不由自主买回来，带回来后又不想让别人发现自己这奇怪的小爱好，导致这些书的来由不是「没注意顺手买的」就是「别人送的」。\n在处理事务不得头绪异常烦躁时，她也会借着寻找灵感的由头去看些杂书放松心情，从未有人发觉她是在忙里偷闲规避工作。",
		plot_tip = "管理员，你去赤炁堂处理完事情之后，记得来我这里一趟……我会一直在办公室等你。",
		cv_ko = "이현진",
		like = "阅读",
		super_plot_tip = "",
