		cv_en = "Yuuki Luna",
		age_en = "",
		cv_zh = "苏婉",
		cv_ja = "yukana",
		heart_chain2 = "执明在觉醒前便通过自身努力成为了虚恒小有名气的学者，从此人们不再会关注她本身的外表缺陷，反而想通过接近她获取更大的利益，无论是贪图她手中的专利亦或者是通过她来接近庚辰。\n小时候经历过的一些事，让本就不会轻易外泄情绪的执明在发觉到那些人的小心思后，更加排斥与他人有交流来往。\n然而四方院有众多事务需要决策者，其余代理中陵光是医者太过心善，监兵性格鲁莽耿直，孟章闲散时常找不到人，唯有执明无论从地位、性格、能力来说都是处理政务最好的人选。\n但其实执明并不喜欢处理这些事务，也不喜欢与那么多人打交道。政治与人际交往上的尔虞我诈让她感到厌倦，但她合适在这个位置上。为了替庚辰分担一些来自四方院的工作压力，执明最终还是主动接下了外交以及文书相关的部分工作。",
		organization = "四方院",
		heart_chain4 = "执明的口味和四方院众人有很大差别，她的口味偏淡，每次去玉京轮值的时候，食堂的掌勺做饭的时候都会减去半分盐。陵光与执明的口味相近，若是执明与她同在玉京，陵光便会多做一份吃食送去。执明虽然说着「好麻烦，下次别做了」但却从未浪费。\n庚辰味觉失灵的事情是执明首先发现并找了陵光确认的。为了让庚辰能品尝到正常的味道，她只是平静地通知食堂自己与庚辰吃一样的东西。起初庚辰并没有发现执明与自己吃的同样的饭菜，只是有些奇怪她的饭量怎么又变小了，私下去找了陵光这才得知执明已经知道此事有一段时间了。\n庚辰立刻找到执明，却发现她正伏在水池边干呕。两个人产生了相识以来最激烈的一次争吵。\n「我只是想和你一起承担而已，难道你就这么让我心安理得地接受伤害你之后得到的安稳吗？」\n执明少见地宣泄出压在心底的真实想法，却在说完后下意识想离开。\n「抱歉。但这样的状况谁都不可能一开始就预料到，你现在该做的不是伤害自己，天通引擎还需要你去维护……」\n执明只是沉默地离开。\n再次轮到执明到玉京轮值的时候，一切如同从未发生过一样，她们坐在同一张饭桌前，谈着日常的话。\n她没有再逞强过。",
		heart_chain3 = "执明经常会到虚恒各大高校给学生讲课，顺便挑选有能力和天赋的人进入自己的实验室为优化天通引擎做准备，也正因如此与执明有师生之名的人有很多。\n虽然很多人都称呼执明为老师，但实际上真正被执明自己认可的学生只有麟钰一个。\n麟钰被引荐到四方院学习时，执明是明确拒绝了的，她自认为自己没有耐心带着一个时时刻刻跟着自己的学生，并劝导麟钰去陵光那里。但当麟钰不厌其烦地找到她时，执明看着她的眼睛犹豫了。因为从麟钰的眼神中，执明看到了曾经的自己，那不顾一切想要证明自己，想替重要的人分担压力的决心。所以执明选择给麟钰一次机会，告诉她「如果能全部答对我出的题，就收下你当学生」。\n麟钰交给执明的答卷想法非常的稚嫩，并且漏洞百出，但却意外地富有灵性和创新。\n执明当场指出麟钰有一道题的思路完全错了，然后将她带到自己的实验室亲自演示了一遍。并且在得知这些知识麟钰已经理解并吸收了之后开放了她的出入权限，不顾麟钰惊讶的神色告诉她以后改口要称自己为「老师」。",
