		name = "大国主",
		id = 1066,
		heart_chain5 = "「透过塔罗看到的命运，亦或是通过研究得到的答案，两者都是通往这个世界真理的途径，在我看来它们没有区别。」\n掀开桌上排列着的其中一张塔罗牌，大国主露出了会心的笑容。\n「看来今天的实验会很顺利呢。」\n正是因为在研究中解答了许多世界的谜题，所以才会明白这个世界当中的更多未知，是研究无法解答的——这个信念构成了大国主在神秘学和科学领域均有涉及的矛盾。\n在新人管理员来到深空之眼的第一天，大国主发现自己居然无法分析出隐藏在他身上的秘密。在这样的受挫下，大国主没有像海姆达尔一样继续检查和深入自己的数据分析。她回到了自己的房间，回想着那个新人的脸，在桌上摆出了十一张的塔罗排阵——愚者、倒吊人、死神……\n当揭示到最后一张牌时，大国主几乎不曾变过的神情也产生了触动。她缓缓地揭开盖牌，在看到牌面的内容后，长长地叹了一口气。\n「居然错成这样，看来我还是修行不精呀……」",
		heart_chain1 = "二十年前，核心城曾经出现过一位惊动科研界的天才少女。她年仅十岁，便凭借着在顶级科研刊物上发表著作，而免试进入核心城大学就读。接下来，十一岁成为了顶尖学府的终身教授，十二岁达到令所有研究者都望尘莫及的荣誉高峰。\n可就在大家都期待着日后这位少女会创造出怎样伟大的成就时，少女在十二岁生日的当天，却突然留下一封辞职信不告而别。从此她再没有回到过自己的实验室，也没有以她名字署名的文章再出现在科研期刊上。一颗时代的奇迹之星突然消失，时至今日，她曾经在核心城大学办公过的房间仍未转给他人使用。\n在墙壁上挂着她曾经在这里工作的照片——\n雪银色的柔顺短发下，是一双像初春树梢上的樱花瓣般可爱的粉色眼眸。少女专注地看着机械臂耳所抓起的自己的新设计稿，脸上露出满足的微笑。",
		plot_tip = "兔兔零号在你那里怎么样？管理员……你会来吧？",
		cv_ko = "정혜원",
		like = "塔罗牌、科研",
		super_plot_tip = "约定的时间没记错吧，记得来找我。要出去玩……必须和管理员一起。",
		plot_tip_picture = "1066",
		cv_en = "Clare Corbett",
		age_en = "",
		cv_zh = "皛四白",
		cv_ja = "种崎敦美",
		heart_chain2 = "「人类学术界的研究水平对大国主来说已经触及瓶颈，想要更进一步的话，只有深空之眼的设备和资料可以满足她。」\n「可是，全然不提修正者的使命和视骸的问题，以这种方式招纳成员会不会……？况且她觉醒的时候还这么小。」\n「放宽心，只要适应一段时间，她自然会认可我们的行动的。」\n这样轻描淡写地向休解释完的奥丁，其实还隐藏了一个她与大国主交涉的关键条件。\n此后，深空之眼开始频发跳闸，设备故障等一系列问题，最后追查到的源头往往都是那间奥丁特批给大国主的实验室。而后来大国主交出的研究成果，却都是些让人哭笑不得的发明——怎么切洋葱都不会流泪的兔兔菜刀、可以听不到抱怨声的定向屏蔽耳机，不会让人察觉出来的自动回消息机……",
		organization = "深空之眼",
		heart_chain4 = "虽然大国主对她每一样发明都很自豪，但若要在其中找出最喜爱的几件，那么势必要数兔兔系列了。\n从最初的兔兔一号，到现在的兔兔二号和兔兔三号，大国主的自用作战兵器已经丰富到了钢铁巨拳、激光手枪和兔兔机器人这么丰富了。\n据悉，后续拓展的兔兔四号已经列入大国主的研发日程，但具体是什么样的设计还无人知晓。\n听说大国主为了这次兔兔四号的研发还去找了海姆达尔商量，值得让大国主做出这样的举动，真是让人更期待最后会发明出怎样厉害的东西呢。\n——在科研经费审批的评估会上，替隐科组争取的弥芙尔如是说道。",
		heart_chain3 = "「交流什么的，只要保持最低限度的不就好了吗？」\n保持着这种观点，平日里的大国主基本很少说话，甚至连表情的浮动也难以看到。如果你为了一些琐事，在她专注研究时打扰到她，会毫无疑问收获到一道仿佛可以冻结一切的冰冷视线。\n此外，希望大国主能配合任务出动也是天方夜谭——\n尽管大国主的各项发明都拥有着不俗的战斗力，但奥丁在邀请大国主时提出了「可以不参与任何出战行动」的条件，所以大国主也毫不客气地拒绝了作战小队的编制和所有外出任务。\n「我对消灭视骸没有兴趣，是那个人答应了我，可以在这里随便做自己希望的研究。」\n不过在做完自己的古怪发明后，剩下的时间里，大国主还是会帮处理一些第九部门的科研协助请求，毕竟下个季度的科研经费审批单还握在那个管事的女人手里……",
