		name = "欧申纳斯",
		id = 1067,
		heart_chain5 = "「时间如同流动的水，其中的一切都是在不断变化的，唯有雕塑能将它们化作不变的永恒。」\n即便改变身份，也没法改变自己已经经历了漫长年岁的事实，在这么长久的时光里欧申纳斯逐渐明白没有什么事是能够永远不变的，人心、情感……只有雕塑才能将事物最美好的时间定格，并且经年累月的流传下去。\n他到底是想借此缅怀什么，没有人知道，只是自从欧申纳斯开始创作雕塑开始就变得不苟言笑了。或许对于欧申纳斯来说，恒久不变才是他所追寻的艺术本质。\n常有人看见欧申纳斯站在欧莫菲斯最大的那座阿尔蒂斯雕像下伫立许久，对于欧莫菲斯的人们来说，这座雕像是黑暗时代的墓志铭，也是星虹时代的里程碑，阿尔蒂斯的伟大得以被久远地流传与歌颂，他的目光也得以借着这尊雕像，长久地守望欧莫菲斯。\n「老朋友，这是我能为你做的，最后的事。」",
		heart_chain1 = "与同在星虹议会的修正者成员不同，欧申纳斯为了方便在人类社会行动，每隔一段时间都会改头换面以新的身份出现。目前他对外的名字是「卡介伦」，表面上是少年有成的渔夫之子，实际上是从「黑暗时期」就开始活动的修正者，一直在为了将艺术推向更高的层次而努力。\n虽然在神力的帮助下改换容貌并不难，但经常改换身份也意味着每次都要重新接受考验，才能再次加入议会，像欧申纳斯这样不嫌弃麻烦的修正者并不多见。自议会建立以来，第三席的位置一直都是由欧申纳斯担任，也因此被哈迪斯嘲笑过是「三号钉子户」。",
		plot_tip = "委托我制作的艺术品，必须要一个身份足够重要的人来亲自验收。",
		cv_ko = "민승우",
		like = "雕塑，艺术评判",
		super_plot_tip = "",
		plot_tip_picture = "1067",
		cv_en = "Brett Calo",
		age_en = "",
		cv_zh = "刘飞",
		cv_ja = "羽多野涉",
		heart_chain2 = "欧申纳斯对于雕塑的热爱之情可以说无人能出其右，没有办公事务之际，他基本都待在自己的创作室里废寝忘食地雕刻。而与之相符的自然是每次都有着超高完成度的作品，几乎一经发表就能达到轰动欧莫菲斯的效果。有人曾评价说欧申纳斯的作品已经超越了雕塑，走近观察时仿佛能看见某种生命力在其中跃动，因此他也被誉为「创生的魔术师」。\n不过欧申纳斯对于这些虚名并不在意，他想做的自始至终都只有雕刻这一事。在欧申纳斯看来，只有雕塑才是阿尔蒂斯理念最好的载体。原石在不断被雕琢后成为精美的艺术作品，正如同欧莫菲斯经历变革后成为代表艺术至高点的原质区，欧申纳斯希望自己的雕塑能继续将这得来不易的局面延续下去。",
		organization = "星虹议会",
		heart_chain4 = "就像古典的雕塑一样，欧申纳斯平时不苟言笑，散发着令人充满压力的冷漠气场，表现得非常的严厉和毒舌。不过在天才雕塑家的表面之下，实际上自理能力却不太强。不会自己做早餐，疏于清扫整理，做园艺则会剪得一团糟……\n甚至因为生活太过单调，欧申纳斯连现代设备都不会使用，哈迪斯曾不止一次教过欧申纳斯如何使用电子设备，直到最近他才勉强掌握，平日里他还是习惯用纸笔来处理各种各样的事。\n好在这些情况在恩利尔到来后得到了改善，早餐不再枯燥单调，院子里也变得井井有条。时至今日欧申纳斯在生活上已经相当依赖恩利尔，但他似乎对此并无自觉。尽管欧申纳斯几次强调不需要做这些，总会遭到恩利尔反问，「可欧申纳斯大人，你自己做得好吗？」\n欧申纳斯觉得自己可以，但每次都以失败告终，后来为了能更快吃到恩利尔的早点，欧申纳斯将自己的卧室搬到了和恩利尔相同的楼层。",
		heart_chain3 = "大约五年前，因为和千星学院院长出现了观点上的分歧，欧申纳斯与他定下了赌约：由欧申纳斯领养一名孤儿并亲自培养，看看几年后他的造诣能否赶上欧申纳斯，而也因为这个赌约，恩利尔被接到了欧申纳斯家中。\n起初欧申纳斯并不看好这个孩子，对于教导的事也只是偶尔提及一嘴。实际上想要成为欧申纳斯学生的人数不胜数，而欧申纳斯在数百年中也早就见过不少天赋斐然的人才，但他们最终都没有达到和自己相同的高度。所以对于恩利尔，欧申纳斯也并没抱有期待。最开始对于恩利尔的教导也并不怎么上心，通常只是浅浅讲解基础知识。而恩利尔也确实只做出了一些有形无神的作品，这让欧申纳斯更加失望。\n不过在某件事发生后，欧申纳斯知道，恩利尔已经觉醒了「自我」，之后他不再有所保留，将自己的知识倾囊相授。",
		weight = "70kg",
