	[1068] = {
		birthday = "12月24日",
		height = "156cm",
		name = "恩利尔",
		id = 1068,
		heart_chain5 = "关于那个夜晚发生了什么，根据欧申纳斯所说，那天恩利尔半夜突然来到雕刻室，砸碎了他之前所有的作品。然后他将自己关在房间里整整三天三夜，不吃不喝，最后拿出了一个表情微妙的人像，迷茫和坚定两种情绪被整合在人像的五官上，显得不伦不类，用旁人的眼光来看就是一个十足的半成品。\n「他说，那是他自己，」欧申纳斯说，「而他只是一个半成品。」\n而恩利尔则说，那天晚上他回想起自己学习中的种种，都只是在对他人的作品临摹罢了，始终没有自己的东西在其中，也正因为如此，自己不论如何都没法雕出像欧申纳斯那般极具灵魂的作品。欧申纳斯的话让他明白雕刻不应该是单纯对技巧的钻研，更是对内心深处的挖掘。所以他才毁坏作品，向过去的自己告别。在这之后恩利尔被送入千星学院深造，向着自己的目标更近了一步。",
		heart_chain1 = "恩利尔从孤儿院时期就表现得与其他的孩子大不一样，他有些沉默寡言，几乎没有什么朋友，但却对雕塑展现出了很高的兴趣。孤儿院中仅有的杂志书籍早已被恩利尔熟记于心，他也时常自己动手用泥土尝试着做些在书上看见的雕塑作品。而在这些艺术品中，他模仿最多的是「德里安」所做的雕塑。即便只能看到图片记载，恩利尔也从中感受到了作品的灵魂存在，那种直击灵魂的感觉让他第一次知道艺术作品也可以这么有力量。因为不怎么活泼的性格，愿意领养恩利尔的人也迟迟没有出现。不过他也早就习惯了这样的事，所以当听到自己被欧申纳斯收养的消息时，恩利尔表现得有些迷茫。\n「只是现在想来，当时能遇到父亲，真是太好了。」",
		plot_tip = "管理员，欢迎来到千星学院餐厅。今天的早餐要来点什么呢？",
		cv_ko = "남도형",
		like = "雕塑，家务",
		super_plot_tip = "",
		plot_tip_picture = "1068",
		cv_en = "Caleb Yen",
		age_en = "",
		cv_zh = "冯霖",
		cv_ja = "永塚拓马",
		heart_chain2 = "对于这个突然出现的新养父，恩利尔的第一印象来源于他的大宅，第一次迈入那座富丽堂皇的「宫殿」之时，他都有些怀疑是自己走错了地方。而在听说他是星虹议会的第三席时，恩利尔更加觉得是自己听错了，对他来说议员们都是高高在上的存在，能够见到都已经是奢望，更何况是自己仰慕已久的雕塑名家。不过欧申纳斯并未摆出什么架子，只是说了之后会教他雕塑的技艺便兀自离开了，抱着许多的疑问恩利尔开始了新的生活。\n然而之后的几天，欧申纳斯都并没有再出现在恩利尔的面前，像是遗忘了这位养子一般。看到欧申纳斯没有限制自己的意思，恩利尔也就在大宅中四处观摩起来，亲眼看到自己曾经在杂志上见过的名作，给他带来的震撼远比图片更为强烈。在好奇心驱使下，恩利尔便偷偷在欧申纳斯的工作室外观摩起他创作的过程，叮咣声中石屑飞散，栩栩如生的作品也逐渐成型，欧申纳斯脸上透露出的专注让恩利尔逐渐沉浸其中，等他再次反应过来时，已经不自觉地迈步走进工作室了。也就是从那时起恩利尔就下定了决心，要跟随欧申纳斯全心学习雕塑。",
		organization = "千星学院",
		heart_chain4 = "刚开始的学习生活并不怎么尽人意，恩利尔一度认为自己是因为雕塑的天赋被收养的，因此他对雕塑格外上心。他渴望得到养父的认可，无论是课本，图册，还是实物观察，他总能做到尽善尽美，不少人对他的作品赞不绝口，只有欧申纳斯一直嗤之以鼻。恩利尔越努力，欧申纳斯就越不满意，虽然看上去他们的关系亲近了，但是恩利尔却为此感到痛苦。\n在与欧申纳斯一起生活的过程中，恩利尔也逐渐了解到关于自己的某个赌约。得知自己被收养的原因时，他也曾有一瞬间的动摇，怀疑起自己是不是没有才能，更加不确定欧申纳斯对自己的看法。恩利尔逐渐感到自己身陷在压力的泥沼之中，这也让他的学习变得停滞不前。度过了浑浑噩噩的几天后，恩利尔找到了正在工作的欧申纳斯希望要一个说法。虽然第三席并没有停下手中的动作，但却少见地开口了——\n「想做出怎么样的作品，是由你自己决定的。只不过现在的你，还差得很远。」\n虽然欧申纳斯表现得像是无意提及，但恩利尔很快明白了他的意思，恭敬地鞠了一躬后退出了工作室。随后他在某个夜晚做出了一个大胆的决定，虽然恩利尔不太愿意提及发生了什么，但这个决定也确实让他们之间的隔阂被打破。",
		heart_chain3 = "在被欧申纳斯收养后，恩利尔渐渐发现自己这个看上去神秘而完美的养父其实问题很多——\n他不擅长收拾自己，经常会将正装穿错；因为不懂怎么烹饪，自制食物的味道一言难尽；他每次都会将工作室弄得一团乱，但又不想让其他人进自己的工作室，因而总是等杂物堆积到几乎无处落脚时才会勉强收拾一次……\n于是恩利尔开始为欧申纳斯做起了一些小事：他在欧申纳斯睡醒前按照一周的营养表煮好早点，在他出行前替他整理好衣着，在他工作完后替他收拾工作室……打扫卫生，裁剪花园的工作也都没有落下——突然两个人的关系像是颠倒了一般，收养的人变成了被照顾的人，欧申纳斯也在无数次自理失败后选择了妥协，选择交给恩利尔打点家里的一切。",
