	[1070] = {
		birthday = "6月19日",
		height = "162cm",
		name = "金乌",
		id = 1070,
		heart_chain5 = "金乌的行动力很强，无论什么事情，她都是一拍脑袋就去做，而且大多数时候结果还不错。\n在大家的印象里，她向来是一个勇气十足的人，但如果再了解她一点，就会发现……\n「乌很有勇气？咦？其实乌一直都很怕哦，小时候乌经常搞砸事情，每次都要做很久的心理准备才敢踏出第一步。」\n「但是，一想到『魑魅』会为祸人间，乌的勇气就占了上风！毕竟比起乌的那点小情绪，还是『世界和平』更重要！」\n对于金乌而言，越是重要、难办的事情，她越是会将其套上晦涩难懂的奇怪用词，了解这一点后就能够明白，她什么时候才需要真正的帮助……",
		heart_chain1 = "金乌，虚恒出身。从小跟随老师羲和在南交岛群山中的若木宫修习天通术。\n自金乌记事起，她就一直生活在若木宫中。在下山历练之前，关于外界的情况，金乌都是从老师的口述中听闻的。饮食起居，她几乎一律遵从老师的习惯——唯独一件事除外。\n羲和的口味清淡，但金乌却热爱着重油重辣的毛血旺。这要归功于前来拜访的庚辰：自从吃过庚辰做的菜后，金乌便觉得自己发现了食物的终极意义。此后羲和做的餐食已经无法满足她了，她开始自己研究菜谱。\n金乌开始自己动手丰衣足食，对羲和来说算件好事，毕竟可以少操一份心。但锅只有一口，羲和那清淡的菜多少还是有些被串味……\n这不是自己要让金乌下山历练的原因——羲和特地解释了这一点。",
		plot_tip = "和乌一起去冒险吧！乌相信，和「命定的伙伴」一起，就能克服任何困难~",
		cv_ko = "강새봄",
		like = "漫画、玩偶、风水学",
		super_plot_tip = "",
		plot_tip_picture = "1070",
		cv_en = "Rebecca Wang",
		age_en = "",
		cv_zh = "十四",
		cv_ja = "大空直美",
		heart_chain2 = "羲和认为金乌尚需入世历练，才能获得真正的成长。\n但金乌耿直率性的性格，让她的修行之旅一波三折。再者，金乌不知从何时产生的奇怪思考方式，更让本不如意的情况雪上加霜。\n「呔，猫妖休走！哼哼，乌已在此埋伏多时了，为夺乌的食物竟不惜变化作这般可爱模样，看来我们之间必有命数的一战……喂，等下，乌的外卖！」金乌手持十曜，大声喊叫道。\n那只叼着外卖的橘猫「喵~」的一声便溜到树上了，利索地咬开了外卖包装，开始撕咬装在里面的烤鱼。\n「姐姐，你为什么不把它打下来啊？待会没东西吃了哦……」站在金乌身旁的小孩托着腮帮，不解地问道。\n「这家伙瘦骨嶙峋的，身上的伤口还在流血，咳咳！当然，主要是它头顶没有『魑魅』的印记，所以呢……乌决定放它一马……」金乌叉着腰，一脸娇憨地说道。\n第二天，大树下便多了一个瓦楞箱，上面贴着：「注意！注意！此处有猫妖出没！请勿惊扰！」箱子里，橘猫正睡得香甜。\n显然，对于完成羲和的期望，她还有很长的一段路需要走……不过，现在这样，也未尝不是好事。",
		organization = "无",
		heart_chain4 = "由于金乌的言行举止与他人大相径庭，因此，大家对金乌的第一印象通常是「一个一本正经的笨蛋」。\n但事实上，金乌的悟性非常之高。\n在金乌意识到吃辣才是自己的归宿后，她立刻开始尝试自己做菜，事实证明，她自己琢磨的做菜技术，已经能够达到虚恒大厨的水平。\n羲和在教授金乌天通术要领时，金乌时常打盹。但直到完全睡着前她所听到的部分，她都能记住。待到实战环节，她也只需要稍加练习便可收放自如。\n由于成长环境的限制，金乌对外面世界的认知，可能会产生「小小的偏差」。但她所抱持着的「善」和「正义」，其本质放之四海而皆准，不会因为对外界认知的偏差而错误。",
		heart_chain3 = "如果你进入金乌的房间，你一定会惊讶于她的书架——上面满满当当地摆着各种少年漫画。\n她将这些拥有五彩斑斓封面的书本奉为圭臬，每天起床，她都会用天通术占卜今日大吉数字，并顺着行数挑选对应的漫画。虔诚地阅读完后，她将书页规整抚平，庄重地放回书架。\n「为什么要这么做？因为《元典抄本》是乌的启示录，它会揭示『魑魅』一行今日将会在何处为非作歹。乌作为正义的伙伴，已经打败了好几个为祸人间的魑魅下属！」\n「具体是谁？哼哼~分别是『把小孩困在树上的扭曲树精』『特意瘫在老奶奶面前的香蕉皮妖怪』『横在巷子里散发毒气的垃圾桶精』……」\n金乌游历至鲤港时，偶然发现了一位与漫画中的反派模样十分相像的人，于是跟随其来到光轨站。\n结果金乌被其反制打晕，后不知为何搭乘上了光轨，来到了艾因索菲。她对神秘人的唯一印象只有金发与金瞳，因此在来到艾因索菲后，她误认为阿波罗就是那反派神秘人，后来才发现是误会一场。\n「之前乌把阿波罗认成『魑魅』，用十曜敲了他脑壳，乌真的超级抱歉……他真的好温柔，脑袋明明在流血，不但没有责怪我，还在说安慰我的话……」",
