	[1071] = {
		birthday = "5月24日",
		height = "182cm",
		name = "孟章",
		id = 1071,
		heart_chain5 = "身边的人接连离去，孟章逐渐认定独自前行才是最好的选择。他从未对自己的处境有过安全感——独狼总需要十倍警惕才能生存。\n他总是一视同仁地怀疑所有人，待到线索足够证明此人可信，方才解除怀疑。\n不过，对小孩子是个例外。\n他从来不会拒绝孩子们的请求，譬如将漂荡在河中央的皮球捞上来，或者取下挂在枝头的风筝。\n街头巷尾的孩子中总有几个调皮捣蛋的，会故意使坏。某次孟章就因为帮几个孩子捡篱笆内的毽子，被恶犬猛追了三条街。\n即使如此，他仍然会相信向他求援的孩子们，不曾有过怀疑。\n他对此的说法是，自己「不太擅长应付小孩子」，所以「不是很会拒绝」。\n……其实只是看到小孩子，想起从前的自己罢了。",
		heart_chain1 = "早年虚恒的机关术大师「烛」，是孟章母亲的好友，孟章称她为「烛姐」。彼时他们两家住得很近，常有往来。孟章天资聪颖，年纪尚小时就遍览古籍，对于一些手作玩物也能立刻上手，父母念他有此天赋，于是让孟章跟随烛学习机关术。\n过人的天资使得年纪尚小的孟章有些自负。烛出的难题，他悉数解出，好几次到了约定上课的时间，他却不见人影。\n烛感觉到了他心态的变化，于是她给孟章出了新的难题：尝试爬上不远处一座高山的山顶。她一并说，假如能顺利登顶，那便算是出师了，不必再来学习。然而那山上早已布置了机关，孟章终究只能在山腰打转，最后只得返回。\n「一山更有一山高，我知道烛姐你要告诉我这个道理。但我只是尚没有学到那些技术罢了……烛姐这么做，又何尝不是一种自负呢？」\n烛听罢愣了几秒，转身走进屋里。孟章正疑惑她要做什么，却被屋内飞出的不明物体正中脑门。他回了回神，看到那砖头似的物件，是一本厚厚的《空间技术机械化运用原理》。\n几天后，孟章成功解开了山腰的复杂机关。而烛预计到了他大约今日学成，早已在山上等候。两人坐在山顶，烛晃着手中的易拉罐，孟章则偷偷把她带来的花生米吃得一粒不剩。\n此番经历之后，孟章的学习态度确实变得比往常认真数倍。\n再后来，某个清冷的雨夜中，他终究没等到烛姐回来。",
		plot_tip = "",
		cv_ko = "박주광",
		like = "市井闲逛，收集古物",
		super_plot_tip = "",
		plot_tip_picture = "1071",
		cv_en = "David Cui Cui",
		age_en = "",
		cv_zh = "张沛",
		cv_ja = "杉山纪彰",
		heart_chain2 = "孟章的父母在云歌之变中去世，此后他便由烛一人照顾。烛带着孟章解决了许多混乱，孟章也在自己能力范围内为大家带来了帮助。在此期间，孟章觉醒了修正者意识。\n孟章的知名度在嵎夷一带逐渐提高，庚辰也有意邀请他加入四方院，出任嵎夷代理。然而孟章此时并不想上任。接连遭遇变故后已是孑然一身的他，彼时只想远离一切，过逍遥自在的生活。\n庚辰对孟章的说法表示理解，并未再多说什么。然而那块「嵎夷」的令牌，庚辰始终没有交到他人手中。\n虚恒慢慢从灾难中恢复过来，人们的生活步入正轨。于是孟章回到旧城山中，独自生活了两年，不问世事。\n……\n他随手掸下肩上的落叶，江河上的太阳仿佛只为他一人而坠。",
		organization = "四方院",
		heart_chain4 = "孟章似乎能在任何地方找到自己的位置。\n在市井街头，他是个散漫的闲人，或是淘古玩的行家，能与街口的大爷谈笑风生。在四方院内，他是一方代理，只不过不太管事，但若论及要务，多少也能说上两句。在不见光处，他步步斡旋，全身而退。在视骸面前，他是修正者，身法飘逸，剑术卓绝。无论走到何处，他都是那般如鱼得水、左右逢源。\n「那么，你是什么人呢？我的意思是——你自己。」实在摸不清他的思绪，于是尝试这样问他。\n「我？我嘛……」他的眼神飘向不知何处，欲盖弥彰地伸手挠了挠头。\n「你就当我，只是个爱摆弄机关的无趣家伙吧。」\n他或许从来没有悠闲过。",
		heart_chain3 = "独自生活的日子里，孟章常去旧城区闲逛，也常在断壁残垣中见到熟悉的物件。或许他在古玩市场中走动时，心境与行走在旧城区相差无几。\n孟章在山中独居已有六百余日。这天，他摆弄着一个复杂的机关锁。这是他小时候给自己留下的难题。\n孟章年纪尚小的时候，一般的「乾坤锁」就早已难不倒他，于是他在原本的锁上多加了六十四道结扣，以此消磨时光。当时的他，尝试了无数次也未能成功，便只得寄希望于将来的自己。现在，这个「将来的孟章」尝试了很多次，锁扣仍然杂乱无序。他没来由地有些急迫，不觉开始用上蛮力。\n一瞬间，经历长久岁月、内部早已朽坏的锁在他手中碎裂。\n他确实把锁解开了。\n他将山中小屋清理干净，与枝头的麻雀道别，走出山中，离开旧城，登上天梯。\n「你想通了吗，自己究竟想做什么？」\n「我只是个志向平平的俗人，我只希望自己的日子安安稳稳。」\n束发的青年直直站在厅堂中央。他面前的白发女人没再说什么，只是默默点了点头。",
