	[1072] = {
		birthday = "8月8日",
		height = "143cm",
		name = "禄良",
		id = 1072,
		heart_chain5 = "失踪已久的禄良终于再次回到天禄贸易董事会，并公布了一个令所有人吃惊的决定——禄良将自己持有的60%的股权全部拆分，并下放给来自各个旧坊市的个体商户。同时天禄贸易将取消全部金融业务，转而大力投资虚恒各地的新兴商业，同时与四方院合作积极投资新兴但风险极高的光轨列车制造业与重力引擎制造业，并斥资修建工厂，大批招收工人。此举立刻遭到了大股东的一致反对，但反对意见被禄良一票否决。\n在这些决策被实施后，立刻得到了无数新兴商业户主的大力支持，天禄贸易奇迹般地募集到了令人咋舌的大笔资金，一举扭转了股市的颓势。那些持反对意见的股东也都被稀释了股权，再也无法对企业的发展指手画脚。玉京的新兴商业也因为大量资金的注入，焕发出无限生机。\n同时时代也站在了禄良的这一边，不出两年，虚恒区的光轨列车制造业与重力引擎制造业迅速崛起到能够和诺伊汉萨区的智械制造业相比肩的水平，成为了能够和塔列朗家族企业一较高下的商业巨头。由于禄良推行的股权下放策略，即便天禄贸易几乎垄断了虚恒区的原材料进口贸易，却仍旧被大多数商家支持，甚至获得了四方院的首肯。 而那些抱残守缺的矿业巨头则在这一过程中先后变卖资产，湮灭于历史的浪潮之中。",
		heart_chain1 = "幼年时的禄良每天主要做两种事：帮助养父清账；跟随养母砍价。在这个过程中，禄良养成了精打细算的性格，同时看着养父母为了一点小钱就整日发愁，禄良开始坚信「挣到钱就可以解决一切问题」。\n秉持着这种信念，禄良很早就开始帮助父亲经商。由于禄良天生就拥有超绝的数学天赋和一副伶俐的口舌，她混迹于商贩聚集的市井街巷时如鱼得水。任何错综复杂的账目，在她手里不消片刻便能理清。在玉京的各大集市中，几乎没有商贩能挡住禄良的砍价。\n另外根据坊间知情人的传闻，禄良甚至可以把石头说成铁再按照金子的价格卖出去。她满脑子古灵精怪，做生意从不赔钱，讲道理也绝不理亏，很快就获得了一个「铁嘴财迷」的称号。\n凭借这种天赋，禄良很快就将养父的小本生意扩展成了远近闻名的「天禄商行」，并作为年龄最小的老板娘，闻名于各大坊市。",
		plot_tip = "",
		cv_ko = "소연",
		like = "理财、经商、麻将",
		super_plot_tip = "",
		plot_tip_picture = "1072",
		cv_en = "Xanthe Huynh",
		age_en = "",
		cv_zh = "王晓彤",
		cv_ja = "新井里美",
		heart_chain2 = "在与四方院合作的过程中，禄良结识了庚辰，并领略到了庚辰所坚持的修正者的理念，并接到了对方的邀请——但她并不完全认同庚辰的理念，同时也拒绝了庚辰的邀请。相比于完全加入四方院去履行什么使命，她还是喜欢直接跟各式各样的人类打交道。\n于是禄良从玉京中心城区搬回自己长大的街市，隐藏了天禄贸易幕后总裁的身份，经常出没于摆摊集市和各种各样的小吃摊，像是个贪恋人间烟火的仙女丫头，一晃数十年过去，一直如此。就算有知情人提起，也很少有人相信这个小丫头就是那个几十年前创立天禄贸易的传奇人物。",
		organization = "天禄贸易",
		heart_chain4 = "禄良忽然发现，此刻的她经过辛苦打拼拥有了万贯家财，在那些掌控股市的巨头眼里也不过只是个待宰的羔羊，这些矿业巨头利用股市转瞬间就做空了天禄贸易将近一半的资产。虽然禄良拥有超绝的数学天赋，仅凭心算就能通过交易所屏幕上的大数字瞬间估算出下一步的股价，但她根本无法扭转这些被人为控制的股市风向。矿业巨头甚至还使出了联名排挤天禄贸易参加金融会谈的卑鄙手段，让禄良引以为傲的游说口才也毫无用武之地。\n眼看着天禄贸易剩下的资产也将被收割殆尽，禄良终于意识到，一个人即便挣再多的钱，有些事情也无法改变。心灰意冷的禄良逃回了养父母那坐落于旧坊市的家，躲开了咄咄逼人的大股东和新闻记者，回到了养父母的怀抱里，从叱诧风云的总裁重新变回了那个才十几岁的市井女孩儿。\n养父母心疼禄良这个唯一的养女，于是替她挡下所有来访者，希望她能够在这场注定失败的商战落幕之前，好好享受下一个普通女孩儿该有的生活。于是禄良重新回到她无比熟悉的市井之中，同摆摊的大爷砍价，品尝新开的麻辣烫小吃摊……禄良渐渐发现，四方院决定让虚恒区转型之后，这些原本生活拮据的普通虚恒人都渐渐赚到了一些小钱，生活远比之前宽裕。但矿业巨头垄断了上层商业资源，这些虚恒人只能继续做市井小贩，干一些过时的买卖。\n看着这一切，禄良终于意识到，她所追求的财富并不存在于泡沫一般虚幻的股市，也与交易所大屏幕上那些毫无生气的大数字无关。她所追求的财富，就在这市井之间的一次次砍价交锋中，就在每一顿普通但美味的麻辣烫中，被烟火气熏烫着，与被精致包装的「高端商业」格格不入，但远比股市中的天文数字更不可估量。\n禄良最终下定了决心——一个人挣再多钱也无法改变的事，就让更多的人挣更多的钱去改变！",
		heart_chain3 = "禄良十岁时正值虚恒区改革期，彼时的虚恒人已经从之前的灾难中吸取到教训，四方院决定让虚恒从资源产地转型成工业品产地，后续虚恒人研究云歌石而掌握的重力科技则为这个决定提供了可能。\n禄良凭借超前的商业嗅觉看到了未来虚恒区对原材料进口的旺盛需求，而后迅速调整天禄商行的经营方向，承包了大量原材料进口贸易，天禄商行的规模迅速扩大。数年后，禄良越来越富有，但她还想挣到更多的钱，于是搬出了自己长大的坊市，并让天禄商行成功上市。\n但四方院的这一政策触犯了虚恒区矿业巨头的利益，他们更希望虚恒继续作为一个资源输出区，于是决定暗算以天禄商行为首的新兴企业来使这一政策破产。随后经过多方运作，连接虚恒区的光轨被尽数占用。天禄商行恰好在此刻接到了一份大宗商单，要保证货物及时抵达玉京，商行的货运列车不得不取道一条被废弃已久的光轨。据说这条光轨上曾经发生过怪物袭击的骇人事件，因此才被废弃。\n禄良知道这份商单对天禄商行意义重大，于是力排众议，并亲自押运货运列车。这趟列车果然如同幕后黑手设想的那样遭遇了变故，行至中途误入视骸制造的源层裂隙，并遭到视骸的围攻。危急时刻，禄良终于彻底觉醒了自身修正者的力量，并成功击退了视骸，护送列车安全抵达玉京。或许是商业思维入脑，禄良并没有深究自身的修正者力量来源于何处，而是开始思考这种力量对生意的好处。于是禄良迅速伪造了货列失事的消息，麻痹对手的同时召集大量拥有类似能力的人组成安保部队护送列车，借助这条「专属」光轨大量进货，最终成功瞒天过海，度过了这次危机，随后天禄商行也历经数次扩张，并最终更名为天禄贸易。\n然而此刻天禄贸易已经是新兴企业中唯一的幸存者，同时矿业巨头们也撕下了伪装，正式打响了一场商战。暗算天禄贸易失败后，矿业巨头们试图凭借雄厚的家底，利用股市搞垮对方。禄良毫不示弱，她决定利用自己积攒的资本与商业天赋同那些矿业巨头正面对决。",
