		id = 1073,
		heart_chain5 = "在执明前往夏什瓦特之后，天理阁的大部分事务便交予麟钰处理，于是，这位小小的助理一下子成为了天理阁的「临时负责人」。\n身份的转变让麟钰有点措手不及。虽然需要处理的事项没有太大变化，但少了执明老师的指导，某些研究她找不到方向，某些决定她拿不准主意。\n「怎么做才对？」成为麟钰心中最难解的问题。\n四方院的其他代理人看见麟钰发愁的样子，常常暗中指点她。得益于代理们的帮助，天理阁在麟钰的打理之下也勉强能运作下去。\n在承蒙关照的同时，代理们的思维方式也影响着麟钰。\n陵光以柔化刚、孟章运筹帷幄、监兵坚定强大……这些都被她一一吸收，并学着用更成熟的方式来思考问题，逐渐地，麟钰也开始能够独立做出决定。\n从调整天理阁三餐食谱，到负责对付视骸的新型道具开发，麟钰事无巨细地安排着天理阁的事务，努力地让天理阁发挥出应有的作用。\n虽然她仍然不知道这些决定到底是「对」还是「错」，但从结果来看，一切有条不紊，便是最好。\n刚接受新身份时，麟钰只是希望等到执明老师回来那天，能够将天理阁完好无缺地归还于她的话就谢天谢地了；\n而现在的麟钰想要成为能够独当一面的力量，成为保护大家的力量。也许成长的道路还很长，但麟钰已经迈出了第一步。",
		heart_chain1 = "成为天理阁的得力助手之前，麟钰就展现出与年龄不符的懂事。\n在同龄人无忧无虑的年纪，麟钰却与姐姐英招过着居无定所的生活，两人的生活经费全靠英招四处打工维持。麟钰将姐姐的忙碌看在眼里，想要帮姐姐排忧解难，而英招却总是轻描淡写地带过自己的压力。但是，在好几个深夜，睡眼惺忪的小麟钰会看见姐姐拖着疲惫的身体回到家，却因为不忍吵醒麟钰而趴在桌子上将就睡着的情形。\n麟钰自知年幼，无法在工作上提供帮助，于是她主动承担起生活方面的职责：用精巧的刺绣遮盖衣服上破损的地方，用便宜实惠的食材做出可口的家常菜，用玻璃瓶做成风铃等等。在麟钰的努力下，两人的出租屋也有了「家」的感觉。\n心灵手巧的麟钰对机械工程的兴趣，也许就是从这个时候萌芽的。\n当英招从打工的书店中带回一本卖不出去的《机械工程复原研究》时，她更明确了自己对机械工程的喜好。\n照着书本上的教程，麟钰亲手制作了许多精巧的玩意：机关锁、天气预报球、自动浇水装置……麟钰创造的初衷，原本只是在处理家务之外的琐碎时间里找点乐趣，而当她看到自己制作的自动按摩装置能够有效缓解姐姐工作的疲惫之后，她从机械制造中找到了新的意义。\n小小的装置展现出想象之外的功用，不仅能够让生活更为便利，还能具象化为一个个微笑，让麟钰感受到自己在发挥作用，并真实地体会到帮助他人的快乐。",
		plot_tip = "",
		cv_ko = "김하영",
		like = "下厨、逗弄姐姐带回的动物",
		super_plot_tip = "",
		plot_tip_picture = "1073",
		cv_en = "Melissa White",
		age_en = "",
		cv_zh = "陈阳",
		cv_ja = "铃代纱弓",
		heart_chain2 = "最初，麟钰对机关与机械的理解皆从书上得来，用它来解决生活中的小问题便是她对机关术的所有想象。\n随着学习的深入，麟钰发现机关术的作用不止于此，她也希望用机关术来解决一些更为「关键」的事情。\n英招打工的店中所发生的货品失窃事件成为了契机。因此她也开始暗中调查，追踪到犯人留下的蛛丝马迹，并成功地运用所学的机关术困住了这几名窃贼。\n但机关术能做到的事情仅限于此，最终姐妹二人还是敌不过这几名窃贼的武力压制，所幸得到天禄贸易的陆吾出手相救，姐妹俩逃过一劫，并因此阴差阳错地加入了天禄贸易。\n少女想要证明自己的心受了挫败。每当拿起机关装置，麟钰脑海中会浮现那日的情景，她开始怀疑学习机械工程的意义，担心自己只会成为别人的麻烦。\n被禄良引荐到执明手下进行学习之后，麟钰消极的想法有所改变。\n最开始的她并不被执明看好，但麟钰用稚嫩却充满创造力的想法通过了执明的考验，还成为了老师的得力助手。\n在新环境接触到的新知识让麟钰大开眼界，执明老师的认可也让麟钰稍微找回了信心。不过，麟钰再也不急于证明自己在机械工程方面的能力，相反，她认识到自己只是个初心者。\n「我现在要做的……除了不给大家惹麻烦，就是沉下心来，读懂每本书，做好每个任务。」麟钰脚踏实地地吸收着新知识，期待着有一天能真正将所学变为所用。",
		organization = "四方院",
		heart_chain4 = "刚来到四方院时，麟钰时常感到不习惯。敞亮的庭院，精致的楼阁，先进的实验室，四方院中的很多事物都是麟钰从未见识过的。\n作为四方院中的重要实验机构，天理阁中不时会有高校学生和专业学者前来研学或交流。麟钰经常能看到专业人士们积极讨论的情形，对比之下，虽然自己被执明老师纳入门下，但她这个初来乍到的小学徒连实验室的仪器都认不全，更别说参与到学术交流中去。\n麟钰更珍惜这个在天理阁跟随执明老师学习的机会，她小心翼翼地探索着这里的「规矩」：作息时间、活动范围、规章守则……麟钰仔细观察着其他人的行为，努力让自己融入新环境，早日配得上「执明老师的弟子」这个身份。\n认不全实验室的仪器，麟钰便将它们的外观和结构一一临摹到笔记本上，分析每个部件的结构，搞懂仪器运作的原理；融入不了其他人的讨论，麟钰便成天泡在天理阁的资料室中，废寝忘食地阅读所有教材和资料。来天理阁进行交流的学者们经常能看到麟钰拿着小板凳四处走动，那是她为了拿到书架最顶层那些晦涩的教材时最重要的工具。\n执明捕捉到了麟钰拘谨却忙碌的身影，于是让麟钰试着对天理阁提出改善方案，而麟钰小心翼翼地交出了答案。\n那是一个书架改造设计案，算不上新颖，也算不上完善。执明没有过多评价，只是对方案稍加指点，让麟钰自行领悟。不出三两日，资料室里出现了一个新型书架，无论是想查阅存放在哪一层的资料，只需要简单的操作便可以传送到面前，免去了四处寻找的麻烦。\n「既然改动了天理阁的设备，那这一角的维护工作日后就属于你了。」执明这样对麟钰说。就这样，麟钰的小创造成为了天理阁的一部分，而麟钰本人也因此与其他学者产生了交流，从而有了飞速的成长。\n麟钰知道，老师是在给她机会，证明自己有能力成为天理阁的一员；但麟钰不知道的是，成为执明弟子的条件，并不是这个简易的小小书架，而是她身上无限进步的可能，和那颗想要帮助他人的心。",
		heart_chain3 = "在厨艺方面，麟钰并不是天赋型选手。\n麟钰从小就学着下厨做饭，但刚开始，她能够掌握的菜品也不过三四道。究其原因，还是虚恒的菜谱里所写的「适量」「少许」等字眼太过难以揣测，让麟钰在调味时无法把控正确的用量，因此，姐妹俩的饭桌上偶尔会出现一道黑漆漆的红烧鱼也不出奇。\n好在，麟钰的优点之一是不会轻易言败，在多次练习和反复调整中，麟钰已经能够根据时令、天气还有食材的新鲜程度做出不同的菜肴。\n只不过，能够好好坐在餐桌上吃饭的时间愈来愈少。英招是天禄贸易的人事和贸易部长，每日要处理的事务有小山那么高；而麟钰自己是执明老师的助理，不仅要学习新的知识，还需要负责调试天通引擎的部分工作。\n工作成为生活的主干，而最为平常的一日三餐却成为了奢望。但两方面都同等重要，麟钰也开始寻找一个能在两者之间取得平衡的方法。\n麟钰另辟蹊径，居然发明出一种足够「高效」的烹饪方式：一边下厨，一边学习。四方院的其他人看到麟钰左右开弓的样子，总是担心她的安全，而麟钰却在循序渐进的练习中做到了真正的一心二用，不仅看完了一本本教科书，还能在饭点准时做出一桌子美食佳肴。\n「文思豆腐」是麟钰刀工的极致体现。最开始，她只是希望能让姐姐品尝到感兴趣的食物，到了后来，她在细切豆腐的重复动作中找到了平静的感觉，反而能够更为沉浸地学习。\n对麟钰来说，能一举两得的事情不多，更何况，姐妹俩也终于因此有了坐下来好好吃饭的机会。\n文思豆腐，精巧如丝，清醇如绸。看似清淡朴素，是生活中一剂缓冲，实则余味悠长，饱含了麟钰对平和日常的思念。",
