		name = "英招",
		id = 1074,
		heart_chain5 = "古老遥远的事，不着边际的事，仅存在于幻想之中的事，对英招而言，都是「难以理解之事」。\n因为对于从小只思考如何生存的她来说，「幻想」是奢侈的。\n不过，在受到妹妹的影响，开始花时间做感兴趣的事后，她似乎开始乐于听人讲述童话。那些本应在童年时成为入睡良方的故事，对于已经生活了几十余年的她而言，每一个竟都显得新奇有趣。\n「嗯，有趣的故事。……不过，为什么小红帽会分不清人与狼的面孔，居然将大灰狼错看成外婆呢？」\n下次见到她时，倘如一时间找不到话题，不如就从童话故事开始吧。",
		heart_chain1 = "作为贸易和人事部长，英招全面负责天禄贸易的人事、行政相关工作。留在莱仙阁时，她处理各部门的工作规划和联系、人员的分配调动；其他时候，则多是出差在外处理合作企业事务。大部分时候，她都处在忙碌状态。\n禄良为她安排的工作量已经是正常而言的数倍，不过对于英招来说，同时处理数件任务并不算难题，这也多亏了她曾身兼数职的经历。\n「天禄贸易的业务众多，我需要处理的事务十分庞杂。不过只要将效率提上去，还是可以挤出一些个人时间的……」\n在这短促稀缺的「个人时间」内，英招居然在住所的后院搭起了一座小花园，其中有诸多不同品类的动植物。\n照顾这么多不同种类、不同习性的生物，往往需要周密的计划制定及执行能力，某种程度上，天禄贸易的工作确实锻炼了她。\n不过，至于为什么英招每一次出差都会「恰好」路过当地的公园或是植物园……那就只有规划路线的英招自己知道了。",
		plot_tip = "有事需要我帮忙的话，随时来找我吧。",
		cv_ko = "정유정",
		like = "业务出差、照顾植物",
		super_plot_tip = "",
