		cv_zh = "张琦",
		cv_ja = "Lynn",
		heart_chain2 = "四方院的许多人都很难能把英招和麟钰联系到一起，毕竟作为姐姐的英招做事相当注重效率，工作起来就像迅雷烈风，和妹妹的娴静完全相反。\n而其中的原因是，英招在尚未加入天禄贸易时，曾经为了生计身兼数职。为了赶上每一份工作开始的时间，她必须用最快的速度完成上一项事务。\n英招这一追求速度的习惯也带到了工作之外。在天禄贸易的传闻中，英招的吃饭时间一直是个谜。因为她的动作实在太快了，很少有人能够目击。\n她基本只吃便携食品，寥寥几口就解决了一餐。然而每当麟钰到莱仙阁时，大家就会看到，「效率至上」的英招部长，与妹妹坐在一起，花上大段的时间品尝菜肴，尤其是一道制作工艺精细、工序繁杂的菜肴，名为「文思豆腐」——出自麟钰之手。\n起初，英招会教育麟钰，让她不要将时间花在这种可有可无的事情上。但既然妹妹已经花时间做了这道菜，不品尝反而是一种浪费——麟钰料到姐姐会这么想，于是总是偷偷地将文思豆腐做好。久而久之，英招也接受了这偶尔的放松时刻。虽然英招仍认为「做精致的菜肴」是浪费时间，但她同时认为，「一定程度上的时间浪费是必要的」。而且麟钰在与英招一起吃饭时十分开心，这对英招而言已经足够。\n不过，刀工熟练的麟钰经常会一边切豆腐，一边阅读机械工程教材。这争分夺秒的情形，又像极了英招。",
		organization = "天禄贸易",
		heart_chain4 = "英招加入天禄贸易，实属机缘巧合。\n当时英招打工的某家店内发生了货品丢失的事件，虽然上了年纪的店主并没有责怪的意思，但英招的责任心并不允许这样的失误出现，于是她主动请缨调查货品的去向。那一段时间除了工作外，英招都在整理相关的线索，也因此积累了许多疲劳。只是她没想到自己偶尔的失神都被麟钰看在眼里，也没想到妹妹会因为想帮助自己而开始独自追查。\n等英招接到麟钰的信息赶到现场的时候，两方已经陷入了对峙的局面中。偷走货品的是些三教九流之辈组成的团伙，没想到在出手的时候被麟钰的小机关算计，随后麟钰就找上了门，试图帮助英招讨回店里丢失的货物。英招明白了事情的原委，也知道今天或许没法善终，但她还是拿起靠在墙边的铁管，站到了麟钰的身前。\n但对于十几岁的孩子来说，要对抗数个成年人根本毫无胜算。英招很快被打倒在地，遍体鳞伤。就在她快要失去意识时，眼前纷乱的人影忽然悉数倒下。\n天禄贸易安保队的成员陆吾也在追查这个团伙，没想到正好救下姐妹二人。由于英招的境况实在不容乐观，于是陆吾将她带回天禄贸易疗养。禄良在听说了英招的事迹后收留了她和麟钰，为她们提供了像样的安身之所，并向英招提出加入天禄贸易的邀请。\n平日里，英招经常会向陆吾学习功夫。她趁手的武器，也从水管变成了卜字拐。而也是这次之后，英招变得更为担心麟钰，不敢再让她接触危险的事。",
		heart_chain3 = "英招雷厉风行的处事方式，使得大多数人都下意识认为，她是个完全没有私下生活的工作狂。但熟悉她的人都知道，她也有自己独特的爱好。\n在英招家中的后院，有一片仿佛与世隔绝的小天地。若是有幸能够进去参观，就会发现里面充斥着与主人的形象格格不入的「可爱」要素。\n一些只有在地面上才能找到的娇俏植物，以及数量众多的小巧生灵占据着这座精致的后花园。它们都是英招随商行的队伍出行时带回来的。\n「地上的环境恶劣，若是放着不管，它们或许很难存活。」\n很难想象这句话出自向来注重「效率」与「意义」的英招口中，但每每遇到这种情况，她都会暂时放下手中的工作，望着那些生灵出神。禄良说，英招是看见了自己和妹妹过去的影子。\n随着植物与动物的增加，英招也逐渐对照料它们有了兴趣，有时也会特地去各处搜罗独特的植物。于是在麟钰的帮助下，两人一起在后院搭建了这座后花园。打理工作主要还是由英招负责，麟钰偶尔也会帮忙。\n对过早担起责任的英招而言，这座花园或许就是属于她心中的柔软。",
