		name = "陵光",
		id = 1075,
		heart_chain5 = "事实上，陵光长久受到失眠的困扰。\n她并非不知道这症状的根源。无非是思虑过多，心火旺盛。若要调理，也无非是停下手头事务，停止思虑，放松精神。\n——因此，这失眠是她无论如何也不会治好的症状。\n失眠的时间是难熬的。夜深人静，她不愿打扰别人，所以她通常会坐起身，静静听窗外的虫鸣。\n虫鸣的起伏节奏，宛如大地的呼吸。她想到白日里的种种人与事，想到开出的药方，想到称药时残留在手边的一粒茯苓，那茯苓乍看又好似方糖……如此任由思绪漫游许久，她才觉有些困意袭来，于是再次躺下。\n宁愿夜夜如此辗转，她也不愿停下思虑。\n「有生有死，有得有失，有无法弥补的遗憾，有追逐终生的理想。这是人类，有限的生命，本就比我们无限停驻的时光珍贵。倘若这样珍贵的时光被病痛劫掠，对人而言又是何等的悲哀？」\n「拯救，必然要伴随着牺牲吗？虽万相盈亏、阴阳损益，然而我觉得，此问未必无解。圣人之术，为万民式，倘若人人皆能自渡，便再无需牺牲者的付出。」\n「在这一切实现之前，我来做这个牺牲者就好。」",
		heart_chain1 = "尚未觉醒时，陵光被当地的大户人家收养。她的养父母都是医师，经营着当地最大的医馆。耳濡目染之下，陵光也逐渐学会了医百病、辨百草。\n幼时的陵光，由母亲带着，坐在柜台后。她看到母亲取药、称药、煮药，看到父亲为人针灸、拔罐、正骨。她看到吵闹的孩子嫌弃药汤太苦，问能否给送些糖；伛偻的老妇带着一捆柴，问这可否抵药钱。\n医馆自然是多疾苦之人，来来往往，陵光见了太多太多。\n云歌之变后，宅子倒了，医馆倒了，陵光也再没找到过养父母。\n「父亲母亲行医一生，明明救人无数，却……我无力也无权指责天灾，但至少，我还能延续父母亲的夙愿。」",
		plot_tip = "管理员，阔别多日又见你身体抱恙……让我替你检查一下如何？",
		cv_ko = "김연우",
		like = "演奏古琴、照顾他人",
		super_plot_tip = "若是管理员对琴艺仍有兴趣……我随时欢迎你来做客。",
		plot_tip_picture = "1075",
		cv_en = "Molly Zhang",
		age_en = "",
		cv_zh = "阮从青",
		cv_ja = "三森铃子",
		heart_chain2 = "陵光年纪尚小的时候，有位客人来家中作客，即兴弹奏了一曲。那是一位琴师，陵光的母亲医好了她的病，使她弹琴的手不再无端颤抖。\n陵光被这琴声吸引，开始跟随这位琴师学习技艺。她天资过人，很快便能弹出流畅动听的曲子。\n陵光偏爱演奏慷慨激昂之曲，她说偏是这样的曲子，才能让自己由澎湃繁杂的情感中安下心来。\n「风月花鸟，虽也悠扬动听，但终究是飘渺之物。然而慷慨之思、激昂之气，有血有肉，无不触我心弦。」\n陵光至今仍保持着晨起演奏古琴的习惯。经历了一晚的睡眠，思绪浑浊不清，她便需要这样使自己清醒。清早赤炁堂的后山，总是隐约回荡着悠扬的曲声。",
		organization = "四方院",
		heart_chain4 = "在周围人的眼中，陵光是一位温柔和善的大姐姐。然而，在一般民众的眼中，她却是使人敬畏的存在。\n几十年前，为了推行更为完善的医疗保障条例，陵光曾代表四方院，与各大巨头据理力争。当时，企业为了赚取更高的利润，大幅削减平价药品的生产线，转而推行利润极高的保健品。在此情况之下，基础药物供给短缺，某些地方的人们无法获得最基本的健康保障。\n有些老人仍然时常提起，彼时的代理人，如何用她振聋发聩的质问，代替人们说出心声。\n「如今有些人，视他人疾苦为无物，将一己私利凌驾于百姓福祉之上。」\n「试问，几人惬意，能重于千万人性命吗？」\n医疗保障事件过去后，曾有人因此对她怀恨在心，并试图造谣称，赤炁堂的药材都是劣等品质，因此才售价低廉。谣言风波只持续了短短一阵便平息，因为人们都愿意相信这位肯为大家发声的代理人。\n如今，虚恒已是井井有条，少有过去那般风波。不过，陵光仍然时常会做些演讲，譬如节日贺词。\n「是诸位的辛勤，带来了今日的美满——愿诸位享受这时光。」",
		heart_chain3 = "「彼时的我，目光浅薄，竟被悔意冲昏了头脑。」\n云歌之变后很长一段时间内，她靠着悔恨与怨念行事。她无比懊悔于自己的无能：身为修正者，竟然连自己的双亲都未能救下。\n浮岛稳定后，陵光在南交开设了名为「赤炁堂」的医馆。她此举原本只是想以所谓「父母夙愿的延续」，来弥补自己的愧悔。\n医馆开设后，陵光更是不知疲倦地工作。没过多久，庚辰便注意到了陵光的异常，于是邀她谈心。\n两人促膝长谈半日，陵光幡然醒悟——单纯的悔意，并不能成为自己前行的永久支柱，反而会侵蚀心智。\n「医者仁心，父母教给我的东西，我居然忘得一干二净……一味懊悔止步不前，又怎么能治病救人呢？」",
