	[1076] = {
		birthday = "1月7日",
		height = "173cm",
		name = "庚辰",
		id = 1076,
		heart_chain5 = "庚辰取出了原质之心，是这个纪元的事。原本按照盖亚的规则，修正者不应该也并不被允许擅自取用原质之心，但是庚辰没有顾上烛的劝阻，还是这么去做了。\n她将原初的权能与原质之心链接，成功将原质之心带出了心之殿，随后利用它启动了天通引擎，成功稳定了虚恒。而完成这一切的代价则是她的权能受损，无时无刻都在接收「规则」所带来的负荷。随着时间过去，庚辰的身体也每况愈下，她的五感渐渐减弱，力量也不再能如臂指使。这是一条没法回头的路，但庚辰从未后悔。存亡之际，只要有一丝能够拯救虚恒的希望，就值得她赌上全部。一路走来，庚辰已经见证了太多的无奈、痛苦……她背负着无数次的抉择前行，放弃、拯救、甚至是对友人举剑相向。为了她所想守护的虚恒，她无言地承担这一切，也不惜为此打破规则的束缚。\n「数不尽的战斗与多少次重启，视骸也未彻底消逝。但在我看来战斗只是手段，并非是修正者全部的使命，守护才是我们存在的真正意义。」\n纵使世界庞杂，纵使身躯有限，庚辰依旧觉得自己应该去守护，这是她所认可的，并能够为之献上全部的使命。",
		heart_chain1 = "庚辰所求不多，惟愿虚恒的平稳能够持续下去。然而云歌之变毫无征兆地到来，打破了虚恒许久以来的平静。\n世道混乱，城市也几近分崩离析，科尔盖却迟迟没有行动，但庚辰已经没法坐视——她已经见证了数次的重启，而这个原质区是否能有再来的机会还未可知。\n在烛与执明等人的协助下，庚辰组建了四方院，并将虚恒的情势初步稳定了下来。多项技术和举措的落实不仅安抚了虚恒的人民，也大幅减少了云歌之变中期开始的伤亡。直到天通引擎的成功启动稳定了浮岛，这场灾难才算彻底结束。众人庆幸之际，唯有庚辰神色凝重，她明白此法并非治本，但当务之急是要让虚恒人民摆脱云歌之变的阴影。\n之后的时间里庚辰代表四方院奔走各处，切实地解决各岛住民的基础生活问题，不知不觉间积累了相当的威望，四方院也成为了虚恒人认可、仰仗的组织。甚至渐渐有人将庚辰奉为「拯救虚恒的神明」，不过庚辰每次听禄良说起这个话题，都只是淡淡地摇头。她从不觉得自己是救世主，只求能守护虚恒这一方净土。",
		plot_tip = "",
		cv_ko = "이명화",
		like = "收集字画、品茶",
		super_plot_tip = "",
		plot_tip_picture = "1076",
		cv_en = "SURA SIU",
		age_en = "",
		cv_zh = "秦紫翼",
		cv_ja = "生天目仁美",
		heart_chain2 = "最初庚辰认为，会发生云歌之变是骸能侵蚀亦或者视骸所为，然而即便她与羲和共同镇压了南交的强大视骸「混沌」，情况也依旧未见好转。她又独自潜入源层，排查了虚恒源层的每一个角落，清除在她看来的所有威胁。一年的努力过后，源层仍呈现一幅破碎景象，虚恒浮空的大地依旧在无序地运动。\n当庚辰终于理解到这灾难或许来自于世界的本身时，她也曾一度感到茫然。却不知该与谁质问。但她毕竟代表着四方院，承载着虚恒上下的企望，也早已决定要为虚恒寻求一线生机。\n「大江奔去，山则绕，壑则满，旦莫止，终入海。天地永动，万象方衡，只要不断前进，终有一天我们能找到解决问题的方法。」\n「若有那一天的话，无论代价是什么……」——陵光曾听见庚辰如此自语道，据她说那天先生仰望天通，随后良久没有说话。",
		organization = "四方院",
		heart_chain4 = "庚辰原本非常爱吃一家餐馆的麻婆豆腐，那店主对佐料的掌控得心应手，鲜香麻辣恰到好处。在浮岛完全稳定之后，这家餐馆也迁到了伴川东街。然而待她又一次来到这餐馆时，却觉得那麻婆豆腐鲜香全无，徒留麻辣。可店主又说餐馆的配方和烹调手法从未变过，其余的食客也不曾觉得口味有变。庚辰忽然明白，出问题的是她自己。\n她回到四方院，空口尝了一勺盐。嘴里的晶体化开，她却未能感受到半点咸味——这反倒让她松了一口气。陵光检查了她的身体状况，结论是由于原初权能受损，庚辰的味觉已经大幅丧失，甚至除味觉以外的感触都有不同程度的衰退。\n庚辰知道这对四方院的众人来说只会徒增负担，因此选择了隐瞒。陵光自然也没有对其他人提起此事，在人前时还常劝庚辰减淡些口味，庚辰对此也心领神会。\n世人常言酸甜苦辣咸，但唯独辣是一种痛觉。现时能够使她的生活不那么无趣的，只剩下这独一的痛觉。后来庚辰也爱上了喝茶，尤其是滚烫的热茶。热水激发出茶叶的香味，勾起她的嗅觉，沸腾的温度，又从侧面向她证明茶汤的存在。对于修正者而言，就餐本就是消遣之事。庚辰本就少有可消遣的闲暇，但这样对她而言已经足够。",
		heart_chain3 = "庚辰喜欢书画，这是四方院的众人都知道的事。云歌之变前，庚辰就常常在游历之时收集优秀的字画作品，尤其是人文写实的水墨，更是庚辰收藏中的数量之最。对庚辰而言，这些画面拼凑出了虚恒的变迁，也让她得以窥见虚恒人民生活的一角。她能从中感受到虚恒的生命力，书画也在向她展示虚恒未来无限的可能性。\n以前庚辰总会趁着闲暇在自己的房间中欣赏，甚至偶尔还会自己提笔落词。只是云歌之变后，她把大部分的藏品都捐赠了出去，由天禄贸易管理的博物院代为展出。禄良问起，庚辰只答她说四方院要管理虚恒上下，恐怕是没有时间空余了，与其让它们蒙尘，还不如让更多人有共赏的机会。\n展览非常成功，禄良来四方院找到庚辰，正想告诉她这个好消息的时候，却发现庚辰正在书桌前，面前摊开的是练功用的宣纸。她努力控制着落笔的力度，甚至额间都隐约沁出了汗迹来。可待停笔，庚辰的眉间又露出了失望的神色来——字虽方正，但细看就会发现笔势不畅，甚至有点凌乱。发现禄良敲门进来，庚辰才收了纸笔，摆出热茶来。\n「馒头，你……」\n「你看到了？呵……多日不练，有些生疏。之前给你题的字，我怕是没法再给你一副一样的了。」\n禄良的问题最终还是没有说出口，只能任由这个话题在庚辰玩笑般的自嘲后毫无痕迹的结束。",
