	[1077] = {
		birthday = "1月16日",
		height = "162cm",
		name = "武罗",
		id = 1077,
		heart_chain5 = "自遵从师父的吩咐来到大荒，武罗便一直受到各方注目，「神剑传人」、「长琴上仙的弟子」、「铸剑术的传承者」等等称号都被套在了武罗的头上，而武罗自己也认为，身为长琴的弟子，帮助边军是自己应尽之事。\n所以在边军找到武罗，希望她能够协助铸造一批武器装备时，武罗立即表示，自己会铸造出全新的盔甲武器，定能协助边军对抗荒兽。\n武罗会说出这番话，不仅是源于责任心，更是看出了边军和当地百姓对自己的期待，作为长琴上仙的弟子，他们希望自己能够铸造出新的神剑助力边军对抗荒兽。\n武罗曾作为长琴的助手参与铸造神剑的全过程，哪怕不能铸造出神剑……铸造出一把些许劣化的神兵，她认为自己应当是能做到的。\n但当她真的开始在锻炉旁工作时才发现，一切并不像自己想的那么简单，越是铸剑，她就越是感知到自己与师父的差距——自己真的能打造出众人期待的神兵吗？自己真的能成为众人期待的那个铸剑师吗？\n怀疑开始在武罗的心中不断滋生，但交付日却逐渐逼近，在最后一次挥下锻锤后，残酷的现实告诉武罗——再这样下去别说神兵了，自己什么都无法交给边军们。\n武罗只能重新评估方案，将目标从铸造神兵改为制造一批改良型的制式装备。\n待到约定的日子，武罗成功交付了一批武器装备，比起边军们原本的武装，这批装备有着诸多改进……但双方都知道，这距离神兵相距甚远。\n告别边军之后，对方那礼貌而不失尴尬的笑容一直浮现在武罗的脑海中，她将自己关在房里不断铸剑，从长剑到短刀，各式各样的武器她都尝试过，待到半年后，她才从炉火熄灭的屋子里缓缓走出。\n出关的武罗和往常一样，那张看起来有些冷漠的脸上没有任何表情，但在那之后，武罗便拒绝了科尔盖的邀请，一个人在城中开了间小工房——「武罗机电」。\n自此之后，武罗便不再为人铸剑，而是以机械师的身份为边军和当地百姓提供帮助，但偶尔也会有人看见武罗对着角落里散乱摆放的剑胚露出有些寂寞的神色。\n「师父常说铸剑之道即为锻心之道，剑之所向即为心之所向……那我的心，到底又指向何方呢？」",
		heart_chain1 = "长琴首次见到武罗是在一个雨夜。斩杀了追击武罗的凶兽后，无论长琴怎样询问少女的来历，得到的都只有支离破碎的话语，甚至会让长琴误以为自己是在与一台智械交谈。\n长琴本想将武罗送往最近的安全地带，但对方却紧紧抓着她的衣袖不肯离开。看向少女那充斥着迷茫的双眼……她简直像是看见了镜中的自己，那是失去了许多的人才会有的眼神。\n最终，长琴选择把武罗带在身边，一同回到昭黎山。经过了一段时间的接触，长琴才发现，武罗虽是修正者，但在与自己遭遇之前却是生活在荒城中，只与城中的智械进行过交流，自己只能从人类社会的常识与普通的沟通方式开始教起。\n武罗很听话，甚至可以说是有些过于听话了，就像是害怕被抛弃的流浪猫一般，只要是长琴吩咐的事情，她都会尽全力去做，只是每次结果都有些微妙。她也试着学习长琴去抚琴赏画，但却总是难以领悟这些行为的意义，于是她便将目光转到另一件更为重要的事务上——铸剑。\n长琴看出了她在机械方面的天赋，本不打算让她走铸剑这条路，但在武罗的一再恳求下，长琴最终还是教了她铸剑术，而这一次，武罗学得很快。\n时过境迁，武罗也逐渐从「长琴捡回来的女孩」变成了「长琴的弟子」。但每次武罗提出由自己接手「神剑」的铸造时，长琴都只是沉默着摇了摇头。\n「她和我不一样，也不应当被束缚在『铸剑』这条路上。终有一日……她会走向自己应行的道。」",
