		heart_chain2 = "与武罗会面前，管理员只知道对方是长琴的弟子，从没想到她会是一名机械师。\n但武罗那充斥着各类智械、电器的工房，以及当地人的言论都说明了，武罗不仅是铸剑师，更是一位技艺高超的机械师。\n在与武罗正式见面后，虽说武罗那毛茸茸的耳朵与尾巴的确引人注目，但对方专业的言谈与冷静的判断才是更为鲜明的第一印象，只可惜……这种印象甚至没能撑过一天就被刷新了——因为对方坚持要把交付给科尔盖的机甲制作成熊猫的外形。\n或许是有些心虚、又或许是第一次遇到认可自己审美的人，武罗喋喋不休地诉说着熊猫与各类毛茸茸动物的可爱之处。\n虽然有些脱线，但或许……她也有像普通少女一般，喜欢可爱小动物的一面吧——这便是管理员对武罗的第二印象。\n但在与管理员的不断接触中，武罗却总是能够刷新管理员对她的印象。最开始只是一些小事，比如遇到任何事情，武罗基本都会要求具体数据。「稍等一下」、「马上就来」、「走两步就到」，这种句子根本不存在于武罗的思考回路内。\n一开始管理员只把这种情况当成武罗具有良好时间观念的表现，但随着与武罗接触的时间逐渐变长，管理员才真正大开眼界。\n武罗为了感谢管理员对自己的帮助，准备亲自下厨款待对方，但她下厨的流程却显得非同寻常。武罗根据当地气压，以精确到小数点后两位的方式调控水温，甚至还在与菜谱中的「适量」、「少许」等字样搏斗了一小时后，选择用专业仪器对比视频称量所有调味料——最终一盘普普通通的回锅肉，她却花了几乎一整天才做好。\n这些行为在他人看来是脱线甚至令人费解的，不过在武罗眼里，这都只是必要流程的一环而已。\n「和武罗相处，该怎么说呢……有点像是剥洋葱，一层又一层，每次都能发现她新的一面。」",
		organization = "大荒边军",
		heart_chain4 = "武罗向来不愿意与人过多交流。在她看来，原本朴素直率的想法，在经过语言这一层加工后，总会变得晦涩难懂，导致他人的误解。\n所以她很喜欢机械师这份工作，能够将自己的思绪以实物而非话语来表达。 虽说偶尔也会有招致误解的情况发生，但那大多只是设计方向，又或是审美观念的差异。 这种情况只需要修改设计图就好，就算自己的想法无法准确传达，也不会有什么影响。\n所以一旦对方提出异议，武罗总会优先修改自己的设计图。只要自己的技艺也能帮上他人的忙就好，她一直这样想。\n直到管理员出现之后，她才发现，原来与他人沟通这件事，远没有自己想象中的那么难。 曾经看起来那么固执的科尔盖军士，也会因为管理员的话语而让步，那些看起来绝对不可能落地的机甲设计，也在管理员与对方的一次次商讨中逐渐被搬上议题。\n「沟通的目的是为了互相理解，既然如此……为什么要和他人拒绝沟通呢？」\n听着管理员的话语，武罗陷入了沉思。为什么自己会如此拒绝与他人沟通呢？是认为他人难以理解自己吗？又或者……是不想被他人理解呢？\n这个问题的答案，武罗尚且无法得知。但至少她知道，自己现在很想与这位管理员「沟通」。",
		heart_chain3 = "在荒兽入侵时期，前线地带有许多因人员撤离而留下的空城。而武罗……便苏醒在这样一座空城里。\n她漫无目的地走在空荡的城市中，甚至不知道该如何描述心中这份本应被称为孤独的情感。就在这时，武罗听见了声音——「欢迎来到大庆百货商场，请问您有什么需要吗？」。\n那是一台商城接待智械发出的声音，在这座空城里，有许许多多被抛下的智械依靠着自律式充电站活动着，它们成了武罗唯一能够与之沟通交流的对象。\n虽然这些普通智械上搭载的AI模块即便恭维也说不上高级，但对于武罗来说，这种程度的交流也已经弥足珍贵。其中，武罗最喜欢与之交流的是一种扮做动物的仿生智械。\n这些本作为儿童玩具诞生的智械不仅在交流上比普通的工作用智械更加自然，并且还有着如小动物般可爱的外表与毛茸茸的触感，在和它们交流的途中，武罗还结交了一个名为「潘潘」的朋友，在这座空无一人的城市中，正是这些有温度的武罗支撑着她的内心，让她没有被寂寞与孤独摧垮。\n或许是因为年少时的经历，武罗在给科尔盖的设计机甲时，总希望给机甲套上各种可爱的外观，想让这些冷冰冰的机甲多一些「人味」，不过每次都被科尔盖方面驳回了。\n即便如此，每当需要设计新机甲时，武罗总会在设计图上画出一只可爱的动物，因为她一直在心中怀揣着这样的想法——智械绝不是冷冰冰的机械，而是能够抚慰内心的伙伴。",
