		heart_chain5 = "虽然维达尔在冰冷残酷的环境中成长，也曾经以狩猎其他动物为食。但是她对于生命抱有平等的尊重，为了自己的生存而狩猎，为了生存而吃掉猎物。对视骸这样只是为了破坏而破坏，无故夺取生命的存在，维达尔感到深深的厌恶。\n另外，维达尔在极地时期还饲养了一只名为「芬里尔」的雪地犬，这是她从长久的冬眠中醒来后的第一个伙伴。\n在被探索装置发现后，芬里尔也随维达尔一同来到了深空之眼，与拘谨的维达尔不同，它反而是最快与同伴们热络起来的。不过这样热情的芬里尔也有一个忌讳，那便是不允许别人摸它的头，这点只有维达尔和利维坦是例外。\n作为主人的维达尔尚可理解，但芬里尔和利维坦如此亲昵的原因却难以追寻。大家不禁猜测，难道真的如利维坦所说，她和维达尔与芬里尔是早就在极地共同生活的关系，可这样一来，维达尔的记忆内容就又无法解释了……",
		heart_chain1 = "维达尔苏醒在一个遍地都是冰川的原质区，在那个被称为极地的地方，她自小便靠着狩猎动物来养活自己。\n她像一个穿梭在雪原的猎人一样独来独往，白天藏在雪堆里等待猎物，晚上呆在简易搭建的冰屋里入眠。这样的生活持续多年，直到一艘破冰船的到来改变了一切。\n某支科考队驾驶着破冰船「雪列格号」来到极地冰圈，他们一路上凿破厚积的冰路，抵抗凛冽的风暴，预测会忽然从风雪中出现的冰山，这些困难都没有对他们造成影响，但偏偏在抵达了目的地时，无坚不摧的核动力破冰船却接连发出警报……\n船体出现奇怪破洞，螺旋浆翼遭到破坏，部分船舱的舱门被在夜间摧毁，众人猜测可能有一队训练有素的北极熊起跳将近20米的高度潜入了船舱内。他们开了一个短会，接着不论调查员还是船员都提起一杆老式猎枪巡逻全船。最终，科考队队长克林·博格在动力室内发现了这一切的罪魁祸首——一个手持利斧，正准备砸破动力室大门的少女。",
