		cv_zh = "蟲蟲",
		cv_ja = "诹访彩花",
		heart_chain2 = "驾驶「雪列格号」的极地科考队是维达尔见到的第一批人类，那时她正准备使用大斧将这个闯入自己领地的「怪物」——科考破冰船大卸八块。\n调查员们过了好久才接受一个十多岁的少女在极地独自生活了数年的事实，而她除了自己的名字外什么也说不出来。在科考队长博格的号召下，调查员们开始每天轮流教授她基础的人文知识，用科考队的制服替换了那件兽皮外衣，将她那些充满自然野性的习惯一一改造，总算让维达尔看上去不再像一只长着人类外貌的极地雪狼。\n为期一年的极地科考任务结束了，科考队们完成了预定目标，在征得维达尔同意后，他们本打算带着维达尔乘坐雪列格号返回城市。然而在启程之夜，维达尔的修正者意识突然觉醒，她在嗅到了潜藏在极地冰川中的视骸后独自跳海返回，不然从冰川中复苏的视骸会将雪列格号拖入无底的冰渊。她从冰封中取出那柄被科考队们藏起的冰斧「寒霜之牙」，像过去和冰原的野兽们交锋一样，直面了迎来的视骸们。\n这场持续了一天一夜的战斗以维达尔的胜利告终，但她也同时失去了离开这片冰原的机会，雪列格号并没有返航找她。长夜破晓，艰难取胜的维达尔筋疲力尽地倒在冰原上，陷入了漫长的冬眠之中。",
		organization = "深空之眼",
		heart_chain4 = "来到艾因索菲后的维达尔，初期并不能适应这里的生活，也因此闹出过很多的事故——比如在餐厅用餐忘了付钱，不明白什么是交通规则，和公园的动物打起来之类的。\n不过在同事的帮助下，现今的她已经完全适应了现代社会的生活方式，也能正常地操作大部分电子设备了。不过唯独有一点，当维达尔看着总部里相处融洽的众人时，向来独处的她却不知道该如何加入。她不明白为什么人总要集体行动，为什么要因为无意义的事大笑，即便去网络上搜寻这个问题，也没有一个好的答案可以解决她的困惑。\n不知如何与人相处的维达尔，会在同伴试图与她亲近时感到迷茫与不知所措；也不知道那个总是自顾自地称呼自己为「师父」的女孩，心里到底在想着什么。看起来，这份拘谨和困惑还需要更多的时间，或者一个合适的机会去化解。",
		heart_chain3 = "四年后，在深空之眼的某次观测中，维达尔的微弱信号被弥弥尔的神力探测系统捕捉到，并派遣了专门的搜寻部队「弥弥尔雪橇机器人」前往。\n被带离极地的维达尔的身体出现了奇怪的现象——会对冰冷的事物产生本能的依赖，如果体感温度超过26℃便会完全陷入虚弱状态，几乎无法做任何事。\n为了解决这个问题，隐科组为其制作了特殊的控温芯片植入体内，使得维达尔的体温一直保持在较低的区间。可即使这样也不是绝对安全的，神力的过度使用会使得控温芯片的调节失灵，令维达尔出现升温和冒汗的症状，所以在战斗中需要时刻关注她的体温变化。",
