		id = 1081,
		heart_chain5 = "当一个人真的将传说变成了传奇，又当如何？丝卡蒂第一次抵达边缘海域后，就在思考这样的问题。\n当她驾驶着雪晶二号冲出风暴，跨越洋流后，迎接她的竟然是一片如同镜面一般的海面，仿佛夙愿得偿后突然平静的内心。承载着无数星辰的夜幕慢慢降临，与这镜面般的海面融为一体，告诉她这里就是冒险的终点，前方就是艾因索菲传说中的「边界」……\n然而丝卡蒂并没有发呆太久，她发动引擎，驾驶雪晶二号掉头，再次向风暴驶去。丝卡蒂明白，对于刚刚思考的那个问题，她很早之前就已经得到了答案。",
		heart_chain1 = "丝卡蒂很小的时候，就开始听父亲讲有关大海的故事。在父亲的讲述下，东面那片一望无垠的大海变成了一个绚烂缤纷的舞台。勇敢的航海人在这里登船，开始演绎一个又一个传奇。据说，有一位船长曾经看到过这片大海的边界；据说，还有一位船长曾经闯入骇人的风暴却又奇迹生还；据说，有的船只曾经被诡异的水怪袭击过……\n丝卡蒂听得入迷了，真的以为大海上每天都在发生这种事，还兴奋地向同学分享。然而那些早已变成小大人的同学却嘲笑丝卡蒂无知，分不清传说和现实。丝卡蒂再次回到海边，一言不发地看海。这时父亲就像往常那样再次来到丝卡蒂身边，并说出了改变她一生的话：「传说一旦被证实，就会成为传奇。而这两者之间的区别，仅仅是一个敢于出海的人。」",
		plot_tip = "没有忘记我们约定的事情吧！趁着还有一点时间，我们一起去完成心愿吧~",
		cv_ko = "김예림",
		like = "出海航行、船",
		super_plot_tip = "管理员，这次的任务，我们又可以同行了呢！",
		plot_tip_picture = "1081",
		cv_en = "Kayli Mills",
		age_en = "",
		cv_zh = "潘丹妮",
		cv_ja = "矢作纱友里",
		heart_chain2 = "当丝卡蒂说她要建造一艘属于她自己的船，并像那些传说人物一样出海时，没人觉得她是认真的，除了她的父亲。或许是为自己的技艺可以得到传承而欣慰，也可能是不想破坏自己曾经向丝卡蒂描述过的那些传说，父亲力排众议，全力支持丝卡蒂利用课余时间造船的计划。而后，父亲的同事每天都能看到丝卡蒂在造船厂的废料处理区翻找和收集，仿佛真的要用一堆边角料造出一艘船来。丝卡蒂开始听到嘲笑和议论，但她并不在乎。她继续收集废弃部件，阅读从父亲那里借来的书籍，尝试自己画图纸，笨拙但又大胆地学习使用焊枪……\n最终，所有嘲笑都随着一艘小型快艇的逐渐成型而消失了——丝卡蒂在造船这件事上展现出了惊人的天赋，竟然真的只花了两个月的时间就造出了一艘船。丝卡蒂将那艘船命名为「雪晶一号」，虽然这艘船还很简陋，但丝卡蒂已经开始在脑海中编织这艘船的传奇故事。",
		organization = "深空之眼",
		heart_chain4 = "深空之眼安排丝卡蒂担任外勤海事专员，既是考虑到丝卡蒂的天赋，也是出于无奈——丝卡蒂在办公室里半分钟都坐不下去。一不留神，办公桌就被她锯下一角来拼凑船只模型。再一不留神，办公用的纸张就被叠成纸帆船，放到观赏鱼缸里航行。但有时，丝卡蒂也会安静下来，坐在落地窗前望着远处的海面。而这样的情景，经常被休看在眼里。\n某一天，在丝卡蒂结束了又一次的胡闹后，一脸严肃的休来到她跟前，宣称她被「罚」去负责海域外勤工作，并获准使用一笔资金和一个私人港口来建造一艘调查船。休永远都忘不了那天丝卡蒂回敬给她的拥抱，好在丝卡蒂在休窒息前就兴奋地冲出了办公室。",
		heart_chain3 = "「再见了，雪晶一号……」\n「但是，我们证明了传说中的海怪真的存在，不是吗？」\n短暂地哀悼后，丝卡蒂的心中再次燃起了强烈的渴望——将这次经历带回去，讲给别人听，将传说变成传奇！\n——彼时丝卡蒂执意进行的初次航海刚刚惨烈收场，一大群来源不明的怪物袭击了她的雪晶一号。心爱的船变成残骸，自己也跌落水中，然而即便身处如此绝境，丝卡蒂也拒绝让绝望占据自己的心扉。「我一定要回去，把这个传奇讲给他们听！」或许是为了回应这个愿望，丝卡蒂的神力终于觉醒，从她体内溢出的寒冷冻结了海水，也驱散了那些怪物。\n虽然不久后有一位名叫休的人专门找到丝卡蒂，用一套包含「修正者」、「视骸」等诸多新奇词汇的理论，科学而又严谨地解释了当时发生的事。但丝卡蒂还是坚信，那是她创造的第一段传奇。",
