	[1083] = {
		birthday = "12月7日",
		height = "173cm",
		name = "埃克什瓦",
		id = 1083,
		heart_chain5 = "在被深空之眼找到前，埃什从未遇到过视骸和源层裂缝，这是她没能认知自己修正者身份的重要原因。\n但学习了修正者理论知识，开始辨认视骸种类时，埃什发现了一件事。\n或许，她曾经见到过一次视骸，一只伪装成人类的侵蚀种。\n彼时埃什连冒充的治安官也不是，虽然戴着一顶牛仔帽，但本质只是个拿钱办事的佣兵。她会救人，也会抢劫，她做什么不取决于道德，也不取决于良心，更与修正者守护的职责毫无关系，一切都只看委托人给了多少钱。\n有次埃什完成委托，带着抢来的货物准备甩掉追兵离开，忽然看到一个奇怪的人扑向身后的敌人。埃什回身，随手来了几枪，击毙了那个突如其来的袭击者，然后丢下目瞪口呆的敌人扬长而去。\n如果问埃什当初为什么这么做，她自己也没有答案。那行为没有任何理由，也没经过任何可供回味的思考，她只是单纯地抬起枪管，救下了自己的敌人。\n这种行为是出于一种本能吗？是作为修正者的本能，还是作为埃什的本能？\n顶着压力做出决定重返长水镇的那一天，埃什考虑了很多事情，但并不包括这件。这件事情早被淹没在许许多多不同的过往里，看不出什么特殊。\n但在已经认知到自身守护职责的如今，埃什觉得这件事就像是命运偷偷埋下的伏笔。\n重要的抉择早已在平凡的细节中昭示，过往的纷繁中隐藏着未来的道路。\n即使出身于迷茫，即使经历过混乱，最终，埃什仍然成为了一名承担起使命的守护者。",
		heart_chain1 = "在艾因索菲荒原的部分小镇上，曾经流传过一个关于「真正的牛仔」的传说。\n常年戴着牛仔帽的女人出身神秘，行为成谜。她可能会出现在小镇的任何一个角落，提着她的枪。如果你有委托，可以带着钱找到她；如果你没别的事，那就千万不要去惹她。牛仔从不吝啬于拔出她的枪，而别人能看到的，只有牛仔行走在风沙里的背影。\n艾因索菲荒原的风见证过无数的故事和传说。风拂过低垂的灌木，拂过山地上的刺槐，把故事又带回了它的主角身边。\n埃克什瓦在吧台旁听到这个传说时，微笑着给自己倒了一大杯珍酿。\n出身神秘，是因为她睁开眼睛时没有任何记忆，只有一具二十多岁的年轻身体，还有这个叫「埃克什瓦」的名字；行为成谜，是因为她没有归处，也不知道去处，只能像风滚草一样随性，任凭自己被风带到哪里。\n睁开眼睛的那一天，没有任何人告诉埃什她应该去哪里。她的眼前和心中一片空白，身边只有风沙，只有荒原。她观察周围的环境，捡走一件披风，顺走一个钱包，跟随他人找到人群的聚集处，看到吧台上方正在播一部热门的荒原剧。津津有味地看着荒原剧的情节，顺便把名字改成了更帅气的简称「埃什」，她开始适应荒原的生活。\n埃什很快发现，她头脑聪明，轻松能够看破伙计的把戏；她身手灵活，徒手能撂倒三个不使用武器的壮汉；她天赋异禀，第一次接触枪就能射中十米外的靶子，练习之后更是百发百中。她优秀的身手很快吸引到了其他人的注意，逐渐开始有人把事情委托给埃什，埃什没什么强烈的道德观念，除了喜欢模仿荒原片主角帅气的样子，也没什么特别的喜恶，对各种委托来者不拒，一边养成了无法无天的性格，一边也懂得了金钱的美妙。\n在人们口中，牛仔从剧目走入荒原；但实际上，埃什也只是一个普通的荒原人。荒原中的人追逐金钱、享受生活，埃什也追逐金钱，享受生活。\n埃什成为了一粒和其他岩石并没有什么不同的岩石，成为了荒原的一部分。",
		plot_tip = "",
		cv_ko = "장예나",
		like = "写日记",
		super_plot_tip = "",
		plot_tip_picture = "1083",
		cv_en = "Jayme Mantos",
		age_en = "",
		cv_zh = "菊花花",
		cv_ja = "巽悠衣子",
		heart_chain2 = "在水上列车北线建立的许多年之后，荒原上还流传着那些故事：破产的农场主不愿意进入城市，戴上荒原剧里的牛仔帽，用枪声声嘶力竭地反抗着命运：黑帮和流民涌入绿洲中的小城，坎扬维尔在一夜之间崛起，子弹和血腥连缀成一次又一次没有尽头的争斗。\n但如今仍在的，也只有故事。坎扬维尔已经是光鲜奢靡的销金窟，荒原小镇们同样回归了平静的生活。\n长水镇便是无数普通的荒原小镇之一。这个普通的名字后来成为了埃什珍贵的记忆。\n委托带来的收入虽然足以温饱，但极不稳定，埃什寻找着赚更多钱的办法。在一次和本地小姑娘伊兹尔、以及还未上任便已死去的治安官的偶遇后，她将目光投向了长水镇。带着伊兹尔和擦去血污的银星，埃什成为了镇子的治安官。\n长水镇是启城-核心城列车北线的站点，虽然不是个大站，也有些往来的商贩。埃什一边拿着镇长给的工资，一边调解纠纷，对抗劫匪，收取点保护费用，不仅有了更加稳定的金钱来源，还收获了荣誉，颇受镇民们欢迎。\n没有工作的时候，埃什喜欢在镇子里闲逛，美其名曰像个真正的治安官一样巡逻。她通常从居住区出发，镇里的老太太们都喜欢这个年轻又俊俏的牛仔，会送给她刚烤的面包，邀请她来屋里喝一杯手磨的咖啡。接着她路过餐吧和珍酿馆，徘徊在店门口的醉鬼嬉笑着摘下帽子向她打招呼。继续走到车站旁的货物装卸区，被她照顾过的商贩们会热情地围上来给她递各种小礼物。\n等埃什摆脱了所有人，时间已经是傍晚。她沿着列车远去的方向慢慢向前，巨大的夕阳坠落在荒原的地平线上，猩红的日光照着她和她身后的长水镇，好像昭示着某种命运的结局。\n长水镇之类的小镇已经步入暮年，镇里几乎没有什么年轻人，农业生产为主的经济结构也看不到未来。镇民们想通过吸引游客的方式拯救小镇，埃什虽然配合，心里也和伊兹尔一样，盘算着有没有其他更赚钱的法子。也许某一日，她就会离开这里……\n悠闲的日子总有尽头，但那时候的埃什只是停下脚步，转身慢慢地走回去。",
		organization = "深空之眼",
		heart_chain4 = "在荒原时，埃什对荒原剧和牛仔的热衷还不算奇怪；但到了核心城，这种特别的喜好就有些太过显眼了。\n毕竟在人人衣着精致、西装革履、脚步匆匆为繁忙工作奔走的大街上，一个戴着牛仔帽、背着披风、行动浮夸的家伙让人很难不多看几眼。\n在深空之眼也是如此。\n埃什刚刚加入深空之眼的时候，被塞尔凯特安排去参加新人修正者的理论补习班。补习班里的其他人大多是些缺乏社会经验的年幼孩子，看到这么一位帅气的牛仔提着枪微笑不言地坐在最后一排，顿时惊呼一片，一整天都在探头探脑。课后塞尔凯特敲了敲埃什的桌面，让她解决这个问题。埃什满口答应，说自己已经想到了好点子，结果第二天根本没来教室。\n塞尔凯特二度警告，于是这次埃什又有了新的好点子。她预支了第一个月的工资，买了十几顶同样帅气的牛仔帽。这次孩子们不用探头探脑了，他们直接一跃而起，闯出教室，开始了一次临时起意的牛仔主题大游行。他们穿过走廊和休息室，留下荒原风格的贴纸，差点就闯入隐科组的试验场一起去见识各种新式武器。好在道路的尽头是抱臂微笑着的塞尔凯特，无情地让每个人见识了违反课堂纪律的后果。\n随着时日渐长，众人逐渐对埃什的装束见怪不怪，认同这只是个特别些的爱好。偶有对牛仔文化好奇的人来询问相关的知识，埃什总会热情接待。于是这人将被迫连看五部荒原剧录影精选，接着来到训练场练习牛仔的拿枪和出场姿势练到手臂抽筋，最后参观埃什的私人荒原剧周边收藏馆，听她滔滔不绝地介绍每一件藏品的来历。大多数被好奇心害死的修正者都会半途而废，不过也有人坚持到了最后，顺便问了一个问题：埃什到底为什么这么狂热地喜欢牛仔？\n收到这个问题的埃什自然联想起自己刚刚睁开眼睛，第一次跟随人群走进珍酿馆，看到吧台上方播放着荒原剧的时刻。在几声枪声之后，剧中的牛仔俯身凝视着自己的敌人，扯下挂在胸前的口琴，塞进了敌人的嘴里，而珍酿馆中一片屏息。黄沙笼罩着两人，牛仔的眼中写满了那时的埃什看不懂的东西。埃什于是产生了一种朦胧但强烈的欲望，想要像剧中的主角一样，拥有一双眼睛就能装下，但又多得数不清的东西。\n她选择的不只是一种爱好，也是想要成为什么的道路。",
		heart_chain3 = "在最开始，埃什真的相信自己同荒原上的其他人并没有什么不同。\n她只是失去了记忆，她只是身手好一些。这样的身世不多见，但在混乱的艾因索菲荒原，也称不上离奇。偶尔脑袋里会跳出「修正」、「守护」之类的破碎词语，她也并不在意，毕竟她的梦里也会每天上演十出不同的荒原剧。\n她不在乎过去，无所谓将来，也从不去想自己是谁。她关心的只有今天赚了多少钱，只有自己登场时牛仔帽的角度是否如同荒原剧里一般帅气。\n直到某一天，埃什普普通通地在居所醒来，发现手边出现了一柄枪。\n那是一柄极为帅气的枪，线条流畅，机械精巧，金属反射着微冷的光，炫酷到不该出现在真正的荒原上，而该出现在荒原剧明星手中。埃什盯着手边的东西，没有一刻怀疑过这是恶作剧或者威胁，她只是顺从仿佛刻在自己身体里的惯性，伸手握住那柄枪，感受着一种奇怪的力量涌动在自己的身体内。同时到来的，是一种压在心口的，名为命运的预兆。\n埃什很快发现，她视力变得更好，身体反应灵活得不像人类，枪的威力也极为强大。她积累的常识还不够多，但足以明白，这绝不是该出现在一个正常人类身上的事情。\n「我是谁？」\n「我什么而诞生？为什么诞生成如此摸样？我和别人有什么不同？」\n「我应该去做什么特别的事、成为什么特别的人吗？」\n埃什提问，但回答她的只有荒原的风沙和夕阳。\n在一年之后，被管理员带回深空之眼的埃什会学习到修正者的基础知识。她将明白，每个修正者都是这样一无所有地突然出现在世界上，而自己处于不完全觉醒的状态，才会懵懂地不知使命与职责。\n但当时的埃什并不能理解这些。\n风沙和夕阳不会告诉她答案，手中的枪和脑袋中词句也不会。埃什便把飞散的心从去往不知何方的风里抓回来，裹住沉甸甸的疑问，放回胸口，做出了一个日后的自己也会认同的结论：\n无论未来寻找到什么样的道路，当下感受到的自己，便是真正的埃什。",
