		name = "薇儿丹蒂",
		id = 1084,
		heart_chain5 = "在医院遇到的这位奇妙的姐姐以后，薇儿丹蒂从她那里听来了许多外面的事情——那都是她从来没有经历过的，所有的一切对她来说都有无比的吸引力。塔琳娜总会看着她那双充满期盼的眼睛，然后温柔地抚摸着薇儿丹蒂的头对她说：等什么时候两人能出院了，就带她去看看外面世界的样子。\n但这个愿望最终却没能实现，塔琳娜还是因为病症去世了。\n在最后的时间里她和薇儿丹蒂定下了一个约定：不论发生什么，都不要轻易放弃，要积极地活下去。\n或许是受体质的影响，后来薇儿丹蒂的身体居然意外的痊愈了，而后她也被塔琳娜的父母收养，慢慢过上了正常人的生活。\n但她不曾忘记，这个与重要之人的约定，现在也在试图把这份积极，传递给身边的人。\n「被人类所拯救，被人类所抚养……所以即便发现自己是修正者后，我也不觉得自己和一般人有什么不同。」\n十七岁那年的薇儿丹蒂觉醒了修正者意识，她明白了自己维护文明、消灭视骸的使命，恰好此时深空之眼发来了邀请。即便很不舍得养父母，薇儿丹蒂还是以上大学为名离开了自己长大的城市，前往修正者大本营所在的艾因索菲核心城。",
		heart_chain1 = "对于后天觉醒而被招入深空之眼的修正者来说，突然脱离日常生活后面对即将到来的战斗，虽然是记忆中的职责所在，但难免都会有些迷惘甚至害怕。\n不过这条定律似乎并不能作用在薇儿丹蒂身上，应该说，她似乎并不存在精力不足的情况。即便是刚加入新人小队时，也总是展现着强大的活力和热情。\n「想要用这份力量守护世界、守护喜爱的人们，因此才更应该努力！」\n用她自己的话来说，自己的乐观坚强是从重要之人身上学到的，现在也想要把这份积极的态度继续传递下去。",
		plot_tip = "管理员，你醒了？你还记得我吗？",
		cv_ko = "여민정",
		like = "吃烤肉，哼小曲",
		super_plot_tip = "管理员，听说凯丽姐想要我们去拍宣传片，你有时间吗？",
		plot_tip_picture = "1084",
		cv_en = "Emma Ballantine",
		age_en = "",
		cv_zh = "牛奶君",
		cv_ja = "矢野妃菜喜",
		heart_chain2 = "对于成为修正者这件事，薇儿丹蒂似乎没有什么太多的自觉。换句话说，她还是一直把自己当作「普通人类」充实地生活着，像是随处可见的同龄人一般上学、打工，即便觉醒成为了修正者，向往有趣生活的心情也不会减少。\n而在这么多有趣的事情当中，美食算是不可或缺的一环。肉食主义者薇儿丹蒂，在尝试过各种各样的烤肉料理后，做出了「烤肉就是人生啊！」这样的纯粹发言。曾经也有为了品尝到最著名的牛肉料理，选择跑到很远的地方却迷路的经历。意外的也很擅长烘焙和烧烤料理的制作，不过那是经过多少次失败磨炼出的技艺，这件事或许只有她的队友比较清楚了。",
		organization = "深空之眼",
		heart_chain4 = "那场意外事故后，薇儿丹蒂的身体机能受到了严重的破坏，虽然没有直接丧命，但身体出现了很多在当时的人类医学角度看来难以治愈的症状。虽然及时接受了治疗，但心脏功能却在不受控制的日益衰竭，不管服用什么药物都收效甚微。被告知只有数月时间的薇儿丹蒂在住院病房里静静地等待着死亡的到来。\n一周后，一位名为塔琳娜的少女转入病房，她比薇儿丹蒂年长几岁，同样是身患重症，塔琳娜却和薇儿丹蒂有着截然不同的性格。她出生在一个普通但幸福的家庭，父母因为不想放弃而将塔琳娜送至该机构治疗，或许是天性使然，又或是不想让他人担心，塔琳娜一次也没有因病症消极过，她对谁都展露笑容，甚至比许多正常人还要开朗。薇儿丹蒂一度怀疑她是否真的是绝症病人，直到一天她看到塔琳娜病症发作时的模样，黑色的诡异斑纹蔓延上皮肤，仿佛在将塔琳娜身体撕裂般地令她不断哀嚎。\n「你看到了啊……对不起……是不是吓到你了？」\n擦拭着因剧痛而渗满额头的汗珠，塔琳娜只是对薇儿丹蒂露出无奈的苦笑，仿佛这样瘆人的画面对她早已是家常便饭。\n与塔琳娜相处的半年是薇儿丹蒂一生中最奇妙的时光，她第一次接触到福利院以外的人，明白了这个世界上的人类是各种各样的。被这个奇妙的姐姐所感染，薇儿丹蒂渐渐对世界的看法有所改变，塔琳娜乐观积极的性格也在无形当中影响着薇儿丹蒂。",
		heart_chain3 = "大部分人，包括深空之眼的朋友们在内，都对薇儿丹蒂的年幼时候的经历知之甚少。只知道她曾经生过一场大病，遗失了一部分幼时的记忆。所以很少有人能想到，现在开朗乐观的薇儿丹蒂小时候其实相当的寡言少语，怯懦胆小，福利院的生活给她的童年蒙上了一层阴影。\n实际上，曾经收养薇儿丹蒂的福利院因为内部的管理不当，导致许多孩子在院内都有被黑工欺凌的经历。从小在这样阴暗环境中长大的薇儿丹蒂逐渐失去了对他人的信任，选择把自己封闭起来。\n直到那年福利院意外事故的发生，成为了薇儿丹蒂人生的转折点。",
