		name = "诗蔻蒂",
		id = 1085,
		heart_chain5 = "最初的见面只是个偶然，那个人出手帮助了险遭诈骗的诗蔻蒂，望着眼前仗义出手的好心人，诗蔻蒂不知为何总觉得心中流过一股暖意。\n虽然说不上原因，但她总想再见对方一面——而这个愿望很快就实现了。\n两人在弥楼衍再度相遇，这位被叫做管理员的人还是那样亲切，平日里总是有些怕生的诗蔻蒂却很快就和对方混熟。\n他们去了各种地方游玩，甚至去到了加尔的游乐园，那是诗蔻蒂常常会梦见的地方，看着眼前的人，诗蔻蒂甚至有了梦境照进现实的错觉。\n但好景不长，诗蔻蒂无意间接触到了往世书的密钥，陷入时间循环之中，无论如何也无法逃离。\n在她打算任由盖亚抹除自己以终结循环的过程中，管理员找回了她的存在，并与她逃离了这个循环。\n听着管理员那诚挚的话语，与不知为何有些熟悉的面容，就算没有了过往的记忆，诗蔻蒂也能够确信——\n「我终于找到你了……小昙！」",
		heart_chain1 = "苏醒之后，第一个被叩问的问题便是——「你是谁？」，然而面对这个简单的问题，没有记忆的诗蔻蒂却根本无法给出答案，周围的人亦然。\n「人造修正者」、「0705」……这些传入耳内的词汇似乎代表着她的身份，又似乎什么也不是，她唯一记得的东西便是自己的名字。\n事后她从他人口中了解到，修正者是特殊的存在，肩负着对抗视骸这种「坏东西」的使命。\n那自己呢？自己又该去做些什么，又该向着怎样的未来进发呢？即便向旁人发问，这个问题依旧不会得到答案。\n她只能紧紧揪住自己记忆中剩下的那唯一的东西，那是一个叫做「小昙」的名字。\n虽然已经记不得对方的长相，甚至也记不得与对方共度的任何回忆，但她却本能地感觉到，那是对自己来说非常重要的人。\n这也成了她的第一个目标——「找到小昙」。",
		plot_tip = "和小昙来到深空之眼，还有很多好奇的事，很多未知的事，想要和你一起探索。",
		cv_ko = "이보희",
		like = "去游乐园玩",
		super_plot_tip = "",
		plot_tip_picture = "1085",
		cv_en = "Risa Mei",
		age_en = "",
		cv_zh = "江月",
		cv_ja = "大桥步夕",
		heart_chain2 = "对于诗蔻蒂来说，身边的一切都是新奇的，飞过的蝴蝶、枝头的鸟儿、不断变换的终端荧幕……这个世界中的一切都是她前所未见的。\n最开始，她只是通过托特送给自己的书籍来试着了解这一切，但自从来到加尔之后，她却发现一切都似乎和自己在书中看见的不一样。\n吵闹的人群，飞驰的车辆，对于初到加尔的诗蔻蒂来说，加尔的街道只会让人感觉有些害怕，但随着待的时间越来越长，她逐渐从这幅景象中感受到了某种「不一样的东西」。\n她也说不清这种「不一样的东西」究竟是什么，不过每当自己心情低落的时候，看着这幅景象就总会觉得心里暖暖的。\n随后，她找到洛肯，道出了自己的疑惑。\n「你问这种「不一样的东西」是什么？啊……解释起来很麻烦，简单来说，这叫『生命力』。」\n在那之后，洛肯又讲了不少关于其他原质区的事情，在每个原质区生活的人不一样，所能看见的风景也不一样。\n虽然洛肯的话，诗蔻蒂并没能全部听懂，但一个愿望却在她的心中扎根发芽——她想去看看这个世界，见识那些不一样的风景。",
		organization = "深空之眼",
		heart_chain4 = "没事的时候，诗蔻蒂很喜欢睡觉，因为梦里有那些熟悉的东西，她喜欢的东西。\n梦里的世界很广阔，小昙会陪着自己一起玩，会带着自己去到很远很远的地方。\n有时梦里的小昙看起来像是一只白色的鸟，有时看着像是一只兔子，和小昙在一起总是很快乐。\n但梦总有醒来的时候，每当梦醒之时，曾经努力记下的样貌也会随之烟消云散。\n越是做梦，醒来的时候就越是感觉怅然若失……\n又一次从梦中醒来之后，诗蔻蒂并没有再试图睡个回笼觉，而是默默望着熟悉的天花板看了许久。\n比起这些一摸就散的梦境，她更想要真实的东西，不管那是可以触碰的温度，还是可以被铭记的面容都好，她想要在现实中见到小昙。\n为此，自己不能再停步不前了，这样想着，诗蔻蒂向外走去。",
		heart_chain3 = "对诗蔻蒂来说，在加尔的每一天都是从面包和牛奶开始的。大部分时候，这是作为监护人的洛肯为她送来的早餐，有些时候则会变成伊里伽尔。\n由于她的身份，诗蔻蒂大部分时间都待在洛肯的店里，或许是为了不让她过得太无聊，洛肯给她准备了各式各样的书籍，还有用来玩游戏的终端。\n诗蔻蒂尚不知晓别的生活方式，也并未对这种生活有多少不满，外面是吵闹的街道，而店里面则是书籍与网络。\n但随着她的愿望逐渐萌芽，洛肯也看出来，如果想要探索外面的世界，加尔不是个最合适的选择，诗蔻蒂和自己不一样，加尔不是她应该待的地方。\n在那之后，诗蔻蒂每天的日程中增加了新项目，战斗技巧的训练与修正者和视骸知识的学习。\n「总有一天，你会找到那个叫小昙的人。到时候，我教你的这些东西都能派得上用场的。」\n虽然诗蔻蒂听得一知半解，但从洛肯认真的眼神里，她本能地感觉到这是某种非常重要的事情。\n「嗯，我知道了。」\n虽然不知道未来究竟会如何，但她还是决定，要好好记住这些事情。",
