	[1089] = {
		birthday = "10月15日",
		height = "170cm",
		name = "帕尔瓦蒂",
		id = 1089,
		heart_chain5 = "在贫民窟时，帕尔瓦蒂从未奢求过「理想」这种东西。能吃饱，能穿暖，能活着便构成了她的愿望。但她并不甘心于这种苟延残喘的生活，她想要改变这世界设定的规则。\n「人活着，总要向往些什么。」带着这样的想法，帕尔瓦蒂才终于开始寻找自己的愿望。终于，帕尔瓦蒂如愿以偿地建立了帮派，带领着一部分人试图从贫民窟的规则中走出。\n但突如其来的灾难毁掉了这一切，帕尔瓦蒂从未想过，失去一切的代价之重已经到达了让她难以承受的地步。甚至每每回想起来，都会让她感到窒息般的疼痛，强烈的情绪与无法触及的愿望逐渐让她消沉下去。她并非第一次面对死亡和失去一切，但在那个雨夜，帕尔瓦蒂才真正理解了「向往」二字。她想要挽回自己失去的一切，唯有奇迹才能创造奇迹。所以当梵天带着那个近乎不可能的计划出现在帕尔瓦蒂面前的时候，她毫不犹豫地选择了加入。\n帕尔瓦蒂一直都知道自己并无特殊，她只是一个徘徊在过去，久久不愿离开的可怜人。",
		heart_chain1 = "帕尔瓦蒂，作为弥楼衍的二把手，她似乎整日都在忙东忙西，顶着浓重的黑眼圈四处奔走是她的常态。由于她给人的第一印象实在太过惊悚，以至于「别死我屋里」的玩笑也一度在弥楼衍流传开来。但若是经过观察便能发现，那黑眼圈不过是帕尔瓦蒂自己画的伪装。她要么在看材料时发呆打盹，要么是在去工作时偷偷溜进厕所玩失踪，要么就干脆把工作分包安排给其他人。\n总而言之，她似乎很是抗拒自己的各种工作。但弥楼衍的众人从未有任何怨言。所有人都知道，帕瓦的能力并不止于此，她有更重要的事情要做。她几乎不会去做日常的事务性工作，只有当弥楼衍遇到上上下下无法解决的问题时，帕尔瓦蒂才会勉为其难地出手。随着时间的推移，弥楼衍之中流传的传说已经变成了：「不论多严重的问题，只要帕尔瓦蒂在就能搞定一切；如果连帕尔瓦蒂都搞不定，那肯定也轮不到你来担心。」",
		plot_tip = "",
		cv_ko = "이현진",
		like = "打牌等简单且低成本的娱乐",
		super_plot_tip = "",
		plot_tip_picture = "1089",
		cv_en = "Ellise Chappell",
		age_en = "",
		cv_zh = "唐雅菁",
		cv_ja = "远藤绫",
		heart_chain2 = "帕尔瓦蒂出身于贫民窟，据她所言在很长一段时间里，她并未见过真正的蓝天，仿佛那肮脏的一亩三分地就是她的全部世界。大多数贫民窟的人早已失去希望，光是活着就让他们拼尽全力，她困惑于普通人类的安于现状，又感慨高墙之外光鲜亮丽者的蠢笨，却对此无可奈何。对于当时的帕尔瓦蒂来说，那根本算不上生活，只能说是活着，不过是由果腹和恐惧构成的活着。她也成为了埋葬在泥潭中的金子，无处放射她的光亮。\n而这一切都在她决定建立帮派时迎来转机，并非是想成为什么善人，帕瓦只是觉得或许自己可以带着这些人走一段路，至少让他们不用再为生存发愁。想在贫民窟拥有稳定的食物来源并不容易，而帕尔瓦蒂仅仅靠着两份协议就轻易解决了这个问题。在她看来，万般难事都有解决的方法，只是极少有人能够全面地看待问题以及问题之外的部分。\n事实证明，帕尔瓦蒂的智慧确实帮助曼陀罗帮——这支由一无所有的贫民组成的帮派走到了从未想象过的高度。",
		organization = "弥楼衍",
		heart_chain4 = "关于这一点，帕尔瓦蒂似乎从不与人提及，这是在多年前习惯的衍生。在夏什瓦特的贫民窟中，这些小小的零食是比货币更有价值的硬通货。帕尔瓦蒂完全能够理解，虽然时间已经过去许久，但那时发生的一切依旧历历在目。当帕尔瓦蒂第一次将巧克力棒塞进嘴里时，她像饿了许久的仓鼠一样将那些零食一扫而光。也自那天起，她爱上了巧克力棒微苦回甘的味道。不知道是确实合帕尔瓦蒂的口味，还是她真的从中品出了些生活的酸涩，像是吃下巧克力的原料一样。\n总之，你几乎能在弥楼衍的任何地方找到装着巧克力棒的盒子，而未经许可偷拿的行为，是帕尔瓦蒂的「绝对逆鳞」。不过这并不代表她不愿分享，恰恰相反，当地福利院的孩子们每周都会收到匿名寄来的满满一箱巧克力棒，虽然本人很直接地否认了。\n或许对于她来说，这些巧克力口味的饼干棒就是她活着的证明，她将自己的人性寄托在小小的巧克力棒上，是逃避，亦是赎罪。",
		heart_chain3 = "帕尔瓦蒂刚见到梵天的时候，就见识到了她最为恐怖的一面。彼时的她早已经精疲力尽，只是凭着本能在求生，甚至忘记了自己最大的依赖。只是在灾祸面前，智慧显得如此渺小。就在几近放弃的瞬间，帕尔瓦蒂感到某种与自己「类似」的存在，但又与自己不同，她拥有远远超越自己的力量，其娇小身材与严肃的面容形成了强烈的反差。这是她第一次感受到了完全不同的强大，凌驾于一切的强大，单纯无比的强大。帕尔瓦蒂永远无法忘记那一天，那是她重新认识自己的一天。\n在日后的接触中，帕尔瓦蒂逐渐认同了梵天的神国计划，她也从神国计划中找寻到了生存的意义。对于帕尔瓦蒂来说，梵天的身上有着难以言说的熟悉感，虽然二人从未深入地聊过彼此的过去，但帕尔瓦蒂看得出来，二人似乎有着相似的悲哀。",
