	[1093] = {
		birthday = "2月21日",
		height = "167cm",
		name = "国常立",
		id = 1093,
		heart_chain5 = "对于刚进入深空之眼的后辈修正者来说，大多数人都对前辈帅气战斗的身姿有或多或少的憧憬。国常立的实力也确实是其中的佼佼者，然而当怀着仰慕之情的后辈拜访她的时候，她通常也会负起责任把这份憧憬彻底击碎。轻浮的语气加上随性的举止，对自己认为可爱的后辈甚至会频繁打趣，虽然在本人看来那不过是表达喜欢的一种方式，但这也导致国常立在新人之间风评不佳，但她本人似乎对此并不在意。\n因为曾经差点死去的经历，所以对国常立来说，现在的最重要的事就是在生活中寻找快乐，看到更多，经历更多——而逍遥自在度过的每一天，都算是她「赚到的」。\n「现在，来和姐姐喝一杯吧。」玻璃杯中，印照着她慵懒的目光。",
		heart_chain1 = "隶属于雉小队的修正者国常立，擅长利用类似潜行者的巧妙身法进行战斗，目前主要负责各类潜行，探查类的工作。然而平时的国常立也像是潜行者一样，大部分时候都是神出鬼没的，要是想找她只能选择去各大祭典碰碰运气。据说这也是她以前在笹波的习惯，总是趁着夜幕降临后，辗转在各大祭典间，逍遥生活。\n在她还是自由行动的修正者时，奥丁就认识她了，并且一度因为她强大的实力提出加入深空之眼的邀请。不过习惯了自由生活的国常立没有同意，倒是相同的爱好让这两人成了趣味相投的朋友。",
		plot_tip = "有机会的话，真想让管理员陪我逛逛祭典呢。看看烟花，打打木靶，有吃的喝的，还有姐姐我……别这么震惊嘛，开玩笑的~",
		cv_ko = "이현진",
		like = "逛祭典，捉弄后辈",
		super_plot_tip = "欸，姐姐的心思？管理员想知道的话，就靠近我一点吧~",
		plot_tip_picture = "1093",
		cv_en = "Akira Lee Watanabe",
		age_en = "",
		cv_zh = "牛奶君",
		cv_ja = "泽城美雪",
		heart_chain2 = "「嗯哼，你想知道姐姐的秘密吗？凑近一点就告诉你哦。」\n国常立让人印象深刻的一点，是额前长到盖住左眼的银白色刘海，甚至已经到了不得不担心这是否会影响视线的程度。不过本人似乎并不在意这一点，有人问起也只是故作神秘。不过从隐科组的记载里还是能多少了解到一些当年发生的事：\n国常立在某次讨伐笹波区视骸的过程中，因为对手的实力强大，大意受了重伤，被随后赶到的月读紧急带回了深空之眼抢救。面对国常立严重的伤势，医疗组的成员虽然勉强保住她的性命，但国常立却因此失去了自己的左眼。在奥丁的指示下，隐科组用一颗珍贵的核心晶体替国常立制作了一只义眼。那之后国常立就留长了头发，以遮盖起义眼的存在，不过得益于这颗义眼的特性，国常立的感知能力也增强到甚至可以不用睁眼就判断出对手的行动。\n也因为这次事件，国常立怀着对月读的感激之情答应了奥丁的邀请，并被安排加入了月读所在的雉小队。",
		organization = "深空之眼",
		heart_chain4 = "鲜有人知的一件事是：那次战斗中国常立受到的伤并没有根治，那只强大视骸的侵蚀力超出了可以清除的范畴，隐科组的手段只能够勉强将这股侵蚀力压制在可控的范围内。并且因为这种压制力无法长久维持，国常立需要定时服用抑制药，用以防止侵蚀力在体内的再度爆发导致身体组织被破坏。\n不过，由于尚没能解明那只视骸的真貌，也就无法根据它的侵蚀特性去调整药剂。想要抑止侵蚀就只能用更强的药力来压制，这导致抑制药在挽救国常立生命的同时也是攻伐之剂，药效的副作用会让国常立感到痛苦万分。为了不让小队成员担心，国常立每次都会躲起来偷偷地服药，这或许也属于是她不可言说的秘密之一。",
		heart_chain3 = "国常立对救过自己一命的月读暗自感激，也希望有机会能偿还这份恩情。加入雉小队后，有了更多共事时间的国常立敏锐地察觉到了月读的心事，但她并没有很快说破，而是在力所能及的范围内给予帮助。偶尔对月读的玩笑打趣总是让月读感到有点无奈，但实际上，这只是国常立希望她不要被自己的心情所困。\n不过小队中的另一人似乎对此颇有怨言，联想到国常立平时的轻浮举止，和刻板认真的丰前坊相处不来也是理所当然的。\n所以国常立每每讲起一些不正经的话语，总会立刻被一道「恶狠狠」的视线盯上。\n「嗨呀，原来丰前坊也在啊。」\n不过国常立似乎反而对此更加来了兴致。",
