		height = "148cm",
		name = "海拉",
		id = 1094,
		heart_chain5 = "海拉还是会时常想起过去与姐姐在一起的日子，即便生活的条件不怎么好，但温暖和幸福一直都充斥在那间小小的屋子里。只是现在姐姐真的已经离开了她，海拉心中期盼的那种幸福也更愈发显得遥不可及。\n幸运的是，似乎又有一个人能够让自己感受到许久不曾出现的温暖。再次定下约定的现在，似乎能够好好回头看看过去了。",
		heart_chain1 = "在海拉的修正者意识觉醒前，也曾经拥有一段身为人类的生活经历。尚还年幼的她被一户富裕人家所收养，在良好的家庭条件下度过了幸福的童年。\n但是美好的生活并没有持续太久，在女主人离世后，养父的性格大变并常常因为生活中的不如意而虐待海拉。一次次的事后忏悔和原谅后，海拉终于绝望了。她诉说了自己的遭遇，并期盼有人能秉持正义，帮助自己脱离这样痛苦的生活。",
		plot_tip = "管理员，那些我想要忘记……却又不想忘记的愿望，可以都说给你听吗？我的黑猫……会是你吗……",
		cv_ko = "김하영",
