		cv_zh = "李蝉妃",
		cv_ja = "田村由加莉",
		heart_chain2 = "但是正义没有如愿而来，反而是在偶然间，海拉听见了执法机构迫于养父势力而打算放弃起诉的谈话。不想再回到那个家的海拉只能独自逃出医院，在艾因索菲陷入无助的时候被好心的神父老弗雷收养。\n暂时得到了住所的海拉，也认识了同为被收养的姐姐薇娜。两人一起在神父的葬仪馆担任助手，这份特殊的经历让海拉见识到了人类生命的脆弱，也让她对情感有了新的理解。",
		organization = "深空之眼",
		heart_chain4 = "成为送葬者小队负责人的海拉，主要执行的是消灭伪装成人类的侵蚀种视骸的工作，这是份能让大部分修正者感到迷惘的差事。只有海拉毫不抱怨地完成了，消灭人类和视骸对她来说没有任何区别，她不会感到任何的悲伤或者喜悦，只是完成任务而已。",
		heart_chain3 = "然而作为葬仪人助手的日子却并没有持续很久，多舛的命运再次让海拉失去了容身之所，14岁那年的雨夜，海拉觉醒了修正者的力量。\n也是这时候，她明白了自己并不是人类的事实，并将它作为自己变得漠视人类情感的依据。觉醒了神力的海拉被深空之眼探测装置找到，虽然无意消灭视骸和拯救人类文明，但以此换来一个安稳的居所也并不让她反感。",
