	[1095] = {
		birthday = "1月26日",
		height = "162cm",
		name = "托特",
		id = 1095,
		heart_chain5 = "托特曾经在一位名为诺尔薇的神秘女性介绍下，以笔友身份结识了一名特殊的合作对象，即便是对托特来说，对方也是一个很奇妙的人。\n这位合作对象掌握着即便是在科尔盖任职的托特也未曾知晓的各种机密信息，对各类事情都有着独特的见解。\n一开始，双方的聊天仅仅止于事务性交流，但随着时间变迁，两人交流的内容也逐渐转变，从生活上的琐事到阅读上的感悟，两人也成为了真正意义上的笔友。\n富有智慧的同时却能保持谦逊，成熟老练但却从不虚伪，对于整日生活在算计与阴谋中的托特来说，这个人是她少有愿意信任的人。\n但世事难料，这位笔友在与托特的一次会面后被卷入视骸袭击，在事故中失去了记忆，而托特也因此与其断了联系。\n直到最近——她才终于又收到了那个人的来信，面对着信纸上熟悉的笔记，托特的嘴角掠过一丝若有似无的微笑。\n「这次，我该说好久不见，还是初次见面呢？」",
		heart_chain1 = "托特，前科尔盖安全中心主任，现任重大犯罪对策部特别行动队长。\n然而，大部分人在初次见到这位清秀的少女时，都很难将她与这些头衔联系起来。只要有需要，托特会最大程度收敛自己的真实身份和性格。\n在此之上，她伪装出的虚假性格，则因人因事而异：可爱清纯的，妩媚轻佻的，优雅高洁的，冷酷无情的；善人或是恶徒，羔羊或是屠夫。\n她会凭借自己的判断，「扮演」出最利于推进计划的性格。正因如此，不同的人对她的第一印象各不相同，这更为她在众人眼中的形象增添一层神秘。\n在工作之外的大部分时间里，托特所展现出的形象，是一位气质含蓄内敛的少女。优雅温柔，脸上总是挂着礼貌的微笑——这想必能为她的日常生活提供不少便利。\n至于她内心深处的「真实性格」究竟为何，恐怕连她自己都已分辨不清。\n",
		plot_tip = "最近感觉有些灵感枯竭……管理员，陪我来一场约会怎么样？",
		cv_ko = "김율",
		like = "阅读、看艺术展",
		super_plot_tip = "最近有时间吗，管理员？我想和你来一场……私人旅行。",
		plot_tip_picture = "1095",
		cv_en = "Aria Saltini",
		age_en = "",
		cv_zh = "云鹤追",
		cv_ja = "立花日菜",
		heart_chain2 = "托特出生于凯米特，因其早年显露出的聪颖天赋，进入墨兰德市福利学校学习。学校对外形象为福利性质的义务教育机构，实则为科尔盖科研中心的预备役培养基地。\n成绩最优异的十几位成员，包括托特在内，进入了「幽灵班」学习。完成学业后，托特也以唯一毕业生的身份顺利进入科尔盖的科研中心，于帕拉凯瑟的指挥下工作。\n她并非从未对帕拉凯瑟的实验项目产生过怀疑，但渴求尊重与认可的心情却将那份疑问压下。\n直到半年后的一次实验中，明知风险的帕拉凯瑟依旧要求托特执行实验，在疑问如气球般膨胀之际，托特觉醒为修正者，保护人类的使命感让这份疑惑转变为了否定。\n她收集了这项实验的所有风险数据向上层报告，使得实验被迅速叫停，但她也就此失去了帕拉凯瑟的信任。\n最终在卡玛乌的主张下，托特调职进入科尔盖信息安全中心。\n托特进入信息安全中心后，帮助科尔盖处理了许多棘手的事件，一路升任至安全中心主任，也借着职权的便利不断收集关于科尔盖、其他修正者阵营以及盖亚世界的信息。\n但坐镇后方总有其局限性，她逐渐产生了前往一线收集第一手情报、接触外部修正者的想法，凭着这段时间在信息安全中心的布局，即便她不继续担任信息安全中心主任，情报与信息也会源源不绝的涌入耳中。\n也是在这段时间，红狐对帕拉凯瑟的行动愈加不放心，希望能够在重大犯罪对策部安排眼线，与卡玛乌进行讨论后，卡玛乌推荐了托特来担当此任。\n红狐与托特说明此事后，两人一拍即合，托特随即加入重大犯罪对策部门，成立重大犯罪部门特别行动队。\n",
		organization = "科尔盖",
		heart_chain4 = "灰塔落成的时候，托特曾答应帕拉凯瑟为她的实验品进行训练，用以检测人造修正者的各项指标，同时也作为科尔盖的人员储备。\n想要成为合格的行动专员，这些人造修正者们必须对战场上的一切可利用的事物都了若指掌。\n偶尔托特在教授时使用了某些譬喻，她的「学员」都会露出难以用他们掌握的常识理解的表情。这时托特通常会拿他们能接触到的东西举例，才勉强得以将教学继续下去。\n「好漂亮……我记得老师讲过这个，说它就像天空的颜色。」\n「老师，『天空』是什么？」\n托特愣了一下，却又不知道怎么回答。她只注意到，学员们浅青的统一制服正是拂晓时天空常有的色彩。\n安静的教室里，只有监测仪器发出周期性的低声嗡鸣，提示托特既不能透露太多，也不能长久地保持沉默。\n「你们总有一天会见到的。天空不远，就和它一样——伸手就能抓到。」托特看向那个玻璃容器，里面的物质也散发着蔚蓝的光。\n「可是……如果太用力的话，它会破掉……还是放在罐子里就好了！」\n托特并不知道该怎么接下那些「生命」的发言，对她来说，这只是工作。课程继续，但来听的学生却越来越少。\n三年之后，灰色的建筑轰然倒塌，托特站在旧址上抬头仰望。天空晦暗无比，从被撕扯开的伤口处透出几缕光来。\n那一小片蔚蓝而致密的天空，至此只存在于托特模糊的梦里。",
		heart_chain3 = "虽然任职于重大犯罪对策部，但整日与情报和罪犯打交道的托特，并不认为这些冰冷的工作该是自己生活的全部。\n业余时间里，托特有阅读的爱好，她所喜好的书目以诗歌和史籍居多。从某种角度上说，这也为她百变的性格提供了诸多可参考的原型。\n作为某个线上读书俱乐部的活跃成员，托特经常组织读书活动。各类艺术展览中，也常有托特的身影。\n她能够敏锐地洞察到俱乐部成员的书评背后隐藏的情绪，以及艺术作品背后所含有的创作者的思考，有时甚至能因此掌握一些不为人知的情报。\n最初，她是出于任务需要，才开始阅读和逛艺术展。而如今，这些曾被她视为无聊的任务目标的东西，已成为她不可割舍的爱好。\n「等什么时候我不干了，可能会住到欧莫菲斯去吧。可惜啊，现在还不行~」",
