	[1096] = {
		birthday = "10月9日",
		height = "168cm",
		name = "赫尔墨斯",
		id = 1096,
		heart_chain5 = "作为优秀快递员，赫尔墨斯还掌握着许多一般人都不知道的神奇技能，比如说走过一遍的路闭着眼睛都不会走错、记得大街小巷全部的门牌号排列以及对应的商铺，这些技能让她成为了像是活地图一样的存在，若是想找一家店，问赫尔墨斯准没错。\n这不仅和她去过各式各样的地方有关，更因为赫尔墨斯好的出奇的记忆力。不知道是不是因为酷爱益智游戏的缘故，反正空暇的时候见到赫尔墨斯，她总是在对着数独纸算算写写的。按照本人的说法，脑子的速度和奔跑的速度同样重要。\n「你要不要也来试一下，很有趣的！」",
		heart_chain1 = "超级明星快递员赫尔墨斯，今天也为您服务。\n说到工作，赫尔墨斯在深空之眼当中也算是一个特例。虽然也会帮助进行视骸的清除工作，不过她并没有加入深空之眼，而是在一家名为「奥林匹亚速运」的快递公司工作。身为创办者团队的一员，赫尔墨斯坚持和伙伴们一起，每天都致力于将寄托在包裹上的「希望」送往世界各地。\n聪明可靠，做事认真，再加上阳光爽朗的笑容，赫尔墨斯不管是在公司内部还是客户群里都有着极高的人气。一度被社会评为「光荣劳动模范」之类的候选人，也是奥林匹亚速运公司的年度明星职员。",
		plot_tip = "管理员，要不要体验一下明星快递员的配送呢？嗯？当·然·是，用管理员的身体来体验啦~",
		cv_ko = "손선영",
		like = "益智游戏",
		super_plot_tip = "",
		plot_tip_picture = "1096",
		cv_en = "Abby Espiritu",
		age_en = "",
		cv_zh = "吱毛",
		cv_ja = "和气杏未",
		heart_chain2 = "说起「奥林匹亚速运」的发展过程，赫尔墨斯大概能喋喋不休地和你说上一天一夜……或许中间还能送几个快件。\n这家新型企业能在数年内打败同行业的竞争对手，一跃成为诺伊汉萨区的物流龙头，同时在多个原质区开设分部，除了投资者的帮助，和公司的信念以及优质的服务也是密不可分的。这也是让赫尔墨斯颇为自豪的一点，每每讲到这里都要挺起胸膛。\n而她本人更是提供优质服务的佼佼者，在腿部装甲的帮助下，赫尔墨斯派送快件的效率在业内是绝对的顶尖水准，若是偶尔在城里遇到突然刮起的旋风，说不定就是你刚好和赫尔墨斯擦肩而过。",
		organization = "奥林匹亚物流",
		heart_chain4 = "「小赫是我们最好的伙伴哦！啊哈哈，不如说，大家能像现在这样一起也是多亏了她呢。」\n在赫尔墨斯的伙伴处，听到了更多关于赫尔墨斯的事迹。据说在当时还未成立快递代取业务的时候，就读于工程大学的社长就已经为赫尔墨斯制造了一套粗糙的腿部辅助装甲，虽然简陋，但能让赫尔墨斯下地行走已经让众人非常欣喜了。可是启动用的高纯度电晶石价格相当昂贵，为此大家一直在瞒着赫尔墨斯偷偷打工赚钱。\n在一次前往销售电晶石的大型黑市时，众人恰巧遇上集装箱倾泻的事故。此时悄悄跟来的赫尔墨斯看到了这一幕，她不顾一切地冲向伙伴们，修正者的意识也在此刻觉醒，以「不可思议」的速度救下了他们。然后这件事却从未听赫尔墨斯本人提过。\n「嗯？这不是理所应当的事嘛，帮助伙伴的时候哪里顾得了那么多嘛！」\n求证的时候，被她这样子爽朗地糊弄了过去。",
		heart_chain3 = "但是谁又能想象这家物流龙头企业的前身，只是一个甚至连企业都算不上的「快递代取」的业务，而彼时的赫尔墨斯，也还并没有觉醒修正者的力量。\n据赫尔墨斯说，在她小时候曾经经历过一次严重的交通事故，导致了双腿残疾，只能依靠轮椅活动。一度对生活失去希望的赫尔墨斯在那时遇到了现在的伙伴们，他们积极地帮助赫尔墨斯走出了事故的阴影，并帮助她打造了最初的腿部装甲，让她再次成功站了起来。\n对于这些无可替代的伙伴们，赫尔墨斯即使在成为修正者后，也没有接受深空之眼的邀请，而是选择继续和已经毕业的伙伴们发展快递业务，直到它得到注资，成为现在的奥林匹亚速运。\n「谢谢你们的邀请，但是抱歉啦，我不想辜负伙伴们的心意~」",
