	[1097] = {
		birthday = "11月9日",
		height = "139cm",
		name = "俄尼里伊",
		id = 1097,
		heart_chain5 = "闲暇时候，又恰巧不在睡觉的俄尼里伊会帮忙招待缪斯协会的考证人员，据说她的发证率是最高的。\n不过这种情况是极为少见，大多数时候俄尼里伊都只是躺在自己房间的床上睡觉。在她迷幻的梦中世界里，牛角门飞出真实之梦，象牙门飞出虚无之梦，虚构的原野外是无尽璀璨的虚空，而俄尼里伊在快乐地追逐着小困。\n「醒了，但是又困了……呼啊……这次会做什么样的梦呢？……zzzzz」",
		heart_chain1 = "在深空之眼，不少修正者对俄尼里伊的能力抱有好奇心，传闻再严重的失眠症患者也能在她的能力作用下安然入睡。但是俄尼里伊仅仅在受邀维护梦境装置时才会在总部出现，届时想要睡个好梦的修正者们都不会放弃这个机会。\n不过，最期待俄尼里伊到来的并不是那些想要偷懒的修正者，反而是一向以工作狂著称的休。毕竟即便是休那种因为大量工作积压和长期饮用咖啡而导致的严重失眠症，也能在俄尼里伊的能力下奇迹般地得到缓解。",
		plot_tip = "大人的梦，是什么颜色呢？",
		cv_ko = "문유정",
		like = "抱枕、睡觉",
		super_plot_tip = "",
		plot_tip_picture = "1097",
		cv_en = "Suzie Yeung",
		age_en = "",
		cv_zh = "闲踏梧桐",
		cv_ja = "长绳麻理亚",
		heart_chain2 = "俄尼里伊的能力在她诞生之初闹过不少麻烦——在欧莫菲斯曾经有过这样一个怪谈：很多人会在毫无困意的情况下忽然睡着，睡醒后说自己做了一个古怪的梦，在梦中有一个可爱的小孩缠着他们玩捉迷藏。\n哈迪斯正是因为这样诡异的都市传说注意到了俄尼里伊的存在，她将俄尼里伊带回了缪斯协会，经过研究，她发现俄尼里伊的神力会使她在陷入沉睡时不自觉地将周围人拉入她的梦境。",
		organization = "缪斯协会",
		heart_chain4 = "在缪斯协会的日子里，俄尼里伊耳濡目染，接触了一些艺术基础，而后迅速展现出了极强的艺术天赋。她后来凭借一作《白夜伊梦》入选千星学院进行学习，一举获得「神童」的称号，在欧莫菲斯轰动一时。不过或许是没法振作精神去练习，加上本身也对绘画没有强烈的热爱，入学后的俄尼里伊再没有佳作问世，甚至连基本的课堂作业也不堪入目。\n她将绘图看作是梦境的转述，而其中的内容只需要达意即可。当她的画作不再精彩了，或许也是因为她已经很久没做过让自己流连忘返的美梦了。\n这番表现让不少人以为她是凭着哈迪斯的首席议员关系入学的，不过缪斯协会的人对这些言论不加理会。",
		heart_chain3 = "哈迪斯尝试过主动被俄尼里伊带入梦境世界，她在醒来后说，俄尼里伊在梦境中拥有绝对的力量，并且可以将部分梦境里发生的事以一种微妙的形式转化为真实，只不过这能力还很微弱。\n虽然这孩子的能力非常危险，但好在她本身性格乖巧，乖巧到对哈迪斯几乎言听计从，所以哈迪斯就将她暂时收留在缪斯协会，交由「明塔」和「琉刻」照顾。\n这是无奈之举，因为身为傀儡人偶的「明塔」和「琉刻」不会被俄尼里伊的梦境催眠，整个协会只有她们能当这孩子的保姆。不过可喜的是，俄尼里伊在哈迪斯的收留下不再引发「群梦」事件，同时也渐渐学会了控制她自己的能力。",
