		name = "月读",
		id = 1099,
		heart_chain5 = "师父，队友，伙伴……月读的身份在不断的增加，这代表着与她牵连的羁绊也越来越多，在意识到这一点后，月读陷入了更深的迷惘中。她并不是冷血之人，然而心中的阴影让她无法接受再有其他人因为自己的过错而离开，最好的办法就是在那一天到来之前，先由自己斩断这份牵绊。\n可另一方面来说，月读在他人看来，是优秀的队长、严格的师父、可靠的队友……她也承载着无数其他人的信赖。月读重视每一个伙伴，自然也不想轻易就辜负了他们的期待。或许关于「心」的答案，她还要找上很久。\n「我并非不再迷茫……」",
		heart_chain1 = "月读，雉小队的队长，在深空之眼中也是相当优秀的修正者，不论是单独作战还是带领小队期间，只要是月读负责的任务，都有着惊人的完成率。强大的实力来源于月读对自己的严格要求，以及在旁人看来严苛到过分的训练。若是不在任务期间，你几乎只有在一个地方才能见到她——训练室，即使是夜深人静的时候，她也似乎不知疲倦般一遍又一遍地练习着自己的剑术。\n平时的月读就像凛冽的寒月一般，不怎么表露言辞，散发着生人勿近的气息。大多数的时候她都只是不发一语地忙于任务或者训练，然而敏锐的人会察觉到，她似乎只是想通过忙碌，让自己忘记什么事情。",
		plot_tip = "还记得我们在蛇家一同经历的作战吗？那次之后，震离似乎出了问题……管理员空闲的时候可以来一趟训练场吗？我随时都在。",
		cv_ko = "김율",
		like = "照顾植物、下棋",
		super_plot_tip = "管理员，欢迎来到笹波。有兴趣体验一下笹波两大名产——剑道和温泉吗？",
		plot_tip_picture = "1099",
		cv_en = "Ami Okumura Jones",
		age_en = "",
		cv_zh = "蟲蟲",
		cv_ja = "石川由依",
		heart_chain2 = "据说在月读还没加入深空之眼前，一直生活在笹波区的某处，但却少有人听她提起自己的过往。即便是同队的国常立与丰前坊，也对此完全没有耳闻，只是偶尔会见到那个坚强可靠的队长看向不知何方的天空，眼神中流露出一丝转瞬即逝的迷惘。\n「她在找一个人。」\n虽然不知道奥丁醉醺醺的话语有几分可信度，但月读一些行为似乎也印证着这一说法，然而具体如何，或许也只有月读自己最清楚。\n她早已不记得是何时来到深空之眼的，但是为何来到这里的原因，她却不曾忘记。看向照片中的自己，以及那个站在背后的身影，月读明白，自己还不能停下前进的脚步。",
		organization = "深空之眼",
		heart_chain4 = "「我不会让她成为下一个我。」\n对于自己收下的弟子丰前坊，最开始月读只是抱着想要引导的态度，在认可了丰前坊的剑心之后，才决定帮助她走出阴霾。随后的几年中，月读极尽所能地用心教导丰前坊。而丰前坊也认定了月读这位师父，并且对她的感激之情日益增加，认真地完成每一个要求，以图能报答月读的这份恩情。\n但在发现了丰前坊对自己的信赖后，月读产生了不安与动摇。她在害怕这份羁绊与信任，她害怕有一天弟子会重蹈自己的覆辙，被人心所困而陷入无尽的迷茫与伤痛当中，这也正是月读心魔的真相。她的追寻之路，大概也是自己的救赎之路。",
		heart_chain3 = "然而即便已经过去许久，关于月读想要寻找的人依旧没有任何线索。只是偶尔能听休提起，月读似乎又独自回了一趟笹波，站在三人的「家」前，往日的生活片段不断浮现，随后又宛若泡影般在眨眼间消散。再没有昔日的热闹温馨，现在被冰冷气息充斥的这里，只是一具空壳罢了。「家」如是，月读亦是如此。\n家人的离开，是不告而别，而月读将所有的错误都归结在了自己的身上，自然地想要承担起全部责任，却不曾想引发了更大的矛盾。为此，月读陷入了更深的自责之中，她把一切都埋藏在心里，不再与人提起。然而即便表现得再如何冷静，她的压抑与伤痛并不会因为沉默而减少半分。",
